NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'Matthew'

CHAPTERS = {
    1: {
        1: "Ya itu kapangkatan si Isa Al-Masi, panubu' si Da'ud ya panubu' si Ibrahim.",
        2: "Si Ibrahim bay mma' si Isa'ak, ya Isa'ak bay mma' si Yakub. Si Yakub bay mma' si Yuda maka saga danakanna,",
        3: "si Yuda bay mma' si Peres maka si Sera (si Tamar ya ina' sigām). Si Peres bay mma' si Hesdon, ya si Hesdon bay mma' si Aram.",
        4: "Si Aram bay mma' si Amminadab, ya Amminadab bay mma' si Nasson. Si Nasson bay mma' si Salmon,",
        5: "ya Salmon bay mma' si Bowas (si Rahab ya ina'na). Si Bowas bay mma' si Obed, ina'na bay si Rūt. Si Obed bay mma' si Jesse,",
        6: "ya Jesse bay mma' sultan Da'ud. Si Da'ud inān bay mma' si Sulayman, ina'na bay h'nda si Uriya.",
        7: "Si Sulayman bay mma' si Rehobowam, ya Rehobowam bay mma' si Abiya, ya Abiya bay mma' si Asa.",
        8: "Si Asa bay mma' si Josapat, ya Josapat bay mma' si Joram, ya Joram bay mma' si Usiya.",
        9: "Si Usiya bay mma' si Jotam, ya Jotam bay mma' si Ahas, ya Ahas bay mma' si Hijikiya.",
        10: "Si Hijikiya bay mma' si Manasse, ya si Manasse bay mma' si Amon, ya Amon bay mma' si Jusiya.",
        11: "Si Jusiya bay mma' si Jekoniya maka saga danakanna.",
        12: "Min waktu kapamowa bangsa Isra'il ni lahat Babilon sampay ni waktu kapaganak ma si Isa, buwattitu ya sugsuganna. Si Jekoniya inān bay mma' si Salati, ya Salati bay mma' si Sirubbabil.",
        13: "Si Sirubbabil bay mma' si Abiyud, ya Abiyud bay mma' si Eliyakim, ya Eliyakim bay mma' si Asor.",
        14: "Si Asor bay mma' si Sadok, ya Sadok bay mma' si Akim, ya Akim bay mma' si Eliyud.",
        15: "Si Eliyud bay mma' si Eleyasar, ya Eleyasar bay mma' si Mattan, ya Mattan bay mma' si Yakub.",
        16: "Si Yakub bay mma' si Yusup ya h'lla si Mariyam ina' si Isa, ya niōnan Al-Masi.",
        17: "Manjari aniya' sangpū' maka mpat pangkatan min si Ibrahim sampay ni si Da'ud, sangpū' maka mpat pangkatan min si Da'ud sampay ni waktu bay pamala'an saga a'a Isra'il ni Babilon, ati sangpū' maka mpat pangkatan isab minnē' sampay ni waktu kapaganak ma Al-Masi.",
        18: "Buwattitu ya kal'ngnganan kapanganak ma si Isa Al-Masi. Ina'na si Mariyam bay makapagbintak asal maka si Yusup, sagō' ma halam gi' sigā takawin tananam e' si Mariyam in iya angiram sabab min kawasa Rū Sussi.",
        19: "A'a adil asal si Yusup ya tunang si Mariyam e', angkan iya agara' pabaibad min iya ma halam aniya' makata'u. Mbal iya bilahi amuwanan si Mariyam kaiya'an ma mata mairan.",
        20: "Na, sabu pa'in si Yusup amikil-mikil pasal pakaradja'an itu, aniya' mala'ikat min Tuhan pauppi ni iya. Yuk mala'ikat, “O Yusup panubu' si Da'ud, da'a ka ahawal-hawal magdakayu' maka si Mariyam ilu, sabab min kawasa Rū Tuhan ya angkan aniya' kab'ttonganna.",
        21: "Anganak du iya l'lla, ati Isa ya pangōnnu ma iya sabab iya ya angalappas bangsana Isra'il min paldusahan sigām.”",
        22: "Na, pinat'kka saga pakaradja'an itu kamemon bo' aniya' katumanan ma bay pangallam Tuhan ma dakayu' nabi, ya yuk-i,",
        23: "“Aniya' inān budjang angiram, ati anganak iya l'lla, Emmanuwel ya pangōn sigām ma iya.” Hatina ‘Tuhan pat'nna' ma kitam.’",
        24: "Pagbati' pa'in si Yusup min uppina, bineya' e'na panoho'an mala'ikat ati pah'ndana si Mariyam.",
        25: "Sagō' subay na apuwas bay kapanganak si Mariyam bo' yampa sigā magpūn. Jari anganak si Mariyam l'lla ati Isa ya pangōn si Yusup ma iya.",
    },
    2: {
        1: "Si Isa bay nianakan ma kaluma'an Betlehem ma lahat Yahudiya, ma masa kapagsultan si Herod. Mbal at'ggol, aniya' saga a'a alim bay min sobangan at'kka pehē' ni Awrusalam. Saga a'a itu pangangadji' ma saga bitu'un.",
        2: "Pagt'kka sigām ni Awrusalam magtūy sigām atilaw, yuk-i, “Maingga na onde'-onde' bay nianakan, ya ginanta' magsultan ma bangsa Yahudi? Ta'nda' kami bitu'un ya pamandogahan iya, paluwa' min sobangan, jari itiya' kami pi'itu amudji iya.”",
        3: "Pagkale itu e' Sultan Herod, magtūy landu' asasaw pikilanna. Sampay saga a'a kamemon ma deyom da'ira inān magkasasawan du isab.",
        4: "Magpanoho'an si Herod subay magtipun saga nakura' kaimaman maka saga guru sara' agama. Atilaw iya ma sigām, yukna, “Maingga kono' panganakan Al-Masi?”",
        5: "Anambung saga a'a inān, yuk-i, “Ma kaluma'an Betlehem, ma lahat Yahudiya, sabab tasulat asal e' nabi ma deyom Kitab, ya yuk-i:",
        6: "‘In kauman Betlehem, ya ma lahat Yahudiya, aheya kabantuganna min saga da'ira babantugun ma lahat Yahudiya, sabab aniya' palahil minnē' dakayu' a'a magmakōk, a'a angupiksa' saga a'aku bangsa Isra'il!’”",
        7: "Puwas e' pinalinganan e' sultan Herod saga a'a alim e', binowa magbissala ma halam aniya' makata'u. Tinilaw sigām e'na bang sumiyan waktu bay kasobang bitu'un.",
        8: "Kahaka'an pa'in sultan, pinapehē' sigām ni Betlehem. Buwattitu panoho'anna ma sigām, yuk-i, “Pehē' kam, piha'unbi to'ongan onde'-onde' inān. Bang iya tabākbi, pata'uhunbi aku supaya aku isab pehē' amudji iya.”",
        9: "Aubus pa'in sigām binissalahan e' sultan, palanjal na sigām tudju ni Betlehem. Ma labayan pa'in, parahū min sigām bitu'un ya bay ta'nda' sigām ma lahat sobangan lagi'. Pag'nda' itu, landu' aheya kakōgan sigām. Jari patongod bitu'un inān min diyata' luma' ya pat'nna'an onde'.",
        10: "Aubus pa'in sigām binissalahan e' sultan, palanjal na sigām tudju ni Betlehem. Ma labayan pa'in, parahū min sigām bitu'un ya bay ta'nda' sigām ma lahat sobangan lagi'. Pag'nda' itu, landu' aheya kakōgan sigām. Jari patongod bitu'un inān min diyata' luma' ya pat'nna'an onde'.",
        11: "Makasōd pa'in saga a'a alim inān ni deyom luma', ta'nda' e' sigām onde'-onde' maka ina'na si Mariyam. Jari pasujud sigām amudji iya, maka pinaluwas isab saga huhulmatan bay bowa sigām pamuwan ma onde' inān. Aniya' bulawan, kamanyan, maka pahamut mira.",
        12: "Puwas e' binanda'an sigām e' Tuhan ma deyom uppi, sinō' da'a pabalik ni si Herod. Manjari amole' sigām ni lahat labay min lān saddī.",
        13: "Pagla'an sigām, aniya' mala'ikat min Tuhan magpanyata' ni si Yusup ma deyom uppi. Yuk mala'ikat, “Punduk ka. Bowahun onde' maka ina'na ilu ati alahi kam ni lahat Misil. Mahē' gi' kam sat'ggol kam mbal pala'anku minnē'. Ilu si Herod amiha onde' ilu pinapatay.”",
        14: "Magtūy punduk si Yusup. Niā' e'na onde' maka ina'na bo' sigām pauntas minnē' tudju ni lahat Misil ma sangom du inān.",
        15: "Mahē' sigām sampay amatay si Herod. Jari aniya' kamaksuran ma bay pangallam Tuhan, ya tasulat ma Kitab e' nabi Hoseya. Yukna, “Bay soho'ku anakku pi'itu min lahat Misil.”",
        16: "Pagta'u pa'in e' si Herod in iya bay niakkalan he' saga a'a alim e', apasu' to'ongan atayna. Magtūy iya magpanoho'an pinapatay saga onde'-onde' l'lla kamemon ma Betlehem sampay ma sakalibutna, sasuku angumul duwantahun sampay pareyo' gi' minnē'. Binista e' si Herod umul saga onde' inān tinagna'an min waktu bay pamata'u iya e' saga a'a alim pasal waktu katuwa' bitu'un.",
        17: "Minnē' aniya' kamaksuran ma bay tasulat e' nabi Irimiya, ya yukna,",
        18: "“Aniya' lengog takale ma lahat Rama, lengog a'a magkarukka'an maka maglemong. Si Rakiya anangisan saga anakna. Mbal tapahali paglemongna, sabab wa'i pinapatay anakna kamemon.”",
        19: "Amatay pa'in si Herod, aniya' mala'ikat min Tuhan bay pauppi ni si Yusup mahē' ma lahat Misil.",
        20: "Yuk mala'ikat, “Punduk ka. Bowahun onde' maka ina'na pabalik ni lahat Isra'il, sabab magpatayan na saga a'a bilahi amapatay onde' ilu.”",
        21: "Sakali pabangun si Yusup. Binowa e'na onde' maka ina'na pabalik ni lahat Isra'il.",
        22: "Pagta'u pa'in e' si Yusup in si Arkilas paganti' na min mma'na si Herod magsultan ma lahat Yahudiya, atāw iya palahat maina'an. Binanda'an iya pabalik ma deyom uppi, ya angkan sigām magtai'anak pehē' ni lahat Jalil",
        23: "bo' pat'nna' ma kaluma'an niōnan Nasaret. Jari aniya' kamaksuran ma bay pinagkallam e' saga kanabihan pasal Al-Masi, ya yuk-i, “Niōnan iya a'a Nasaret.”",
    },
    3: {
        1: "Manjari ma waktu he'-i at'kka si Yahiya Magpapandi pehē' ni paslangan Yahudiya magnasihat.",
        2: "Yuk nasihatna ni saga a'a bay patimuk pina'an, “Pataikut kam min dusabi sabab asekot na waktu kapagparinta Tuhan ma kitam.”",
        3: "Si Yahiya itu bay pinagbissala asal e' nabi Isaya, yuk-i, “Aniya' a'a angalingan ma lahat paslangan, yukna, ‘Lanu'inbi lān ya palabayan Panghū'. Pabontolunbi pal'ngngananna.’”",
        4: "Ya pas'mmek si Yahiya inān kakana' hinangan bulbul unta', maka dakayu' sabitan kuwit sapi' pakambot ma hawakanna. Ya pagkakanna ampan maka gula' buwani.",
        5: "Na, pehē' ni si Yahiya saga a'a min da'ira Awrusalam, min kaluha'an lahat Yahudiya, maka min saga kaluma'an ma karuwambila' sapa' Jordan.",
        6: "Magpasab'nnal sigām pasal bay dusa sigām, ati pinandi sigām e' si Yahiya ma sapa' Jordan e'.",
        7: "Sagō' pag'nda' si Yahiya ma ba'anan a'a Parisi maka a'a Saddusi pina'an ni iya mikipandi, yukna ni sigām, “Ē, ka'am ilu, addatbi sapantun sowa pangangakkal! Sai bahā' bay amanda'an ka'am subay papuwas min mulka' Tuhan ya song pat'kka?",
        8: "Bang kam sab'nnal-b'nnal pataikut na min dusabi, hinangunbi hinang ahāp, palsaksi'an in addatbi apinda na.",
        9: "Da'a kam magpikil in ka'am mbal minulka'an saukat na kam panubu' si Ibrahim. Haka'anta kam, minsan saga batu itu tahinang du panubu' si Ibrahim e' Tuhan!",
        10: "Ka'am ilu hantang saga kayu arai' na pinuwad maka kapa, tobtob min po'onna. Sabab kayu kamemon mbal ahāp buwa'na pinuwad du, nilarukan ni deyom api tinunu'.",
        11: "Aku itu,” yuk si Yahiya, “hal bohe' ya pamandiku ka'am, tanda' saksi' in ka'am pataikut min dusabi. Sagō' aniya' pi'itu damuli min aku aheya gi' kawasana min kawasaku. Minsan hal taumpa'na mbal aku tinōp amenten. Saddī bowahan pamandina ma ka'am, sabab in iya amahōp Rū Sussi ni deyom baranbi. Saga a'a kasehe' isab pinandi e'na maka api.",
        12: "Sinilang du e'na a'a ahāp maka a'a ala'at, buwat sapantun a'a anahapan pai. Ya paina tinau' ma deyom tau'anna, saguwā' hampa'na tinunu' e'na ma api mbal kap'ddahan.”",
        13: "Jari itu, ma waktu he'-i, at'kka si Isa min lahat Jalil pina'an ni sapa' Jordan, bo' mikipandi ma si Yahiya.",
        14: "Sagō' mbal bilahi si Yahiya. Yukna ni si Isa, “Angay ka mikipandi ma aku? Aku itu subay pandinu!”",
        15: "Saguwā' anambung si Isa, yukna, “Hinangun na ma waktu itu, sabab patut du bang beya'ta panoho'an Tuhan kamemon.” Jari pasulut si Yahiya ma si Isa.",
        16: "Aubus pa'in si Isa bay pinandi, pariyata' na iya min deyom bohe'. Sakali paukab langit, ati ta'nda'na Rū Tuhan sali' luwa assang pareyo' minnē' pat'ppak ma iya.",
        17: "Aniya' isab suwala ah'lling min deyom sulga' yuk-i, “Iya na itu Anakku kalasahanku, landu' makasulut atayku.”",
    },
    4: {
        1: "Manjari si Isa inān binowa e' Rū Tuhan kaleya ni lahat paslangan, ati sinasat iya e' nakura' saitan, kalu tabowa magdusa.",
        2: "Halam bay makatimtim si Isa ai-ai ma deyom mpatpū' ng'llaw maka mpatpū' bahangi. Puwas e' landu' iya lingantu,",
        3: "jari pehē' ni iya nakura' saitan, ya mananasat, yukna, “Bang ka sab'nnal-b'nnal Anak Tuhan, soho'un saga batu itu papinda ni tinapay.”",
        4: "Sagō' anambung si Isa, yukna, “Tasulat asal ma Kitab Tawrat, ya yuk-i, ‘Ngga'i ka hal kinakan baran ya makakallum ma manusiya', saguwā' lapal kamemon ya binissala e' Tuhan.’”",
        5: "Puwas e' binowa si Isa e' nakura' saitan ni da'ira Awrusalam, ya niōnan Da'ira Mahasussi, ati pinatongod iya ma puttuk langgal pagkulbanan ya maina'an.",
        6: "Yuk saitan, “Bang ka sab'nnal-b'nnal Anak Tuhan, pakuppa ka minnilu, sabab tasulat asal ma Kitab Jabul, ya yuk-i, ‘Aniya' mala'ikat sinoho' e' Tuhan angahampanan ka'a. Tinayak ka e' sigām bo' mbal makahantak tape'nu ni batu.’”",
        7: "Yuk si Isa, “Tasulat isab buwattitu: ‘Da'a sulayinbi kawasa Panghū'bi Tuhan.’”",
        8: "Puwas e' binowa si Isa e' nakura' saitan ni diyata' būd alanga to'ongan, bo' yampa pina'nda'an lahat kamemon ma kaluha'an dunya, maka kawasa saga a'a ya magnakura'an kalahat-lahatan inān.",
        9: "Yuk nakura' saitan ni si Isa, “Bang ka pasujud ma aku amudji, pamuwanku ina'an kamemon ma ka'a.”",
        10: "Ya sambung si Isa ni iya, “Ala'an ka, saitan! Sabab tasulat asal ma Kitab Tawrat, yuk-i, ‘Panghū'bi Tuhan sadja ya subay pudjibi. Tunggal iya paghinanganbi!’”",
        11: "Puwas e' ala'an nakura' saitan min si Isa, ati aniya' saga mala'ikat pina'an ni si Isa angayura iya.",
        12: "Manjari pagkale e' si Isa in si Yahiya Magpapandi wa'i bay takalabusu, pehē' iya ni lahat Jalil.",
        13: "Ala'an iya min kauman Nasaret, bo' pat'nna' ma da'ira Kapirnaum ya ina'an ma bihing danaw Jalil, ma paglahat Sibulun maka Naptali.",
        14: "Jari aniya' kamaksuran ma bay tasulat e' si Isaya, ya yuk-i,",
        15: "“Lahat Sibulun maka lahat Naptali, ya ma llot sapa' Jordan maka tahik s'ddopan, lahat Jalil, ya kalamugayan bangsa ngga'i ka Yahudi.",
        16: "Saga a'a bay hantang pat'nna' ma deyom kalendoman, maka'nda' kasawahan landu' asahaya. Saga a'a bay kalokoban e' kamatay, taluwa' kasawahan.”",
        17: "Tinagna'an minnē' magnasihat na si Isa, yuk-i, “Taikutinbi na dusabi sabab asekot na waktu kapagparinta Tuhan ma ka'am.”",
        18: "Na, hinabu si Isa lum'ngngan ma bihing danaw Jalil, aniya' ta'nda'na duwangan magdanakan. Dakayu' inān si Simun, ya niōnan isab si Petros. Dakayu' inān si Andariyas. Ina'an sigā angahūg pokot ma danaw, sabab magdaraing asal sigā.",
        19: "Jari ah'lling si Isa ni sigā, yukna, “Pi'itu kam ameya' ma aku. Bay kam asal magā' daing, sagō' pandu'anta kam magā' pagkahibi manusiya' ameya' ma aku.”",
        20: "Takale pa'in lling si Isa e' duwangan itu, magtūy ni'bbahan pokot sigā bo' yampa ameya' ma iya.",
        21: "Makalanjal pa'in si Isa minnē', aniya' isab ta'nda'na duwangan magdanakan, si Yakub maka si Yahiya, anak si Sibidi. Ina'an sigā ma diyata' bayanan magbeya' maka mma' sigā amahāp pokot. Nilinganan e' si Isa duwangan itu, sinō' ameya' ma iya.",
        22: "Magtūy ni'bbahan mma' sigā maka bayanan, bo' ameya' ma si Isa.",
        23: "Na, nilatag e' si Isa kaluha'an lahat Jalil inān. Amandu' na pa'in iya ma deyom kalanggalan. Magnasihat iya lapal ahāp pasal kapagparinta Tuhan ma manusiya'. Kauli'an e'na saga a'a kamemon ya taluwa' saki maka kalammahan indaginis.",
        24: "Jari pasaplag kabantuganna ni kaluha'an lahat Siriya. Angkan saga a'a maina'an bay amowa pagkahi sigām ni si Isa, sai-sai kap'ddi'an atawa taluwa' saki indaginis, saga a'a sinōd saitan, a'a binawi-bawi, maka a'a amatay ugat sigām. Kauli'an sigām kamemon e' si Isa.",
        25: "Jari landu' aheka saga a'a bay paturul ma iya, a'a min lahat Jalil maka min Sangpū' Da'ira. Aniya' isab saga a'a min da'ira Awrusalam, min kaluha'an lahat Yahudiya, sampay min dambila' sapa' Jordan.",
    },
    5: {
        1: "Manjari pag'nda' pa'in si Isa ma manusiya' sikatimukan inān, patukad iya ni bīd bo' aningkō' mahē'. Pina'an ni iya saga mulidna,",
        2: "ati anagna' iya amandu' ma sigām, yuk-i,",
        3: "“Aheya kahāpan ma sasuku kata'uwanna halam aniya' pasangdolanna saddī min Tuhan, sabab tantu aniya' okomanna ma pagparintahan Tuhan.",
        4: "Aheya kahāpan sasuku magkarukka'an, sabab pinahantap pangatayanna e' Tuhan.",
        5: "Aheya kahāpan sasuku areyo' pangatayanna, sabab makataima' iya pusaka' min Tuhan.",
        6: "Aheya kahāpan sasuku magmatayan itikad abontol, sabab karūlan iya e' Tuhan.",
        7: "Aheya kahāpan sasuku ma'ase' ma kasehe'anna, sabab ya du iya kina'ase'an e' Tuhan.",
        8: "Aheya kahāpan sasuku apote' atayna tudju ni Tuhan, sabab makapag'nda' du iya maka Tuhan.",
        9: 'Aheya isab kahāpan sasuku amapagsulut ma saga pagkahina, sabab kaōnan iya anak Tuhan.',
        10: "Aheya isab kahāpan sasuku nila'at ma sabab pameya'na ma kabaya'an Tuhan, sabab aniya' okomanna ma pagparintahan Tuhan.",
        11: "“Aheya isab kahāpanbi bang kam ganta' niudju' maka pininjala', maka bang kam nilimut ngga'i ka b'nnal ma sabab pameya'bi ma aku.",
        12: "Subay kam akōd to'ongan bang buwattē', sabab tantu du aheya tungbasbi ma deyom sulga'. Buwattē' isab bay paminjala' ma saga nabi ya bay ma dunya itu ma masa awal e'.”",
        13: "Amandu' lagi' si Isa, yuk-i, “Ka'am bebeya'anku dalil asin ma bangsa manusiya'. Sagō' bang asin itu magtinu' na, halam aniya' pamabalik nanamna. Halam aniya' kagunahanna, hal tinimanan bo' pinaggi'ikan e' a'a.",
        14: "“Ka'am ilu dalil sawa pamasawa bangsa manusiya'. Bang aniya' kaluma'an pat'nna' ma diyata' būd, ta'nda'an di-na du.",
        15: "Halam aniya' anū'an palita'an bo' turunganna maka undam, sagō' pinat'nna' ma diyata' pat'nna'anna bo' amuwan sawa ma sasuku ma deyom luma'.",
        16: "Buwattē' du isab kam, subay kam amuwan sawa ma pagkahibi manusiya'. Hatina subay ta'nda' kahinanganbi ahāp e' a'a kasehe', bo' sigām tabowa ananglitan Mma'bi ma sulga'.”",
        17: "“Da'a kam maghimangkan saga aku pi'itu amapasan sara' ya bay pang'bba e' si Musa, maka pandu' bay min kanabi-nabihan. Ya gawiku pi'itu subay pahatiku pasal sara' he' bang ai kamaksuranna to'ongan.",
        18: "Haka'anta kam to'ongan: sat'ggol masi langit maka dunya itu, halam du aniya' kinulangan min sara' itu minsan la'a hal dambatang sulatna maka balisna. Subay asampulna' kamemon bo' yampa pahalam kapūsanna.",
        19: "Angkan sai-sai angalanggal sara' itu minsan la'a hal ma kariki'an, maka bang bidjakanna sehe'na ameya' ma iya angalanggal, a'a inān areyo' to'ongan ma deyom pagparintahan Tuhan. Sagō' sai-sai ya ameya' ma sara' sampay amandu'an sehe'na subay ameya', alanga du iya ma deyom pagparintahan Tuhan.",
        20: "Sagō' haka'anta kam, mbal kam makasōd ni deyom pagparintahan Tuhan bang mbal palabi ka'adilanbi min ka'adilan saga Parisi maka saga guru sara' agama.”",
        21: "“Bay na takalebi panoho'an ma saga a'a ma masa awal e', ya yuk-i, ‘Wajib kam da'a amapatay pagkahibi manusiya'. Sai-sai amapatay pagkahina pinat'nna'an hukuman.’",
        22: "Sagō' buwattitu na pamandu'ku ma ka'am: sai-sai angastol ma pagkahina subay nihukum. Maka sai-sai angōn ‘dupang’ ma sehe'na subay binowa ni Tumpukan Maghuhukum. Sai-sai isab amah'llingan pagkahina, yukna, ‘Ē! Babbal ka! Halam aniya' pūsnu!’ Piligdu a'a inān pinalabay min api nalka'.",
        23: "Angkanna, bang ka ganta' ma deyom langgal song anukbal ai-ai ni Tuhan, bo' taentomnu aniya' pagkahinu ap'ddi' atayna ma ka'a,",
        24: "mailuhun lagi' panukbalnu ati pasa'ut ka ni pagkahinu inān maghāp maka iya dahū bo' yampa ka pabīng angungsuran panukbalnu ni Tuhan.",
        25: "“Abila ka tinuntutan e' a'a bo' tin'kkahan ni sara', bowahun iya magsulut ma halam gi' makatampal ni sara'. Sabab bang kam mbal magsulut dahū, tin'kkahan ka ni huwis, ati ni'nde'an ka e' huwis ni saga pulis bo' ni'isi ni deyom kalabusu.",
        26: "Jari ka'ddasan ka maina'an. Subay puwasannu bay kataksilannu kamemon bo' yampa ka makaluwas minnē'.”",
        27: "“Bay na takalebi panoho'an ītu, ya yuk-i, ‘Wajib kam da'a angaliyu-lakad ni ngga'i ka paghola'bi.’",
        28: "Sagō' buwattitu na pamandu'ku ma ka'am: sai-sai ang'nda' ni d'nda maka e'na anganapsuhan iya, a'a inān katōngan dusa sabab makalandu' na iya angandusa ni d'nda he' ma deyom pikilanna.",
        29: "Bang matanu kowan ganta' amowa ka'a magdusa, subay paggatun. Gom lagi' lugitnu matanu ilu bo' tinimanan. Ahāp lagi' abuta matanu dambila', bang pa'in da'a nilarukan katibu'ukannu ni deyom nalka' ma ajukup matanu karuwambila'.",
        30: "Damikiyanna isab bang tangannu kowan ganta' amowa ka'a magdusa, paggatun. Gom lagi' pinukulan dambila' tangannu bo' tinimanan. Ahāp lagi' apukul dambila' tangannu, bang pa'in da'a nilarukan katibu'ukannu ni deyom nalka' ma ajukup tangannu karuwambila'.”",
        31: "“Aniya' isab bay panoho'an sara', ya yuk-i, ‘Sai-sai animanan h'ndana subay iya amuwan pagpasahan.’",
        32: "Sagō' buwattitu na pamandu'ku ma ka'am: sai-sai animanan h'ndana ma halam aniya' sababanna, ma halam du bay angaliyu-lakad min iya, taga-dusa l'lla inān ma h'ndana he'. Sabab bang d'nda he' aminda h'lla, taga-dusa iya angaliyu-lakad min h'llana tagna'. Maka dusahan isab l'lla angah'nda d'nda inān.”",
        33: "“Bay na takalebi isab panoho'an ma saga a'a masa awal e', ya yuk-i, ‘Wajib kam da'a magputing bang bay makasapa. Wajib isab sinuhul bang aniya' najalbi ni Tuhan.’",
        34: "Sagō' buwattitu na pamandu'ku ma ka'am: da'a kam magsapa. Da'a sibahatunbi sulga' pagsapahanbi sabab paningkō'an Tuhan ko' inān.",
        35: "Da'a sibahatunbi dunya sabab pat'kkaran tape'na. Sampay da'ira Awrusalam, da'a sibahatunbi isab sabab suku' Tuhan, ya Sultan Mahatinggi.",
        36: "Minsan kōkbi, subay mbal sibahatbi pagsapahanbi sabab ngga'i ka ka'am ya bay amapanjari. Minsan dalamba bu'unbi mbal kapindahanbi walna'na ni ettom atawa ni pote'.",
        37: "Bang kam angaho', subay aho' sadja, bang kam magin'mbal, subay mbal sadja. Ai-ai pamasugpatbi saddī minnē', min saitan patila'atun ko' itu.”",
        38: "“Bay na takalebi panara', ya yuk-i, ‘Bang aniya' amaka'at dambila' mata sehe'na subay binalosan pinaka'at dambila' matana. Damikiyanna bang aniya' angalutu empon sehe'na subay binalosan nilutu emponna.’",
        39: "Sagō' ya na itu pamandu'ku ma ka'am: da'a kam amalos bang aniya' makarusa ma ka'am. Abila aniya' a'a anampak baihu'nu dambila', patampalun isab dambila' panampakanna.",
        40: "Abila aniya' ganta' anuntutan ka'a bo' niamu' multa kamisitanu, pamuwanun ma iya sampay badju'nu.",
        41: "Abila aniya' a'a magmandahan ka'a pasehe' ma iya dabatu lawakna, sehe'in gi' iya duwa batu.",
        42: "Sai-sai angamu' ni ka'a, buwanin. Maka sai-sai bilahi angindam, paindamin.”",
        43: "“Bay na takalebi isab pamandu' dakayu' itu, ya yuk-i, ‘Kalasahinbi bagaybi, sagō' kab'nsihinbi bantabi.’",
        44: "Sagō' ya na itu pamandu'ku ma ka'am: kalasahinbi bantabi. Amu'-amu'inbi kahāpan min Tuhan sasuku angala'at ka'am",
        45: "bo' supaya kam an'ppu addat Tuhan, ya Mma'bi ma sulga'. Sabab Tuhan ya amasilak llaw ma a'a kamemon ahāp ka atawa ala'at. Amap'ttak iya ulan ma saga a'a maghinang kabontolan sampay isab ma a'a maghinang kala'atan.",
        46: "Bang hal a'a alasahan ka'am ya kalasahanbi, da'a kam aholat tinungbasan pahala' e' Tuhan. Minsan saga a'a magā' sukay parinta, alasa du ma sasuku alasahan sigām.",
        47: "Bang hal bagaybi ya saginabi pahāp, sali' du kam maka saga a'a mbal magta'at ma Tuhan, sabab ya du sigām magsagina dakabagayan. Mbal pabidda' kahāp addatbi min sigām.",
        48: "Ka'am ilu subay ajukup ma kaul maka pi'il tudju ni a'a kamemon, buwat Mma'bi ma sulga'.”",
    },
    6: {
        1: "“Kamaya'-maya' kam. Bang aniya' kahāpan hinangbi pagta'atbi ni Tuhan, da'a hinangunbi ma mata mairan. Sabab bang buwattē' hinangbi, halam aniya' tungbasbi min Tuhan, ya Mma'bi ma sulga'.",
        2: "“Angkanna, bang aniya' pamuwanbi ma a'a kulang-kabus, da'a pagbantugunbi. Da'a s'ppuhunbi a'a maglaku-laku in sigām ahāp, ya anarakka ma matahan saga a'a kamemon, ma deyom langgal ka atawa ma paglabayan. Tu'ud sigām bilahi sinanglitan e' saga manusiya'. Haka'anta kam to'ongan, sanglit min manusiya' ya panungbas sigām, halam saddī.",
        3: "Sagō' ka'am ilu, bang aniya' tabangbi a'a miskin, subay halam aniya' makata'uwan iya, minsan bagaybi.",
        4: "Subay halam aniya' makata'u. Jari bang buwattē', tinungbasan du kam e' Mma'bi Tuhan, ya maka'nda' ma ai-ai hinangbi minsan halam aniya' makata'u.”",
        5: "“Bang kam anambahayang, da'a sengorinbi saga a'a maglaku-laku in addat sigām ahāp. Sabab tagian sigām an'ngge anambahayang ma deyom langgal atawa ma paglalabayan a'a bo' supaya ta'nda' e' kamemon. Haka'anta kam to'ongan, bang sigām kasanglitan e' a'a, ya na he' panungbas sigām. Halam aniya' saddī.",
        6: "Sagō' ka'am ilu, bang kam anambahayang, pasōd kam ni deyom bilik. Tambolunbi lawang bo' yampa kam anambahayang ni Mma'bi Tuhan, ya mbal ta'nda'. Ati Mma'bi, ya maka'nda' ma ai-ai hinangbi minsan halam aniya' makata'u, anungbas du ma ka'am.",
        7: "“Bang kam anambahayang, da'a paggunahunbi ba'anan kabtangan halam aniya' pūsna, buwat panambahayang saga a'a ya magta'at ma tuhan-tuhan saddī. Sabab kinabā' e' sigām in panambahayang sigām kinale e' Tuhan saukat na ataha' sidda.",
        8: "Da'a sigām sengorinbi, sabab kinata'uwan asal e' Mma'bi Tuhan bang ai kasusahanbi minsan mbal pah'llingbi.",
        9: "Jari itu, bang kam anambahayang subay buwattitu kal'ngngananna: ‘O Mma' kami Tuhan ma sulga', bang pa'in pinagaddatan ōnnu e' kamemon,",
        10: "Bang pa'in mbal at'ggol bo' ka magparinta ma kamemon manusiya', Bang pa'in bineya' kabaya'annu ma dunya itu buwat asal bineya' mailu ma sulga'.",
        11: "Jukupin kami balanja' ma llaw itu.",
        12: 'Ampunun saga dusa kami, buwat kapangampun kami ma sai-sai makarusa ma kami.',
        13: "Da'a kami tugutin binowa ni deyom sasat, sagō' papuwasun kami min nakura' saitan, ya patila'atun.’",
        14: "“Bang kam angampun saga a'a makarusa ni ka'am, ya du ka'am niampun e' Mma'bi ma sulga'.",
        15: "Ya balikna, bang mbal ampunbi a'a bay makarusa ni ka'am, ya du ka'am mbal niampun e' Mma'bi Tuhan.”",
        16: "“Bang kam amuwasa da'a subay pala'atunbi pamaihu'anbi, buwat a'a maglaku-laku inān in sigām ahāp. Mbal sigām angupiksa' di-sigām, pangilahan a'a kasehe' in sigām magpuwasa. Haka'anta kam to'ongan, bang sigām kasanglitan e' manusiya', ya na he' panungbas sigām. Halam aniya' saddī.",
        17: "Saguwā' ka'am ilu, bang kam amuwasa, kula'upinbi baihu'bi maka surayunbi bu'unbi,",
        18: "bo' mbal kinata'uwan e' a'a kasehe'an in ka'am amuwasa. Ya sadja makata'u Mma'bi Tuhan ya mbal ta'nda' e' manusiya'. Ati Mma'bi ilu, ya maka'nda' ma ai-ai hinangbi sampay ma kalimbungan, anungbas du ma ka'am.”",
        19: "“Da'a kam magtimuk alta' maitu ma dunya, sabab hal magka'at, suma'an pinagkeket e' ulat, suma'an ginaha', suma'an isab nilangpasan.",
        20: "Sagō' maghinang kam ahāp bo' aniya' karayabi tinau'an ka'am ma deyom sulga', sabab karaya mahē' mbal takeket e' ulat, mbal magkagaha', maka mbal kalangpasan.",
        21: "Sababna maingga-maingga panau'anbi alta'bi, mahē' ya pataptapan pangatayanbi.”",
        22: "“Matabi itu sapantun palita'an amuwan sawa ma deyom ginhawabi. Bang ahāp matabi, asawa sampay deyom ginhawabi.",
        23: "Sagō' bang matabi mbal ahāp, angalendom sampay ginhawabi. Bang yukbi aniya' ma ka'am kasawahan bo' pa'in halam, na aheya kalendomanbi.",
        24: "“Ya niōnan sosoho'an mbal makapagduwa nakura', sabab tantu kab'nsihanna nakura'na dakayu' maka kalasahanna dakayu'. Amalut iya ma dakayu' ati taikutanna dakayu'. Hatina mbal kam manjari maghinang ma Tuhan bang pilak ya paheyabi ma atay.”",
        25: "“Angkanna kam soho'ku da'a sakit magsusa pasal kallumanbi, bang ai kakanbi maka bang ai inumbi. Da'a kam magsusa isab pasal ginhawa baranbi bang ai kapan'mmekbi. Sabab kallumta itu labi ahalga' ma kita min kapamanganta. Ya du baranta, labi ahalga' min pan'mmekta.",
        26: "Nda'unbi saga manuk-manuk paleyang. Mbal magtanom, mbal magani. Mbal isab anau' kinakan ma llaw damuli. Sagō' binalanja'an du sigām e' Mma'bi ma sulga'. Bo' ka'am ilu, ahalga' gi' to'ongan min kamanuk-manukan.",
        27: "Sai bahā' makapataha' umulna minsan la'a hal danjām, ma sabab kasusahanna?",
        28: "“Angay isab kam magmasusa ma pasal pan'mmekbi? Nda'unbi saga sumping ma deyom kaparangan bang buwattingga katomo'na. Mbal magsangsā' maghinang, mbal magt'nnun.",
        29: "Sagō' haka'anta kam, minsan sultan Sulayman maka kahaldayana ma masa awal e', mbal du maka'atu lingkat pamakayna ma dakayu' sumping itu.",
        30: "Bang Tuhan ya makapayakun kaparangan ya tatasanna dang'llaw du, bo' pagsalung alanos sampay tinunu', tantu Tuhan amas'mmekan ka'am. Akulang pahāp pangandolbi ma iya!",
        31: "“Angkanna kam subay mbal magmasusa. Da'a kam magupama buwattitu: ai pagkakanta, ai paginumta, ai bahā' pas'mmekta?",
        32: "Saga a'a mbal ata'u magta'at ma Tuhan, ya na pa'in he'-i kinasusahan e' sigām. Sagō' ka'am ilu, kinata'uwan e' Mma'bi ma sulga' in ina'an kagunahanbi asal.",
        33: "Sagō' muna-muna kannalunbi pagparinta Tuhan maka kabontolan atay ya kabaya'anna. Manjari pinaniya'an du kam ai-ai kulang-kabusbi.",
        34: 'Angkan kam subay mbal magkasusahan pasal llaw salung sabab saddī kasusahan ma llaw sinōng. Sarang na pagsusahanbi hal ma llaw itu.”',
    },
    7: {
        1: "“Da'a sā'unbi pagkahibi bo' kam mbal sinā' e' Tuhan.",
        2: "Sabab bang kam ganta' amat'nna' hukuman ma sehe'bi, ya du ka'am pinat'nna'an hukuman e' Tuhan, pinapagtongod maka bay pangahukumbi sehe'bi he'. Ai-ai pan'ppongbi ma sehe'bi, ya du isab pan'ppong Tuhan ma ka'am.",
        3: "Ka'am magsoway sehe'bi ilu, angay ta'nda'bi bukbuk ma mata sehe'bi, ati mbal ta'nda'bi batang kayu ya ma deyom matabi?",
        4: "Mamarahi pahāp ka'am ilu! Yukbi, ‘Tabiya', la'ananta bukbuk min matanu ilu.’ Bo' pa'in aniya' batang kayu ma deyom matabi!",
        5: "In ka'am ilu maglaku-laku halam taga-sā'! La'aninbi gi' dahū ya bukbuk ma matabi ilu supaya asawa pang'nda'bi, bo' yampa kam angala'anan bukbuk min mata sehe'bi.",
        6: "“Da'a kam amuwan ai-ai asussi ma saga a'a ala'at, ya sali' sapantun ero'. Ya aniya' pabibud angal'kkob ka'am. Lapalbi ahalga', ya pinagbahasa mussa'bi, da'a larukinbi ni saga bawi. Ya aniya' pinaggi'ik-gi'ikan e' sigām.”",
        7: "“Angamu'-ngamu' kam, ati binuwanan du. Amiha kam, ati makabāk du kam. Mikiukab kam, ati niukaban du kam.",
        8: "Sabab sai-sai angamu' kabuwanan du. Sai-sai amiha makabāk du. Sai-sai isab mikiukab niukaban du.",
        9: "Ka'am taga-anak ilu, abila kam pangamu'an tinapay e' anakbi, buwananbi bahā' batu?",
        10: "Atawa bang angamu' daing, buwananbi bahā' sowa?",
        11: "Minsan ka'am dusahan ilu ata'u amuwanan anakbi ai-ai makahāp, luba'-lagi'na na Mma'bi ma sulga' ata'u du amuwanan ai-ai makahāp ni sasuku angamu' ni iya.",
        12: "“Manjari bang kabaya'anbi kinahāpan e' a'a, subay isab sigām kahāpanbi. Ya na he' kamaksuran sara' ya bay tasulat e' si Musa maka saga kanabi-nabihan.”",
        13: "“Pasōd kam min lawang akiput, sabab ya lān tudju ni nalka' aluha pasōranna maka aluhay nil'ngngan. Aheka isab manusiya' ameya' min lān inān.",
        14: "Saguwā' ya pasōran tudju ni sulga' akiput maka ahunit nil'ngngan. Akulang isab a'a makatuli' iya.”",
        15: "“Kamaya'-maya' kam bo' kam mbal ka'akkalan e' saga a'a magbau'-bau' in sigām nabi. Ahāp pangluwahan sigām bang ma pang'nda'ta, sali' sapantun bili-bili mbal makamula. Sagō' ma deyom atay sigām sali' sigām ero' talun, sidda ab'ngngis.",
        16: "Takilābi du sigām min kahinangan sigām, buwat kayu takilā min buwa'na. Mbal kita angā' buwa' anggul min kayu puhung, atawa buwa' kayu igira min sampinit.",
        17: "Bang kayu ahāp, ahāp isab buwa'na. Sagō' bang kayu mbal ahāp, mbal isab ahāp buwa'na.",
        18: "Bang kayu ahāp mbal makabuwan buwa' ala'at. Damikiyanna bang kayu ala'at suligna, mbal makabuwan buwa' ahāp.",
        19: "Bang aniya' kayu mbal ahāp pagbuwa'na, pinuwad du bo' tinimanan ni deyom api.",
        20: "Angkan yukku ma ka'am, takilābi du saga nabi ya ngga'i ka b'nnal sabab min kahinangan sigām.”",
        21: "“Ngga'i ka a'a kamemon ya anabbut aku ‘Panghū', O Panghū',’ makasōd ni deyom pagparintahan Tuhan. Luwal saga a'a ya ameya' ma kabaya'an Mma'ku ma sulga'.",
        22: "Bang ta'abut na llaw pangahukum ma manusiya', aheka du amissala ni aku, yuk-i: ‘O Panghū', bay kami amatanyag lapal Tuhan min kawasa ōnnu. Bay kami amala'an ba'anan saitan min deyom baran a'a, maka aheka isab saga hinang makainu-inu bay tahinang kami, min kawasa ōnnu.’",
        23: "Sakali bontolanku sigām, yukku, ‘Mbal kam takilāku. Ala'an kam min aku, ka'am kamemon maghinang kala'atan ilu.’”",
        24: "“Na, sasuku a'a akale ma bissalaku itu sampay ameya', in iya sali' a'a ahāp akkalna, ya bay makahinang luma'na ma papagan abatu.",
        25: "Manjari aniya' ulan alandos bay patumbuk, maka angandunuk kasapa'an, maka taluwa' hunus luma' inān. Sagō' halam ah'bba' sabab ahogot papaganna.",
        26: "Sasuku isab akale ma bissalaku bo' mbal ameya', sali' kahantang a'a kulang akkalna, ya makahinang luma'na ma kal'bbohan.",
        27: "Jari aniya' ulan alandos patumbuk, bo' angandunuk kasapa'an, bo' taluwa' hunus luma' inān. Magtūy ah'bba', alubu to'ongan.”",
        28: "Aubus pa'in e' si Isa amissala, kinainu-inuhan pandu'na e' ba'anan a'a bay makakale inān.",
        29: "Ya angkan buwattē' sabab magbidda' to'ongan pandu' si Isa maka pandu' saga guru sigām. Taga-kawasa asal si Isa bang amandu'.",
    },
    8: {
        1: "Makalūd pa'in si Isa min bīd-bīd inān, aheka to'ongan a'a bay paturul ma iya.",
        2: "Manjari aniya' a'a ni'ipul pina'an ni si Isa bo' angōk-tu'ut min dahuanna. Yukna, “Tuwan, bang ka bilahi, kauli'annu aku.”",
        3: "Magtūy tin'ppak a'a inān e' si Isa. Yuk si Isa, “Bilahi sadja aku. Kauli'an na ka!” Saru'un-du'un du kauli'an ipul a'a inān.",
        4: "Yuk si Isa ni iya, “Pakale ka. Da'a ka angahaka ni sai-sai ya bay tahinang ma ka'a ilu. Sagō' pehē' ka patūy ni imam bo' palilingun barannu ma iya. Puwas e' tukbalin kukulbanan ni Tuhan buwat bay pamandu' e' si Musa, tanda' saksi' ni kaheka'an a'a in ka'a ilu alanu' na.”",
        5: "Manjari itu, pasōd pa'in si Isa ni deyom da'ira Kapirnaum, aniya' dakayu' kapitan bangsa Rōm bay pasampang ni iya angamu' tabang.",
        6: "Yukna ni si Isa, “Tuwan, aniya' sosoho'anku ma luma'. Ina'an iya palege, mbal minsan makaosegan di-na. Kap'ddi'an iya to'ongan.”",
        7: "Yuk si Isa, “Pehē' du aku amauli' iya.”",
        8: "“Da'a ka pehē', Tuwan,” yuk kapitan. “In luma'ku mbal tōp papehe'annu. Angabtang sadja ka minnilu ati kauli'an du sosoho'anku he'.",
        9: "Minsan aku itu, biyaksa du pinagbaya'an e' a'a min diyata'anku, maka aniya' isab sundalu pagbaya'anku. Bang sō'ku dangan pehē', pehē' du iya. Bang sō'ku dangan pi'itu, pi'itu du iya ni aku. Damikiyanna bang aniya' pahinangku ma sosoho'anku, magtūy nihinang e'na.”",
        10: "Pagkale pa'in pah'lling kapitan itu e' si Isa, ainu-inu iya. Yukna ni saga a'a paturul ma iya inān, “Haka'anta kam to'ongan. Minsan ma deyom bangsatam Isra'il halam aku bay makabāk a'a buwat kapitan itu, akosog imanna.",
        11: "Pakale kam. Ma waktu sinōng aheka a'a min bangsa kaginisan, a'a bay min sobangan maka min s'ddopan, magtingkō'an magsalu maka disi Ibrahim, si Isa'ak maka si Yakub.",
        12: "Sagō' saga bangsa Isra'il itu, ya suku' ma pagparintahan Tuhan, nilarukan du tudju ni kalendoman, ati maina'an magalud maka magtage'ot empon sigām sabab min kapagsusun sigām.”",
        13: "Sakali amissala si Isa ni kapitan inān, yukna, “Amole' na ka. Tahinang ma ka'a buwat bay pagkahagadnu.” Manjari saru'un-du'un kauli'an sosoho'anna ma waktu he'-i du.",
        14: "Sakali palanjal si Isa pehē' ni luma' disi Simun. Pagsōdna ni deyom luma' inān, ta'nda'na mato'a si Simun d'nda palege maina'an, nil'mmun.",
        15: "Ni'ntanan e' si Isa tangan d'nda itu, ati pahali magtūy bay l'mmunna. Puwas e' punduk iya angalabotan disi Isa.",
        16: "Ta'abut pa'in pas'ddop llaw, aheka a'a sinōd saitan bay binowa pina'an ni si Isa. Ati pinala'an e'na saga saitan, min kabtanganna sadja. Maka a'a taga-saki inān kamemon bay kauli'an e'na.",
        17: "Buwattē' hinangna bo' aniya' kamaksuran ma bay tasulat ma Kitab e' nabi Isaya, ya yuk-i, “Bay iya anguli'an saga kalammahantam, bay iya ananggung saga sakitam.”",
        18: "Ta'nda' pa'in e' si Isa aheka a'a ma sakalibutna, yukna ni saga mulidna, “Sūng kitam pauntas ni dambila' danaw.”",
        19: "Ma halam gi' sigām makauntas, aniya' dakayu' guru sara' agama bay pina'an ni si Isa. Yukna, “Tuwan Guru, lilla' aku ameya' ma ka'a pi'ingga-pi'ingga papehe'annu.”",
        20: "Yuk sambung si Isa, “Gom hayop talun aniya' patapukanna, maka saga kamanuk-manukan aniya' pugaranna. Sagō' aku Anak Manusiya' itu, halam aniya' minsan patulihanku luggiya'.”",
        21: "Aniya' isab dakayu' mulid inān ah'lling ni si Isa, yukna, “Tuwan, paba'irun lagi' aku pabīng ni luma'. Subay na apuwas pangubulku ma mma'ku bo' yampa aku ameya' ma ka'a.”",
        22: "Sagō' yuk si Isa, “Ameya' na ka ma aku. Patut bang a'a amatay pinakubul ma saga a'a ya halam kaniya'an kallum taptap.”",
        23: "Puwas e' paruwa' si Isa ni bayanan, maka ameya' isab saga mulidna.",
        24: "Makauntas pa'in, parugpak hunus ni danaw inān. Agon-agon sigām abuhaw sabab sinasay e' goyak, sagō' ina'an si Isa atuli.",
        25: "Pasekot ni iya saga mulidna amati' iya. “O Tuwan,” yuk sigām, “anabang ka sabab abuhaw na kitam!”",
        26: "Yuk si Isa ma sigām, “Angay kam tināw? Kulang pahāp imanbi!” Manjari pabungkal si Isa bo' yampa soho'na baliyu maka goyak inān pahondong. Saru'un-du'un du magtūy at'ddo' lahat inān.",
        27: "Ainu-inu saga mulid e'. “Ai bahā' a'a itu?” yuk sigām. “Minsan baliyu maka goyak kapagagihan e'na.”",
        28: "Pagubus, makatandan disi Isa pehē' ni dambila' danaw, ni lahat saga a'a Gadara. Makarunggu' pa'in, aniya' pasampang ni iya duwangan a'a bay paluwas min kakubulan, a'a sinōd saga saitan. Landu' ab'ngngis saga a'a itu angkan halam aniya' makatawakkal palabay minna'an.",
        29: "Magtūy sigā angolang, yuk-i, “O Anak Tuhan! Ai lamudnu ma kami? Pi'itu ka bahā' aminasa kami ma mbal gi' ta'abut ganta'an?”",
        30: "Na, atā-tā lagi' minnē', aniya' ba'anan bawi magkakanan.",
        31: "Sakali anganjunjung saga saitan e' ma si Isa, yuk-i, “Bang kami subay pala'annu, pasōrun kami ni deyom baran saga bawi inān.”",
        32: "“Pehē' na kam,” yuk si Isa. Sakali ala'an saga saitan min baran a'a he' bo' pasalin pehē' ni deyom baran ba'anan bawi. Magtūy maglumpat paragan ba'anan bawi he' min pampang tudju ni deyom danaw, ati alembo kamemon.",
        33: "Jari saga magi'ipat bawi inān paragan pehē' ni kaluma'an angahaka'an saga a'a maina'an pasal bay tahinang e' si Isa ma saga a'a sinōd saitan e'.",
        34: "Angkan paluwas saga a'a min kaluma'an inān amāk si Isa. Magbāk pa'in, angamu' sigām junjung ni iya, bang pa'in iya ala'an min lahat sigām.",
    },
    9: {
        1: "Paruwa' na si Isa ni bayanan bay pameya'anna bo' yampa pabīng ni dambila' danaw, ni kauman ya pat'nna'anna.",
        2: "Jari maina'an pa'in, aniya' binowa ni iya a'a amatay ugatna, hal pabahak la'a ma palegehanna. Makata'u pa'in si Isa in a'a amowa inān angandol ma iya, yukna ni a'a amatay ugatna, “Otō', da'a ka asusa. Niampun na paldusahannu.”",
        3: "Aniya' maina'an saga guru sara' agama magupama dansehe'an. Yuk sigām, “Oy! A'a itu ah'lling kupul ma Tuhan!”",
        4: "Sagō' asal kinata'uwan e' si Isa bang ai ma pikilan sigām. Yukna, “Angay ala'at hona'-hona'bi ilu?",
        5: "Kumpasunbi bang ingga ya aluhay: bang yukku ni a'a, ‘niampun na dusanu’, atawa bang yukku, ‘pabungkal ka bo' ka lum'ngngan?’",
        6: "Na, buwananta kam tanda' palsaksi'an bo' kata'uwanbi in aku, Anak Manusiya', taga-kapatut angampun dusa ma deyom dunya itu.” Jari amissala si Isa ni a'a amatay ugatna inān. “Pabungkal na ka,” yukna. “Bowahun palegehannu ilu bo' ka amole'.”",
        7: "Sakali pabungkal a'a inān sampay amole'.",
        8: "Pag'nda' saga a'a inān ma hinang si Isa, sinōd sigām tāw. Sinanglitan Tuhan e' sigām ma sabab kawasa bay pamuwanna ma manusiya' makahinang buwattē'.",
        9: "Makal'ngngan pa'in si Isa, aniya' ta'nda'na dakayu' a'a niōnan Matiyu aningkō' ma deyom upis pagā'anna sukay parinta. Yuk si Isa ma iya, “Pi'itu na ka ameya' ma aku.” An'ngge magtūy si Matiyu bo' ameya' ma si Isa.",
        10: "Jari amangan si Isa ma luma' si Matiyu. Aheka isab saga maga'ā' sukay parinta maka saga a'a baldusa kasehe', ina'an pasalu ni si Isa maka saga mulidna.",
        11: "Hinabu sigām magsalu, aniya' saga Parisi ang'nda' ni sigām. Yuk saga Parisi itu ni mulid si Isa, “Angay gurubi ilu magsalu maka saga maga'ā' sukay parinta maka saga a'a dusahan kasehe'?”",
        12: "Takale e' si Isa patilaw sigām ati yukna, “Bang a'a abasag mbal na magpadoktol. Ya magpadoktol bang a'a taga-saki.",
        13: "Kira-kirahunbi ya bay tasulat ma Kitab Jabul, ya yuk-i, ‘Mbal ahalga' ma aku susumbali'an ya pagkulbanbi. Ya kabaya'anku to'ongan subay kam ma'ase' ma pagkahibi.’” Yuk si Isa gi', “Ngga'i ka a'a a'adil ya maksudku pi'itu, sagō' a'a baldusa supaya sigām ameya' ma aku.”",
        14: "Manjari pehē' saga mulid si Yahiya Magpapandi ni si Isa atilaw iya, yuk-i, “Tuwan, kami maka saga Parisi magpuwasa na pa'in, sagō' mulidnu ilu mbal amuwasa. Angay bahā'?”",
        15: "Anambung si Isa magparalilan. “Asusa bahā' saga luruk ni pagkawinan sat'ggol maina'an lagi' pangantin l'lla ma atag sigām? Tantu mbal. Sagō' ma llaw sinōng, bang ta'abut na waktu kapamala'an pangantin l'lla min sigām, minnē' sigām anagna' amuwasa.”",
        16: "Puwas e' magparalilan si Isa pasal pamandu'na, yukna, “Halam aniya' a'a amatupak kakana' baha'u, kakana' halam bay nirakdakan, ni badju' ndang. Sabab bang buwattē' pakongkong du tupak baha'u, ati agese' du min kakana' ndang. Jari paheya gom pa'in gese'na.”",
        17: "Pinaralil isab pamandu'na ni binu-anggul baha'u, yukna, “Halam aniya' angisi binu baha'u ni deyom pangisihan kuwit hayop bang ndang na. Bang ganta' buwattē' tantu abustak. Abu'us du binu, ati kaliman bay pangisihan e'. Sagō' in binu baha'u subay ni'isi ni pangisihan baha'u. Jari ya binu maka pangisihanna anatas sali'-sali'.”",
        18: "Sabu si Isa masi amandu' ma sigām, aniya' pina'an ni iya dakayu' nakura' langgal. Pasujud iya ma dahuan si Isa. Yukna, “Tuwan, yamboho' amatay anakku d'nda. Sagō' bang ka ameya' ma aku amat'nna' tangannu ma iya, tantu iya allum.”",
        19: "Sakali an'ngge si Isa bo' paturul ma nakura' inān. Pabeya' isab ma iya saga mulidna.",
        20: "Na, aniya' maina'an dakayu' d'nda sakihan. Sangpū' na maka duwantahun halam bay atitis laha'na. Pasekot iya ni si Isa min buli'an, bo' ama'abut tanganna ni tōng juba si Isa.",
        21: "Yukna ma deyom pikilanna, “Bang sadja tasagidku minsan la'a hal tōng s'mmekna, pauli' du sakiku.”",
        22: "Jari palingi' si Isa ati ta'nda'na d'nda itu. Yukna, “Arung, da'a ka asusa. Pauli' na sakinu sabab min pangandolnu.” Magtūy saru'un-du'un kauli'an d'nda itu.",
        23: "Pagt'kka si Isa ni luma' nakura' inān, ta'nda'na maina'an saga a'a magsuling maka ba'anan a'a magkasensongan.",
        24: "Yuk si Isa ma sigām, “Paluwas kam kamemon. Halam amatay onde' ilu, hal iya atuli.” Minnē' pinagtittowahan si Isa.",
        25: "Aubus pa'in bay pinaluwas saga a'a inān, pasōd si Isa ni deyom bilik onde' d'nda inān bo' yampa balutanna ma tangan. Magtūy iya punduk min baina.",
        26: "Jari in suli-suli pasal hinang si Isa itu bay pasaplag ni kaluha'an lahat e'.",
        27: "Palanjal pa'in si Isa minnē', aniya' duwa a'a buta bay paturul ma iya. Angalingan sigā pakosog, yuk-i, “Oy! Tubu' si Da'ud! Ma'ase' na ka ma kami!”",
        28: "Jari pagsōd pa'in si Isa ni deyom luma', pasekot ni iya duwangan buta inān. Yuk si Isa ma sigā, “Magsab'nnal kam in aku makapauli' du?” “Aho', Tuwan,” yuk sigā.",
        29: "Jari pinat'nna' e' si Isa tanganna ni mata sigā maka e'na ah'lling, yukna, “Tahinang ma ka'am buwat bay pagsab'nnalbi.”",
        30: "Magtūy du sigā maka'nda' pabīng, ati niebot-ebotan e' si Isa, yukna, “Da'a kam angahaka ni sai-sai pasal itu-i.”",
        31: "Sagō' ala'an pa'in duwangan itu minnē', amatanyag sigā pasal si Isa ma sakalingkal lahat inān.",
        32: "Ma sabu pa'in ala'an duwangan inān, aniya' saga a'a pina'an ni si Isa amowa sehe' sigām ya mbal makabissala ma sabab sinōd saitan.",
        33: "Aubus pa'in e' si Isa bay amala'an saitan min baran a'a itu, magtūy iya makabissala. Ainu-inu saga a'a maina'an kamemon. Yuk sigām, “Halam aniya' bay ta'nda'tam buwattitu ma kaluha'an lahat Isra'il itu. Yampa.”",
        34: "Sagō' yuk saga Parisi, “A'a itu taga-barakat min nakura' saitan, ya angkan tapaluwasna saga saitan.”",
        35: "Manjari talatag e' si Isa kamemon da'ira maka kaluma'an ma jadjahan e'-i. Amandu' na pa'in iya ma deyom langgal, anganasihat na pa'in lapal ahāp pasal pagparinta Tuhan. Kauli'an e'na saga saki maka kalammahan indaginis.",
        36: "Pag'nda'na ma a'a kamemon inān, landu' iya ma'ase', sabab ina'an sigām ma deyom kasusahan ma halam aniya' anabangan sigām. Sali' sigām sapantun bili-bili halam aniya' angupiksa' sigām.",
        37: "Sakali yuk si Isa ni saga mulidna, “Saga a'a itu sali' dalil huma atiguma' na buwa'na. Aluha tana', sagō' kulang a'a magani.",
        38: "Angkan kam subay angamu'-ngamu' ni Tuhan ya tag-dapu tana', bo' supaya iya anoho' saga a'a magani pi'itu.”",
    },
    10: {
        1: "Manjari nilinganan e' si Isa saga mulidna kasangpū' maka duwa bo' buwananna sigām kawasa pamala'an saitan min deyom baran a'a sampay pamauli' saki maka lamma indaginis.",
        2: "Ya na itu ōn a'a kasangpū' maka duwa bay kawakilan e' si Isa: kaissa, si Simun ya niōnan isab si Petros, maka danakanna si Andariyas, bo' si Yakub maka danakanna si Yahiya, saga anak si Sibidi.",
        3: "Pasunu' si Pilip maka si Bartolome maka si Tomas, bo' si Matiyu ya bay magā' sukay parinta, bo' si Yakub ya anak si Alpa. Pasunu' isab si Taddiyu,",
        4: "bo' si Simun a'a pangangatu. Katapusan si Judas Iskariyut, ya anukbalan si Isa ni saga bantana ma waktu damuli minnē'.",
        5: "In sangpū' maka duwa a'a itu bay pinandu'an e' si Isa bo' yampa sinō' pal'ngngan. Yukna, “Da'a kam pehē' ni kaluma'an a'a ngga'i ka bangsa Isra'il, atawa ni kaluma'an a'a Samariya.",
        6: "Sagō' pehē' kam ni bangsa Isra'il sadja, ya sapantun bili-bili alungay.",
        7: "Pehē' kam magnasihat in waktu kapagparinta Tuhan song na at'kka.",
        8: "Pauli'unbi sasuku asaki. Pakallumunbi saga a'a bay magpatayan, palanu'unbi sasuku ni'ipul, maka paluwasunbi saga saitan min deyom baran a'a. Bay kam anaima' kapatut min aku ma halam aniya' bayadna, angkan kam subay anabang ma halam aniya' tongodna.",
        9: "Da'a kam amowa bulawan atawa pilak minsan hal pisita ma deyom sabitanbi.",
        10: "Da'a kam amowa paglutu'anan, atawa badju' pasalinanbi, atawa taumpa' atawa tungkud. Sabab bang a'a maghinang, wajib iya binuwanan napakana.",
        11: "“Bang kam at'kka ni da'ira atawa ni kaluma'an, piha'unbi a'a maina'an ahāp kasuddahanna, ati pahanti' kam ma iya sampay ta'abut waktu kala'anbi min lahat ina'an-i.",
        12: "Bang kam pasōd ni luma' a'a, saginahunbi buwattitu, ‘Bang pa'in kam kaniya'an kasannangan!’",
        13: "Jari bang ahāp kasuddahan sigām ma luma' inān, kat'kkahan du sigām kasannangan ya bay pangamu'bi. Sagō' bang mbal ahāp kasuddahan sigām, papellengunbi ni ka'am kasannangan he'.",
        14: "Bang ganta' aniya' saga a'a mbal anagina ka'am, atawa mbal bilahi akale ma ka'am, ala'an kam min luma' atawa min kauman inān. Paspasinbi dahū bagunbunna min tape'bi, tanda' saksi' in ka'am apuwas min sigām.",
        15: "Haka'anta kam, bang ta'abut llaw pangahukum Tuhan ma manusiya', kalabihan gi' buhatna ma saga a'a ma lahat inān min bay hukuman ma da'ira Sodom maka da'ira Gomora, lahat abantug ma sabab dusa a'ana ma masa awal e'.”",
        16: "“Pakale kam,” yuk si Isa. “Ilu kam song papehē'ku ni deyoman saga a'a ala'at. Sali' kam sapantun bili-bili pinapehē' ni deyoman ba'anan ero' talun, ya magpangal'kkob. Angkan subay ataha' akkalbi, maka subay ahatul kajarihanbi.",
        17: "Pahalli' kam, sabab aniya' a'a an'kkahan kam ni paghukuman maka angandaplosan kam ma deyom kalanggalan.",
        18: "Pinaharap kam ni saga gubnul maka ni saga sultan bo' pinapariksa' e' sigām, ati makasaksi' du kam ma pasalanku ni sigām sampay ni saga a'a ya ngga'i ka Yahudi.",
        19: "Jari bang kam tinandanan ni sara', da'a kam magsusa bang ai pamissalabi atawa bang buwattingga e'bi ah'lling. Tantu kam binuwanan lapal pamissalabi bang ta'abut waktuna.",
        20: "Sabab ngga'i ka baranbi ya ah'lling ma waktu he'-i, sagō' Rū Mma'bi Tuhan ya anabangan ka'am amissala.",
        21: "“Ma waktu sinosōng inān aniya' du saga a'a anukbalan danakan sigām bo' pinapatay. Aniya' du isab saga matto'a l'lla anukbalan anak sigām bo' pinapatay. Saga anak isab amantahan matto'a sigām, anoho' isab subay pinapatay.",
        22: "Maka ka'am saga mulidku,” yuk si Isa, “kinab'nsihan du e' a'a kamemon ma sabab aku ya pameya'anbi. Sagō' sasuku ahogot imanna sampay ni kahinapusan, makasampay ni kasalamatan ma deyom sulga'.",
        23: "Bang kam ganta' bininasa ma kaluma'an dakayu', alahi kam ni kaluma'an saddī. Haka'anta kam, ma halam gi' talatagbi kalahatan Isra'il kamemon, in aku Anak Manusiya' pabalik du pi'itu.",
        24: "“Halam aniya' mulid palanga min guruna. Halam aniya' ata palanga min nakura'na.",
        25: "In mulid subay magsukul bang makasali' ni guruna, maka sosoho'an subay magsukul bang makasali' ni nakura'na. Na, bang aku nakura'bi pinagōnan e' sigām Be'elsebul, hatina nakura' saitan, luba'-lagi'na na ka'am sosoho'anku niōnan ala'at du e' sigām.”",
        26: "“Da'a kam tināw ma saga manusiya'. Kamemon bay nilimbungan tantu du pinaluwas. Kamemon bay tinau' ma deyom atay tantu du pinata'u.",
        27: "Ai-ai pangahakaku ka'am ma deyom kalendoman, pah'llingunbi ma kasawahan. Maka ai-ai nihagas-hagas ma taingabi, patanyagunbi ma mairan.",
        28: "Da'a kam tināw ma a'a ya makapatay baranbi, sabab mbal ta'abut palnyawahanbi. Ahāp lagi' bang Tuhan ya katāwanbi, sabab in iya taga-kawasa aniksa' baranbi sampay nyawabi ma deyom nalka'.",
        29: "Pikilunbi manuk-manuk paupit ilu, tab'llita duwa hekana maka pisita, sagō' minsan areyo' halga'na halam aniya' paupit minsan dakayu' ahūg ni tana' bang ngga'i ka min kabaya'an Mma'bi Tuhan.",
        30: "Ya lagi'na ka'am. Minsan lamba bu'unbi ilu, taitung e' Tuhan bang pila hekana.",
        31: "Angkan kam subay mbal tināw, sabab ahalga' gi' kam min ba'anan paupit.”",
        32: "“Sai-sai angahaka ma alopan kaheka'an a'a in aku pameya'anna, angahaka du aku ma alopan Mma'ku ma deyom sulga', in a'a inān palsuku'anku.",
        33: "Sagō' sai-sai amalilu ma alopan kaheka'an in aku ngga'i ka pameya'anna, paliluhanku du isab a'a inān ma alopan Mma'ku ma deyom sulga'.”",
        34: "“Arai' pangannalbi in maksudku pi'itu amowa kasannangan ni dunya, bo' ngga'i ka. Ya maksudku pi'itu ngga'i ka kasannangan sagō' pagsagga'an.",
        35: "Bay aku pi'itu amapagsagga' manusiya' dangan maka dangan. Anak l'lla magbono' maka mma'na, anak d'nda maka ina'na, ayuwan d'nda maka mato'ana d'nda.",
        36: "Binantahan a'a e' sehe'na magdaluma'.",
        37: "“Bang a'a alasahan mma'na maka ina'na palabi min aku, mbal iya wajib tahinang mulidku. Damikiyanna isab bang a'a alasahan anakna l'lla-d'nda palabi min aku, mbal iya manjari tahinang mulidku.",
        38: "Sai-sai bilahi anunuran aku subay tanggungna hāgna pamapatayan iya. Bang hati mbal paglilla'na, mbal iya manjari tahinang mulidku.",
        39: "Sai-sai allogan kallum baranna, halam du aniya' kallumna taptap. Sagō' sai-sai mbal allogan kallum baranna bo' lilla' isab amatay ma sababku, makabāk iya kallum kakkal.”",
        40: "“Sai-sai anaima' ka'am, aku ya tinaima' e' sigām, sampay Tuhan ya bay amapi'itu aku ni dunya.",
        41: "Sasuku anaima' nabi ma sabab lapal Tuhan ya pamissalana, a'a inān katungbasan kahāpan ya panungbas nabi. Damikiyanna, sasuku anaima' a'a adil ma sabab ka'adilna, katungbasan iya kahāpan ya panungbas saga a'a adil.",
        42: "Haka'anta kam to'ongan, sai-sai amuwan minsan la'a hal dasawan bohe' dingin ma dakayu' a'a areyo' kapaga'ana pagka mulidku iya, tantu a'a inān tinungbasan kahāpan.”",
    },
    11: {
        1: "Aubus pa'in e' si Isa bay magpanoho'an ma mulidna kasangpū' maka duwa inān, ala'an iya minnē'. Pehē' iya ni saga kaluma'an ma lahat Jalil bo' magpandu' maka magnasihat.",
        2: "Na, si Yahiya Magpapandi bay takalabusu asal. Pagkalena pasal kahinangan Al-Masi, anoho' iya saga mulidna kasehe' pehē' ni si Isa",
        3: "atilaw iya, yuk-i, “Ka'a bahā' ya bay pinagbissala e' si Yahiya pi'itu ni dunya? Atawa aniya' gi' saddī nilagaran?”",
        4: "Anambung si Isa, yukna, “Pabīng kam pehē'. Haka'inbi si Yahiya pasal ai-ai takalebi maka ai-ai ta'nda'bi itu.",
        5: "Saga a'a bay buta maka'nda' na, a'a bay pengka' makal'ngngan na, a'a bay ni'ipul tapalanu' na, a'a bay bisu makakale na, maka a'a bay amatay tapakallum na pabīng. Sampay saga a'a kulang-kabus pinagnasihatan na lapal ahāp.",
        6: 'Aheya kahāpan sasuku mbal magduwa-ruwa pikilanna ma aku.”',
        7: "Pasalta' pa'in saga mulid si Yahiya inān ala'an min si Isa, amissala iya ni katimukan a'a inān pasal si Yahiya. Yukna, “Ai bahā' bay pihabi, ya angkan kam pehē' ni paslangan? Bilahi kam bahā' ang'nda' a'a sapantun dansolag parang-parang, tabowa pap'llay e' baliyu?",
        8: "Bang ngga'i ka he'-i, na ai bahā' pihabi pehē'? A'a magsin'mmek ahalga'? Arai' ngga'i ka, sabab bang a'a magsin'mmek buwattē', astana' ya pat'nna'anna.",
        9: "Haka'inbi aku to'ongan bang ai bay pihabi pehē'. Dakayu' nabi bahā'? Aho', nabi, sagō' alanga lagi' min nabi.",
        10: "Sabab si Yahiya itu bay pinagbissala ma Kitab Kanabi-nabihan, ya yuk-i, ‘Soho'ku a'a kawakilanku parahū min ka'a, yuk Tuhan, bo' supaya sakapna lān palabayannu.’",
        11: "“Haka'anta kam to'ongan,” yuk si Isa, “pasal si Yahiya Magpapandi itu: halam aniya' abangsa labi gi' min iya. Sagō' sai-sai ma deyoman pagparintahan Tuhan, minsan a'a areyo' kapaga'ana, alanga lagi' iya min si Yahiya.",
        12: "Min waktu tagna' kapagnasihat si Yahiya sampay ni llaw itu, amanuyu' to'ongan saga a'a bo' makasōd pehē' ni deyom pagparintahan Tuhan.",
        13: "In pagparintahan Tuhan itu pinagkallam na pa'in ma Kitab Tawrat maka ma Kitab Jabul sampay ta'abut waktu kalahil si Yahiya.",
        14: "Jari bang kam ahutu magkahagad, si Yahiya ya na si Elija ya pinagsambatan e' kanabi-nabihan.",
        15: "Sasuku kam makakale, kalehunbi to'ongan.",
        16: "“Manjari,” yuk si Isa, “ai pamaralilanku saga a'a ahil jaman itu? Sali' sigām hantang onde'-onde' magtingkō'an ma halaman tabu' magongka'-ongka'. Angalingan saga onde'-onde' min dambila' ni kasehe'an sigām, yuk-i,",
        17: "‘Oy! Ka'am ilu! Bay kami angandapu'an ka'am sagō' ka'am ilu mbal angigal. Bay kami magsindilan sagō' ka'am ilu mbal ameya' magtangis.’",
        18: "“Buwattē' isab ma si Yahiya. Amuwasa iya maka mbal anginum inuman makalango, ati yukbi in iya sinōd saitan!",
        19: "Puwas e' aku, Anak Manusiya', bay pi'itu magkakan maka maginum. Magtūy aku pinah'llingan e' a'a kamemon, yuk-i, ‘He! Nda'unbi a'a itu, dahaga'! Panginginum! Magbagay iya maka a'a magā' sukay parinta, sampay baldusa kasehe'an!’ Saguwā',” yuk si Isa, “ta'nda'tam min kahinangan Tuhan in pangita'una asal taluwa'.”",
        20: "Puwas e' anagna' si Isa amabukagan saga a'a ma deyom kada'irahan bay pangahinanganna kaheka'an saga hinangna makainu-inu, malaingkan halam bay pataikut min karusahan sigām.",
        21: "Yuk si Isa, “Allā, ka'am saga a'a Korasin maka a'a Betsaida, maka'ase'-ase' sidda ya pamakadal ka'am! Aheka hinang makainu-inu bay pina'nda'an ni ka'am sagō' halam bay b'nnalbi. Bang bay tahinang saga hinangku makainu-inu inān ma da'ira Tira maka da'ira Sidun, tantu saga a'a maina'an bay pataikut min dusa sigām. Tantu sigām bay mags'mmek karut, maka magbusugan di-sigām abu, tanda' sin pagsusun sigām.",
        22: "Haka'anta kam, bang ta'abut llaw pangahukum Tuhan, abuhat lagi' hukuman ya pinat'kka ni ka'am min bay hukuman ma saga a'a da'ira Tira maka da'ira Sidun ma masa awal e'.",
        23: "Ka'am isab saga a'a Kapirnaum,” yuk si Isa, “ilu kam magbantug-bantug di-bi in ka'am pinalanga sampay ni sulga'! Sagō' nalka' sadja ya pasampayanbi! In hinang makainu-inu bay pina'nda'an ni ka'am, bang bay kapa'nda'an ni saga a'a Sodom, tantu masi da'ira sigām sampay ni kabuwattina'anan.",
        24: "Haka'anta kam, bang ta'abut llaw pangahukum, abuhat gi' hukuman ya pinat'kkahan ka'am min bay pinat'kkahan saga a'a Sodom ma masa awal e'.”",
        25: "Manjari itu, ma waktu ina'an, amissala si Isa ni Tuhan. Yukna, “O Mma', ka'a ya makapagbaya' ma langit maka ma dunya. Aheya pagsukulanku ni ka'a sabab in bay limbungannu min a'a taga-pangadji' sampay min a'a alalom pangita'una, pata'unu na ni a'a akulang pangita'una.",
        26: "Aho', Mma', min kōgnu maka baya'nu angkan buwattē'.”",
        27: "Yuk si Isa ni saga a'a inān, “Bay na pangandol ai-ai kamemon ma aku e' Mma'ku. Halam aniya' makata'uwan aku, luwal Mma'ku. Damikiyanna, halam aniya' makata'uwan iya, luwal aku anakna lissi, beya' isab sasuku tapene'ku.",
        28: "“Ameya' kam ma aku, sasuku kam binale' maka kabuhatan, bo' kam buwananku pahalian.",
        29: "Taima'unbi pandu' ya pamatanggungku ma ka'am, ati anganad kam min aku sabab ahantap asal aku, maka areyo' pangatayanku. Minnitu kam makabāk kahayangan ma nyawabi.",
        30: "Sabab aluhay ya pamahinangku ma ka'am, maka alampung isab ya pandu' pamatanggungku ma ka'am.”",
    },
    12: {
        1: "Dakayu' Sabtu', lum'ngngan disi Isa labay min t'ngnga' huma pananoman pai-tirigu. Jari itu, pagka lingantu saga mulidna, aniya' batang pai bay kin'ttu' e' sigām bo' ni'inta' isina.",
        2: "Pag'nda' saga Parisi ma bay tahinang e' saga mulid itu, yuk sigām ni si Isa, “Nda'un ba saga mulidnu ilu. Langgal sara' ko' hinang sigām pagka pasabu ma llaw Sabtu'.”",
        3: "Anambung si Isa, yukna, “Angay, halam tabassabi bang ai bay tahinang e' si Da'ud ma masa awal e', waktu bay kaotas sigām maka saga a'ana?",
        4: "Bay pasōd si Da'ud ni deyom langgal Pangarapan ni Tuhan bo' yampa ngā'na saga tinapay ya panukbal ni Tuhan. Pinagkakan e' sigām tinapay inān minsan langgal sara', sabab luwal saga kaimaman ya wajib amangan tinapay bay tinukbalan inān.",
        5: "Halam bahā' isab bay tabassabi ma Kitab Tawrat pasal saga imam ya maghinang ma deyom langgal pagkulbanan sabu ma llaw paghali ni Tuhan? Minsan sigām makalanggal sara' agama halam du sigām bay magdusa.",
        6: "Haka'anta kam, aniya' maitu aheya kapatutna min langgal pagkulbanan inān.",
        7: "Aniya' lling Tuhan bay tasulat ma Kitab Kanabi-nabihan, ya yuk-i, ‘Mbal ahalga' ma aku susumbali'an ya pagkulbanbi. Sagō' ya kabaya'anku to'ongan subay kam ma'ase' ma pagkahibi.’ Bang bay tahatibi to'ongan pandu' itu, mbal du kam bay amat'kka hukuman ni saga a'a ya halam bay magdusa.",
        8: "Sabab aku, Anak Manusiya', taga-kapatut magbaya' ma llaw Sabtu', ya llaw mulliya.”",
        9: "Manjari palanjal si Isa minnē' ni lahat dakayu', ati pasōd iya ni deyom langgal sigām.",
        10: "Aniya' maina'an a'a pakongkong tanganna, maka aniya' isab saga a'a bilahi amiha dusa ma si Isa panuntut sigām ma iya. Tinilaw iya e' sigām, yuk-i, “Langgal sara' bahā' ma agamatam bang kita amauli' a'a ma llaw paghali ni Tuhan?”",
        11: "Anambung si Isa, yukna, “Ai bahā' hinangbi bang aniya' dakayu' bili-bilibi ahūg ni deyom lowang hinabu ma llaw paghali? Mbal bahā' ngā'bi hayop inān, pinaluwas min deyom lowang?",
        12: "In kita binangsa manusiya' labi gi' ahalga' min bili-bili. Angkan wajib bang kita maghinang kahāpan ma llaw paghali ni Tuhan.”",
        13: "Sakali ah'lling si Isa ni a'a pakongkong tanganna inān, yukna, “Pah'nnatun tangannu ilu.” Na, pinah'nnat e'na, magtūy kauli'an tanganna pasali' na ni tanganna dambila'.",
        14: "Sagō' paluwas saga Parisi min deyom langgal inān bo' magisun bang buwattingga e' sigām amapatay ma si Isa.",
        15: "Pagta'u si Isa ma kaisunan saga Parisi e', ala'an iya min lahat ina'an. Aheka a'a bay paturul ma iya, ati kauli'an e'na sigām kamemon sasuku magsakian.",
        16: "Bay sigām banda'anna da'a sinō' anuli-nuli pasal iya.",
        17: "Minnē' aniya' katumanan ma bay pinagkallam e' Tuhan, ya tasulat e' nabi Isaya.",
        18: "Yuk-i, “Itiya' sosoho'anku bay pene'ku. Kalasahanku iya, landu' aku kasulutan ma iya. Pahōpku ni iya Rū-ku, ati iya ya magpasaplag kabontol hukumanku ni sabarang bangsa.",
        19: "Mbal iya angalugat, mbal isab angamahit. Mbal iya amatanog suwalana ma paglabayan a'a.",
        20: "Ma'ase' iya ma sasuku alamma pangandolna, maka tabangna sasuku mbal makakole'an di-na, sampay ni waktu kapat'nna'na hukuman abontol maka tara'ug kamemon kala'atan.",
        21: "Jari iya ya pangasahan e' kamemon palbangsahan.”",
        22: "Sakali aniya' binowa ni si Isa dakayu' a'a umaw maka buta sabab sinōd saitan. Kauli'an a'a itu e' si Isa, jari makabissala maka maka'nda' na iya.",
        23: "Ainu-inu saga a'a bay maina'an. Yuk sigām, “Ya itu bahā' tubu' si Da'ud dakayu'-kayu'?”",
        24: "Pagkale lling inān e' saga Parisi, yuk sigām, “Angkan a'a itu makapala'an saitan min deyom baran a'a sabab taga-kawasa iya bay min si Be'elsebul, ya pagnakura'an saitan.”",
        25: "Sagō' kinata'uwan asal e' si Isa bang ai pinikil e' sigām, angkan yukna, “Bang saupama aniya' pagsultanan abahagi' duwa saga a'ana, bo' magbono' sali'-sali', mbal at'ggol magka'at pagsultanan e'. Damikiyanna bang aniya' a'a magdalahat atawa magdaokom, bo' abahagi' duwa magsagga'an di-sigām, al'kkas sigām magkaukanat.",
        26: "Angkan ko', bang nakura' saitan amaluwas pagkahina saitan, hatina magkuntarahan iya di-na. Tantu mbal anatas kapagbaya'na.",
        27: "Yukbi in aku itu makapaluwas saitan ma sabab aniya' kawasaku pamuwan aku e' si Be'elsebul. Bang he'-i b'nnal, minningga bahā' pangā'an mulidbi kawasa, ya angkan sigām isab makapaluwas saitan? Mulidbi luggiya' ya amabukis kasā'anbi.",
        28: "Sagō' ya b'nnalna, ya angkan aku makapala'an saitan sabab taga-kawasa aku deyo' bay min Rū Tuhan. Ya na ko' ilu paltanda'an in Tuhan itiya' na magparinta ma ka'am.",
        29: "“Nakura' saitan inān sali' dalil a'a aga'os. Luma'na mbal tasōd, pangalta'na mbal kalangpasan. Luwal bang a'a ga'osan inān niengkotan dahū bo' yampa kalangpasan deyom luma'na.",
        30: "“Sai-sai mbal amogbogan aku,” yuk si Isa, “anagga' aku du. Maka sai-sai mbal anabangan aku amatipun saga suku'ku, amakaukanat du iya.",
        31: "Angkan kam haka'anku, sai-sai kam angandusa maka amah'lling pangkal tudju ni Tuhan, niampun du kam. Sagō' sai-sai amah'lling pangkal ni Rū Sussi, mbal ka'ampunan.",
        32: "Sai-sai amah'lling la'at ma aku, Anak Manusiya', makajari niampun dusana. Sagō' sai-sai amah'lling la'at ma Rū Sussi, mbal to'ongan niampun dusana, ai na ka ma masa itu, ai na ka ma masa sinōng.”",
        33: "“Bang saupama kayu ahāp,” yuk si Isa, “ahāp isab buwa'na. Damikiyanna isab bang kayu ala'at, buwa'na mbal ahāp. Sabab takilā asal kayu min buwa'na.",
        34: "Ka'am saga pangangakkal ilu! Mbal kam makabissala ahāp sabab ala'at deyom ataybi. Ai-ai bay ma deyom atay manusiya', gana-gana paluwas min bowa'na.",
        35: "Bang a'a ahāp, ahāp du isab kaul-pi'ilna sabab luwas min kahāpan ya bay tau'na ma deyom atayna. Sagō' bang a'a ala'at, ala'at du isab kaul-pi'ilna sabab luwas min kala'atan bay tau'na ma deyom atayna.",
        36: "“Haka'anta kam, bang ta'abut llaw pangahukum Tuhan ma manusiya', in a'a kamemon subay angahaka pasal bissala kamemon bay tapah'llingna ma halam aniya' kapūsanna.",
        37: "Sabab min pamissalana ya sababan angkan a'a nihukum, bang niampun atawa bininasa.”",
        38: "Manjari aniya' saga guru sara' agama maka saga Parisi bay maina'an. Yuk sigām ni si Isa, “Tuwan Guru, bilahi kami ang'nda' dakayu' paltanda'an luwas min barakatnu.”",
        39: "Sagō' anambung si Isa, yukna, “Dusahan pahāp saga a'a tahun itu-i, mbal to'ongan bilahi magta'at ma Tuhan. Ka'am ilu mikipa'nda' paltanda'an panulayanbi aku. Sagō' halam aniya' paltanda'an pa'nda'anku ka'am, luwal paltanda'an bay min si Yunus ma masa awal e'.",
        40: "Sabab si Yunus bay t'llung'llaw t'llumbahangi ma deyom b'ttong sattuwa dilaut. Damikiyanna aku, Anak Manusiya', t'llung'llaw t'llumbahangi du aku ma deyom gumi ma sinosōng.",
        41: "Bang ta'abut na llaw pangahukum Tuhan ma manusiya', magt'nggehan du saga a'a bay ma da'ira Niniba ma masa awal e', ati sigām ya anaksi' in ka'am taga-dusa. Sabab sigām ya bay akale ma nasihat si Yunus, magtūy apinda min dusa sigām. Haka'anta kam, itiya' na dakayu' a'a labi lagi' alanga min si Yunus e', sagō' mbal iya b'nnalbi.",
        42: "Bang ta'abut isab llaw pangahukum Tuhan ma manusiya' aniya' du an'ngge dakayu' sultan d'nda bay ma lahat Seba ma masa awal e'. Anaksi' du iya in ka'am taga-dusa. Ya angkan d'nda inān taga-kapatut anaksi', sabab bay pi'itu min lahatna ma bihing dunya supaya takalena bissala pangita'u min sultan Sulayman. Haka'anta kam, ma buwattina'an aniya' maitu pasōng lagi' pangita'una min bay ta'u si Sulayman, sagō' mbal b'nnalbi.”",
        43: "“Na, bang takdil ni saitan,” yuk si Isa, “bang aniya' saitan paluwas min baran a'a, nilunsul e'na lahat halam bay kaulanan amiha pahalian. Jari bang halam aniya' tabākna,",
        44: "ah'lling saitan inān ni baranna, yukna, ‘Gom na aku pabīng ni deyom baran a'a bay pat'nna'anku he'.’ Pagbīng pa'in, ta'nda'na halam gi' aniya' pat'nna' maina'an, maka wa'i bay sinapuhan maka minomos.",
        45: "Puwas e' pehē' iya angā' pitu' saitan akalap gi' la'at sigām min iya, ati pasōd sigām kamemon ni deyom baran a'a pat'nna' maina'an. Jari in a'a inān pala'at gom pa'in kahālanna damuli min bay dahū. Buwattē' isab ma saga a'a baldusa ya allum ma tahun itu-i.”",
        46: "Na, hinabu si Isa masi amissala ni saga a'a inān, at'kka pina'an ina'na maka saga danakanna l'lla. Ina'an sigām angagad ma luwasan pagka bilahi magsuli-suli maka iya.",
        47: "Jari aniya' bay anambuku ma si Isa, yukna, “Tuwan, ina'an ina'nu maka saga danakannu ma luwasan. Bilahi magsuli-suli maka ka'a.”",
        48: "Anambung si Isa, yukna, “Sai bahā' ina'ku maka saga danakanku?”",
        49: "Jari tinō' e'na saga mulidna. Yukna, “Ya na ko' itu ina'ku maka dauranakanku.",
        50: "Sabab sai-sai angahinang kabaya'an Mma'ku ma sulga', ya na ko' ina'an saga danakanku l'lla-d'nda, maka ina'ku.”",
    },
    13: {
        1: "Ma llaw he'-i paluwas si Isa min luma' bo' pehē' ni bihing danaw aningkō' mahē' magpandu'.",
        2: "Aheka makalandu' a'a bay patimuk ni iya, angkan iya paruwa' aningkō' ma bayanan bay parunggu' mahē'. Bo' ba'anan a'a inān magt'nggehan ma bihing tampe.",
        3: "Aheka pamandu' e' si Isa ma sigām, pandu' pamaralilan. Yukna, “Aniya' inān dakayu' a'a pehē' ni humana anaboran bigi-tinanom.",
        4: "Pagsabodna itu, aniya' bigi-tinanom kasehe' apakpak ni bihing lān. Sakali pina'an saga manuk-manuk anittuk iya.",
        5: "Aniya' isab bigi-tinanom kasehe' apakpak ni kabatuhan, ariki' tana'na. Bigi inān al'kkas patomo' sabab mbal alalom tana'na.",
        6: "Sagō' pasilak pa'in llaw, magtūy alūs ugbusna sampay alanos, sabab mbal alalom gamutna.",
        7: "Aniya' isab bigi-tinanom apakpak ni t'ngnga' sagmot itingan. Patomo' pa'in sagmot inān, magtūy kasembolan tinanom e'.",
        8: "Na, ya bigi-tinanom kasehe' apakpak ni tana' ahāp, pasōng-sōng amuwa' du pahāp. Aniya' batang kasehe' amuwan buwa' lumandu'an to'ongan hekana, aniya' kasehe' amuwan buwa' aheka, maka aniya' isab kasehe' sarang-sarang hekana.",
        9: "Na,” yuk si Isa, “sasuku kam makakale, kalehunbi to'ongan.”",
        10: "Manjari pehē' ni si Isa saga mulidna atilaw iya. Yuk sigām, “Angay ka magparalilan bang ka amandu'an saga a'a itu?”",
        11: "Yuk sambung si Isa, “Ka'am ilu kabuwanan kata'u bo' supaya tahatibi pasal kapagparinta Tuhan ma saga a'ana, ya halam bay pata'una ni manusiya' kasehe'. Sagō' saga a'a kasehe'an halam kabuwanan.",
        12: "Sabab sai-sai aniya' ta'una, ginanapan gi' kata'una sampay manglabi-labihan. Sagō' sai-sai halam aniya' ta'una kinulangan du min iya bay ta'una dangkuri'.",
        13: "Ya na itu sababanna angkan aku magparalilan ma saga a'a itu: sabab ang'nda' sigām sagō' mbal maka'nda'. Pakale isab sigām sagō' mbal takale to'ongan maka mbal tahati.",
        14: "Na, aniya' katumanan ma bay pinagkallam e' nabi Isaya, ya yuk-i, ‘Asal akale kam, sagō' mbal tahatibi. Asal papatong kam, sagō' mbal tapanhidbi.",
        15: "Sabab halam aniya' pasobsob ni pikilan saga a'a itu. Tainga sigām bay tinaplokan, mata sigām bay tinambunan. Bang ngga'i ka buwattē', bay du ta'nda' e' mata sigām, bay du takale e' tainga sigām, bay du isab tahati sampay ma deyom pikilan sigām, Ati pabalik sigām magta'at ni aku, bo' kauli'anku.’",
        16: "“Sagō' ka'am ilu,” yuk si Isa ni saga mulidna, “aheya kahāpanbi, sabab ai-ai ta'nda'bi tapanhidbi du, maka ai-ai takalebi tahatibi du.",
        17: "Haka'anta kam to'ongan, aheka saga nabi maka a'a suku' Tuhan ma masa awal e' bay bilahi to'ongan ang'nda' ma kahālan ya ta'nda'bi ma buwattitu, sagō' halam tasabu e' sigām. Bilahi to'ongan sigām akale ma takalebi itu, sagō' halam ta'abut e' sigām.”",
        18: "“Na,” yuk si Isa, “pakale kam to'ongan bo' tahatibi paralilan pasal a'a bay magsaboran bigi-tinanom he'.",
        19: "Saga bigi-tinanom bay apakpak ma lān inān paralilan a'a bay makakale pasal kapagparinta Tuhan, sagō' halam tahati e' sigām. Jari pina'an ni sigām saitan patila'atun angandagtu' lapal ya bay tinanom e' Tuhan ma deyom atay sigām.",
        20: "Saga bigi-tinanom bay apakpak ni tana' kabatuhan, paralilan a'a bay makakale ma palman Tuhan. Magtūy sigām kinōgan anaima' lapal palman e',",
        21: "sagō' palman Tuhan e' halam bay anganggamut palalom ma deyom atay sigām. Mbal anatas pagiman sigām. Ta'abut pa'in sigām t'kkahan susa atawa nila'at e' pagkahi sigām ma sabab pameya' sigām ma palman Tuhan, magtūy sigām ang'bba min pagiman sigām.",
        22: "Saga bigi-tinanom bay apakpak ni deyom sagmot itingan e' paralilan a'a bang am'nnal ma palman Tuhan. Sagō' bay pa'in am'nnal, magtūy alimbit pikilan sigām e' kahālan deyom dunya itu. Ya na pa'in ahalga' ma sigām pangalta' sigām. Angkanna palman Tuhan, ya bay takale e' sigām, sali' dalil tinanom kasembolan mbal amuwan buwa'.",
        23: "Na, saga bigi-tinanom bay sinaboran ma deyom tana' ahāp e', paralilan saga a'a bang am'nnal ma palman Tuhan maka makahati to'ongan. Magtūy palman inān sali' dalil tinanom, amuwan buwa' ma deyom atay sigām. Kasehe' aheka to'ongan buwa'na, kasehe' isab aheka-heka, maka kasehe'an sarang-sarang.”",
        24: "Manjari magparalilan na isab si Isa pabalik. Yukna, “In kapagparinta Tuhan ma manusiya' sali' dalil a'a anaboran bigi-tinanom ahāp ma tana'na.",
        25: "Manjari itu ma waktu sangom, sabu pa'in magtulihan a'a kamemon, aniya' banta tag-huma inān pina'an anaboran bigi-sagmot ma bay panaboran bigi ahāp. Puwas e' ala'an banta he'.",
        26: "Na, patomo' pa'in tinanom ahāp inān sampay anagna' na magbuwa', ta'nda' isab kasagmotan.",
        27: "Manjari pina'an saga tendog ni a'a tag-huma. Yuk sigām, ‘Tuwan, ahāp bigi-tinanom bay saborannu ma tana'nu. Minningga bahā' kasagmotan itu?’",
        28: "Anambung tag-huma, yukna, ‘Aniya' banta bay makahinang e'-i.’ Yuk saga tendog, ‘Bilahi ka bahā' bang kami angandarutan saga sagmot inān?’",
        29: "‘Da'a,’ yukna, ‘sabab bang darutbi sagmot inān, kalu ameya' alarut saga batang ahāp.",
        30: "Sagarinbi na magbeya' magtomo' sampay ta'abut waktu pagani. Jari buwattitu du panoho'anku ma saga a'a magani: darutunbi sagmot dahū. P'kkosunbi bo' yampa tinunu'. Puwas e' anihunbi buwa' min bay tinanom ilu bo' tau'unbi ni deyom kamaligku.’”",
        31: "Puwas e' magparalilan si Isa pabalik. Yukna, “In kapagparinta Tuhan ma manusiya' sali' dalil dansolag bigi-tinanom ariki'-diki', ya tinanom e' a'a ma tana'na.",
        32: "Bigi itu anahut min bigi-tinanom kamemon, sagō' bang anomo' na palabi heyana min tinanom kamemon. Tahinang kayu du, ati patapu' pina'an saga manuk-manuk angahinang pugaran ma sangana.”",
        33: "Magparalilan gi' si Isa, yukna, “Ya kapagparinta Tuhan sali' dalil pasulig ya ginuna e' d'nda pinalamud ni tirigu aheka, saga duwampū' maka lima kilu. Puwas e' niaddun e'na, gana-gana anulig kamemonna.”",
        34: "Kahaba' si Isa magpandu' ma kaheka'an a'a, magparalilan sadja iya. Mbal iya amissala ma sigām bang ngga'i ka min paralilan.",
        35: "Minnē' aniya' mattan ma bay tasulat e' dakayu' nabi, ya yuk-i, “Bang aku amandu' ma sigām subay bissala pamaralilan. Haka'anku sigām pasal ai-ai ya halam kinata'uwan sangay min tagna' kapamapanjari dunya.”",
        36: "Puwas e' ni'bbahan e' si Isa kaheka'an a'a inān bo' pasōd ni deyom luma'. Pina'an ni iya saga mulidna. Yuk sigām, “Pahatiun kono' kami paralilan pasal kasagmotan ma huma inān.”",
        37: "Anambung si Isa, yukna, “Aku, Anak Manusiya', dalil a'a anaboran bigi-tinanom ahāp inān.",
        38: "Huma inān, ya na dunya itu. Bigi ahāp inān, ya na saga a'a ameya' pinarintahan e' Tuhan. Kasagmotan inān, ya na saga a'a ameya' ma nakura' saitan, ya patila'atun.",
        39: "Banta bay anaboran bigi-sagmot inān, ya na nakura' saitan. Ya waktu kapagani, ya na llaw pangiyamat dunya. Ya a'a magani inān, saga mala'ikat.",
        40: "Bang takdil ni kasagmotan ya tinimuk inān bo' yampa tinunu', buwattē' du isab pakaradja'anna bang ta'abut na llaw kiyamat.",
        41: "Aku Anak Manusiya', soho'ku du saga mala'ikatku pi'itu ni dunya animuk saga a'a dusahan, sasuku bay amowa pagkahina angandusa maka sasuku bay maghinang kala'atan.",
        42: "Tatimuk pa'in, nilarukan sigām ni deyom api nalka'. Mahē' sigām magolang, saga magtage'ot empon sigām, sabab min kapagsusun sigām.",
        43: "Sagō' saga a'a suku' Tuhan anahaya du, pinaluwa ni mata llaw, bang ma deyom pagparintahan Mma' sigām Tuhan. Sasuku kam makakale, kalehunbi to'ongan.”",
        44: "Magparalilan isab si Isa, yukna, “In kapagparinta Tuhan ma saga a'ana sali' dalil alta' bay tinapukan ma deyom tana'. Sakali aniya' a'a bay makabāk iya. Tabākna pa'in itu, magtūy tambunanna pabalik. Landu' iya kinōgan, angkan iya pehē' amab'llian ai-aina kamemon bo' yampa b'llina tana' ya bay kabākanna alta' he'.”",
        45: "“Buwattitu isab kapagparinta Tuhan,” yuk si Isa. “Sali' dalil palilitu amiha saga mussa' ahāp.",
        46: "Bang iya ganta' makapuwa' dakayu' mussa' ahalga' to'ongan, pinab'llihan e'na ai-aina kamemon bo' tab'llina mussa' dakayu' he'.”",
        47: "“Buwattitu isab kapagparinta Tuhan ma manusiya',” yuk si Isa. “Sali' dalil pokot nihūg ni deyom tahik, sinōd daing ginis-ginisan.",
        48: "Ap'nno' pa'in pokot e', na ginuyud e' saga a'a magdaraing inān tudju ni daplakan. Aningkō' sigām maina'an bo' pinagsaddī ba'anan daing inān. Ingga ahāp, ni'isi e' sigām ni deyom ambung, ingga mbal tapagguna, tinimanan.",
        49: "Buwattē' du isab bang kiyamat na dunya itu. Paluwas saga mala'ikat ati pinagsaddī e' sigām manusiya' ahāp maka ala'at.",
        50: "Ya ala'at nilarukan du ni deyom api nalka'. Mahē' sigām magolang, saga magtage'ot empon sigām, sabab min pagsusun sigām.”",
        51: "Tinilaw e' si Isa saga mulidna, yukna, “Tahatibi bahā' kamemon bay pamissalaku ma ka'am e'?” “Aho',” yuk sambung sigām.",
        52: "“Na,” yuk si Isa, “bang aniya' guru sara' agama kapandu'an pasal kapagparinta Tuhan, sali' iya dalil a'a dayahan taga-luma'. Aheka asal alta'na baha'u maka ndang, hatina pangita'una pasal pandu' tagna' sampay pandu' baha'u.”",
        53: "Pagubus pa'in bay magparalilan si Isa, ala'an iya min lahat inān",
        54: "bo' amole' ni kauman ya luggiya' lahatna. Anagna' iya amandu'an saga a'a maina'an, ma deyom langgal sigām. Ainu-inu sigām ma pamandu'na, yuk-i, “Oy! Minningga bahā' pangā'anna pangita'una, maka barakat ya pangahinangna saga kahinanganna makainu-inu he'?",
        55: "Bang kami mbal asā', ya na itu anak karpentero. Ina'na si Mariyam. Saga danakanna disi Yakub, si Yusup, si Judas maka si Simun.",
        56: "Maka saga danakanna d'nda, itiya' du isab ma lūnganta itu. Minningga bahā' pangā'anna ta'una itu?”",
        57: "Jari kinap'ddi'an atay si Isa e' saga a'a inān. Sakali ah'lling iya ni sigām, yuk-i, “Pinagaddatan asal saga nabi ma sabarang lahat. Luwal saga a'a ma lahatna luggiya' maka sehe'na magdaluma' ya mbal magaddatan iya.”",
        58: "Jari salat saga hinang makainu-inu tahinang e' si Isa ma kaumanna inān sabab mbal angandol ma iya saga a'ana.",
    },
    14: {
        1: "Ma waktu he'-i sultan Herod ya bay magbaya' ma lahat Jalil. Manjari itu makakale iya pasal kahinangan si Isa",
        2: "ati ah'lling iya ni saga a'ana pangandolan, yukna, “Si Yahiya Magpapandi ko' inān, pinakallum na pabīng min kamatayna. Angkan tahinangna saga hinang makainu-inu inān.”",
        3: "Angkan buwattē' pah'lling si Herod, sabab iya ya bay magpanoho'an amapatay si Yahiya. Buwattitu bay kahālanna, sultan Herod itu bay magkabaya' maka ipalna si Herodiyas, bo' allum lagi' siyalina si Pilip, ya h'lla si Herodiyas e'. Pinabukagan na pa'in si Herod e' si Yahiya, yukna, “Mbal manjari bang ka magtimbul maka h'nda danakannu! Dusahan ka!” Angkanna si Yahiya bay sinō' sinaggaw e' sultan, sinō' niekang-ekangan bo' yampa ni'isi ni deyom kalabusu.",
        4: "Angkan buwattē' pah'lling si Herod, sabab iya ya bay magpanoho'an amapatay si Yahiya. Buwattitu bay kahālanna, sultan Herod itu bay magkabaya' maka ipalna si Herodiyas, bo' allum lagi' siyalina si Pilip, ya h'lla si Herodiyas e'. Pinabukagan na pa'in si Herod e' si Yahiya, yukna, “Mbal manjari bang ka magtimbul maka h'nda danakannu! Dusahan ka!” Angkanna si Yahiya bay sinō' sinaggaw e' sultan, sinō' niekang-ekangan bo' yampa ni'isi ni deyom kalabusu.",
        5: "Bilahi si Herod amapatay si Yahiya sagō' tināw iya ma kaheka'an a'a, sabab magkahagad sigām in si Yahiya nabi.",
        6: "Jari magpajamu sultan Herod panabuna ma llaw kapaganak ma iya. Angigal anak si Herodiyas budjang ma pang'nda' saga luruk ati kasulutan sidda si Herod,",
        7: "angkan janji'anna budjang inān. Yukna, “Janji'anta ka. Ai-ai amu'nu ni aku pamuwanku to'ongan.”",
        8: "Na, in budjang inān bay kapitnahan asal e' ina'na angkan yukna ni sultan, “Buwanin aku kōk si Yahiya Magpapandi, pinat'nna' ma talam.”",
        9: "Sidda asusa sultan inān, sagō' mbal kapindahan bay panganjanji'na ma alopan saga luruk e', angkan soho'na subay nirūlan budjang inān ma bay amu'na he'.",
        10: "Jari magpanoho'an si Herod subay pinonggolan kōk si Yahiya ma deyom kalabusu.",
        11: "Puwas e' pinat'nna' kōkna ma talam bo' yampa binowa ni budjang, ati ni'nde'an e'na ni ina'na.",
        12: "Sakali pina'an saga mulid si Yahiya angā' mayatna kinubul. Puwas e' pehē' sigām ni si Isa angahaka'an iya.",
        13: "Na, pagkale si Isa ma pasal ina'an-i, ala'an iya minnē' amusay ni lahat halam maga'a, hal iya dangan-danganna. Kinata'uwan pa'in kamahē'anna, magla'anan saga a'a min ba'anan kauman sigām bo' paturul ma iya, amaklay min bihing susulan.",
        14: "Pagdeyo' pa'in si Isa min bayananna, ta'nda'na saga a'a inān landu' to'ongan aheka. Sakali t'kkahan iya ase' ma sigām, maka kauli'an e'na sasuku taga-saki.",
        15: "Pagka abay kohap na, pehē' ni si Isa saga mulidna. Yuk sigām, “Sōng sangom na, maka itiya' kitam ma lahat l'ngngaw-l'ngngawan. Sō'un lagi' saga a'a itu pehē' ni kaluma'an inān bo' makab'llihan di-sigām kinakan.”",
        16: "Anambung si Isa, yukna, “Minsan sigām mbal ala'an minnitu. Ka'am na ya amakan sigām.”",
        17: "Yuk saga mulid e', “Lima du tinapay ma kami maka duwa du daing!”",
        18: "“Na,” yuk si Isa, “bowahunbi pi'itu.”",
        19: "Jari pinatingkō' sigām e'na ma kaparangan. Puwas e' niā' e'na lima tinapay maka duwa daing bo' pahangad ni langit magsukul ni Tuhan. Pinagpōng-pōng e'na tinapay bo' yampa sōnganna ni saga mulidna, ati tinopod-toporan e' sigām saga a'a inān.",
        20: "Magkakanan na saga a'a inān kamemon sampay mag'ssohan. Pagubus sigām amangan, tinipun kapin kinakan inān e' saga mulid e' ati ap'nno' sangpū' maka duwa ambung aheya.",
        21: "Aniya' saga limangibu a'a bay amangan inān, bang hal l'lla ya ni'itung. Saddī gi' d'nda maka onde'-onde'.",
        22: "Puwas e' sinoho' e' si Isa saga mulidna paruwa' ni bayanan. Pinarahū sigām min iya tudju ni dambila' danaw, sabuna amapole' kaheka'an a'a inān.",
        23: "Tapapole' pa'in saga a'a he', patukad si Isa dangan-danganna anambahayang ma bīd-bīd. Sangom pa'in lahat, maina'an iya dangan-danganna,",
        24: "bo' saga mulidna atā na min bihing. Taluwa' sigām goyak sabab anagga' baliyu.",
        25: "Pagdai' llaw pa'in, pehē' na si Isa tudju ni sigām, lum'ngngan min kuwit tahik.",
        26: "Ta'nda' pa'in iya e' saga mulidna lum'ngngan min kuwit tahik, nileya'-leya' sigām. “Umagad ko' ilu,” yuk sigām, maka e' sigām magsilawak kabowa tāw.",
        27: "Sagō' amissala magtūy si Isa ni sigām. “Paiman kam!” yukna. “Aku ko' itu. Da'a kam tināw.”",
        28: "Sakali ah'lling si Petros, yukna, “Nakura', bang ka'a to'ongan ilu, sō'un aku pi'ilu ni ka'a lum'ngngan min kuwit tahik.”",
        29: "“Na, pi'itu na ka,” yuk si Isa. Jari pareyo' si Petros min bayanan inān anagna' lum'ngngan min kuwit tahik tudju ni si Isa.",
        30: "Sagō' pagnanamna ma baliyu inān, sinōd iya tāw ati inut-inut iya pat'nnob. Magtūy iya angalingan, yukna, “Nakura', tabangun aku!”",
        31: "Magtūy iya niabut e' si Isa bo' binalutan. Yuk si Isa, “Kulang pahāp imannu ilu! Angay aku pagduwa-duwahannu?”",
        32: "Makariyata' pa'in sigā ni bayanan e', pahali na baliyu.",
        33: "Pinudji si Isa e' saga mulid kasehe'an inān, yuk-i, “B'nnal, ka'a ilu Anak Tuhan!”",
        34: "Jari itu, makat'kka pa'in sigām ni dambila' danaw, parunggu' sigām ni lahat Gennesaret.",
        35: "Takilā si Isa e' saga a'a mahē', ya angkan sigām bay anambukuhan sasuku taga-saki ma jadjahan ina'an-i, sinō' binowa ni si Isa.",
        36: "Angamu' sigām junjung ni si Isa, bang pa'in dūlanna saga a'a sakihan ang'ntan minsan la'a hal tōng s'mmekna. Manjari sai-sai bay maka'ntanan s'mmek si Isa saru'un-du'un kauli'an sakina.",
    },
    15: {
        1: "Manjari aniya' pina'an ni si Isa saga a'a Parisi maka guru sara' agama bay min da'ira Awrusalam. Atilaw sigām ma iya,",
        2: "yuk-i, “Angay saga mulidnu ilu mbal angisbat usulan bay pang'bba e' kamatto'ahantam? Amangan sigām minsan halam bay angose'an tangan sigām pahāp.”",
        3: "Anambung si Isa, yukna, “Na, ka'am ilu. Angay langgalbi panoho'an Tuhan ati beya'bi saga usulan bay min kamatto'ahanbi?",
        4: "Entomunbi panoho'an Tuhan, ya yukna, ‘Wajib kam magaddatan mma'bi maka ina'bi.’ Maka itu gi', ‘Sai-sai anukna'an mma'na atawa ina'na, a'a inān subay pinapatay.’",
        5: "Sagō' bang ma pamandu'bi, bang aniya' a'a ganta' amissala ni matto'ana, yukna: ‘Kaniya'ku itu, arak bay panabangku ka'am sagō' pasuku'ku na ni Tuhan.’",
        6: "Minnē' iya apuwas kono' min sara' pasal pagaddat ma kamatto'ahan. Jari tasulakbi dī panoho'an Tuhan pagka pagmatayanbi saga usulan bay pang'bba e' ka'mbo'-mbo'anbi.",
        7: "In ka'am ilu hal magbau'-bau' ameya' ma Tuhan, bo' halam. B'nnal asal ya kallam Tuhan bay tasulat e' nabi Isaya,",
        8: "yuk-i, ‘Saga a'a itu angahulmat aku maka lapal kabtangan sigām, sagō' alawak deyom atay sigām min aku.",
        9: "Ya pagpudji sigām ma aku halam aniya' pūsna, sabab ya pamandu' e' sigām saga panoho'an bay pinahinang e' manusiya'.’”",
        10: "Puwas e', nilinganan ba'anan a'a inān e' si Isa, sinō' patimuk pabīng ni atagna. Yukna ni sigām, “Pakale kam ma bissalaku. Pahati kam to'ongan.",
        11: "Ngga'i ka kinakan pasōd ni deyom bowa' ya makalumu' a'a. Ya makalumu' saga bissala ala'at paluwas min bowa'na.”",
        12: "Sakali pina'an ni si Isa saga mulidna. Yuk sigām, “Kata'uwannu bahā' ap'ddi' atay saga Parisi ma bay bissalanu insini'?”",
        13: "Yuk sambung si Isa, “Kamemon tinanom ya halam bay tinanom e' Mma'ku ma deyom sulga', nilarut du.",
        14: "Da'a kam magsusa pasal sigām. Sigām angamalim, sagō' ibarat sigām a'a buta. Bang buta angambit sehe'na buta, tantu sigām ahūg karuwangan ni deyom lowang.”",
        15: "Sakali ah'lling si Petros, yukna, “Pahatiun kami pasal bay pamaralilnu ilu.”",
        16: "Yuk si Isa, “Oy! Sampay ka'am ilu masi a'awam!",
        17: "Halam bahā' tahatibi? Bang aniya' kinakan pasōd ni deyom bowa' a'a, pasampay du ni deyom b'ttongna bo' yampa paluwas min baranna.",
        18: "Sagō' ya bissala ala'at paluwas min bowa' a'a, bay pino'onan asal min deyom atayna. Ya he' makalumu' iya.",
        19: "Sabab deyom atay manusiya' ya paluwasan hona'-hona'na ala'at, ya angkan iya maghinang kala'atan kaginisan, buwat saga amapatay, angaliyu-lakad, angahinang kahina'an d'nda-l'lla, anangkaw, magputing, maka angalimut.",
        20: "Kamemon itu makalumu' a'a. Sagō' bang kita amangan ma halam bay angose'an tanganta buwat pamandu' saga Parisi, ngga'i ka he'-i makabuwan kalumu'an.”",
        21: "Sakali palanjal si Isa minnē' tudju ni jadjahan da'ira Tira maka da'ira Sidun.",
        22: "Aniya' d'nda bangsa Kana'an min lahat inān bay pehē' ni si Isa anganjunjung. “O Tuwan,” yukna, “tubu' si Da'ud, ma'ase' ka ma aku. Anakku d'nda sinōd saitan, abinsana' sidda.”",
        23: "Sagō' halam makasambung si Isa minsan dakabtang. Jari pasekot saga mulidna amogos iya pasal d'nda inān, yuk-i, “Soho'un iya ala'an! Mbal iya pahali angalinganan kitam!”",
        24: "Anambung si Isa, yukna, “Bay aku sinō' pi'itu anabang saga a'a bangsa Isra'il sadja, ya sali' dalil bili-bili alungay min labayan.”",
        25: "Sagō' takale pa'in lling itu e' d'nda, magtūy iya pasujud ni tongod tape' si Isa. “O Tuwan,” yukna, “tabangun aku.”",
        26: "Sinambungan iya e' si Isa pinaralilan, yukna, “Mbal manjari niā' kinakan saga anak lissi bo' nilarukan ni saga ero'.”",
        27: "“B'nnal, Tuwan,” yuk d'nda. “Sagō' minsan saga ero' amangan du momok kinakan ya apakpak min lamisahan tag-ipatan ma sigām.”",
        28: "Sakali anambung si Isa, yukna, “Arung, ahogot imannu. Nirūlan du bay pangamu'nu ilu.” Manjari ma waktu he'-i saru'un-du'un du kauli'an anakna d'nda he'.",
        29: "Puwas e' ala'an si Isa min lahat ina'an, amaklay min bihing danaw Jalil. Jari patukad iya ni bīd-bīd aningkō' mahē'.",
        30: "Landu' aheka a'a bay pina'an ni iya amowa saga pengka', saga a'a aku'il, saga buta, saga umaw, sampay ba'anan a'a sasuku taluwa' ginisan saki. Pinat'nna' sigām e' sehe' sigām ma tongod tape' si Isa, ati kauli'an sigām e'na kamemon.",
        31: "Ainu-inu to'ongan saga a'a inān, pag'nda' sigām ma a'a bay umaw makapah'lling na, a'a bay aku'il kauli'an na, bay pengka' makal'ngngan na pabontol, bay buta maka'nda' na. Manjari sinanglitan e' sigām Tuhan, ya pagta'atan bangsa Isra'il.",
        32: "Sakali nilinganan e' si Isa saga mulidna bo' yukna, “Ma'ase' aku ma saga a'a itu, sabab kat'lluna llaw itu ya kamaitu sigām ma aku, maka halam na aniya' kinakan sigām. Mbal aku bilahi amapole' sigām ma halam bay amangan dahū, arakala' pinunung sigām ma pal'ngnganan.”",
        33: "Tinilaw iya e' saga mulidna, yuk-i, “Maingga bahā' pangā'anta kinakan sarang pamakan ba'anan a'a itu? Itiya' kitam ma lahat halam aniya' kaluma'anna!”",
        34: "Yuk si Isa, “Pila heka tinapaybi ilu?” “Pitu' tinapay,” yuk sigām, “maka saga daing ariki' mbal aheka.”",
        35: "Manjari sinoho' e' si Isa kaheka'an a'a inān magtingkō'an ma tana'.",
        36: "Niā' e'na kapitu' tinapay maka saga daing e', bo' yampa magsukul ni Tuhan. Puwas e' pinagpōng-pōng e'na tinapay maka daing-daing e' bo' sōnganna ni saga mulidna. Ati tinopod-toporan saga a'a inān e' sigām.",
        37: "Magkakanan sigām kamemon sampay mag'ssohan na. Aubus pa'in bay amangan, aniya' pitu' ambung aheya ap'nno' e' kapin kinakan bay tatimuk e' saga mulid e'.",
        38: "Saga a'a bay magkakanan inān aniya' saga mpat ngibu bang l'lla sadja ni'itung, saddī d'nda maka onde'-onde'.",
        39: "Jari pinapole' saga a'a inān e' si Isa. Pariyata' iya ni bayanan bo' yampa pauntas ni lahat Magadan.",
    },
    16: {
        1: "Manjari aniya' saga Parisi maka saga Saddusi bay pina'an ni si Isa. Bilahi sigām anulayan iya bo' supaya iya tajallat ma bissalana. Angkanna sigām mikipa'nda' paltanda'an, palsaksi'an in iya b'nnal taga-kapatut min Tuhan.",
        2: "Sagō' anambung si Isa, yukna, “Ka'am ilu, bang pas'ddop llaw, yukbi, ‘Ā, t'ddo' du salung sabab ilu akeyat bihing langit.’",
        3: "Pagsubu-subu isab, yukbi, ‘Ulan llaw itu sabab akeyat bihing langit maka angandom.’ Ata'u kam ang'nda' pandoga ma b'ttong langit, sagō' mbal kapandogahanbi paltanda'an ya ta'nda'bi ma masa itu-i.",
        4: "Saga a'a ma patahunan itu ala'at sidda, maka mbal bilahi magta'at ma Tuhan. Bilahi kam bahā' ang'nda' paltanda'an barakatan? Halam aniya' paltanda'an pina'nda'an ka'am, luwal paltanda'an bay min nabi Yunus ma masa awal e'.” Puwas e' ni'bbahan saga a'a inān e' si Isa, ati ala'an iya minnē'.",
        5: "Pagt'kka saga mulid si Isa ni dambila' danaw, halam sigām bay makaentom amowa tinapay palutu' sigām.",
        6: "Yuk si Isa ni sigām, “Kamaya'-maya' kam. Halli'inbi pasulig tinapay min saga Parisi maka min saga Saddusi.”",
        7: "Magsuli-suli saga mulidna pasal pah'llingna he', sabab halam tahati e' sigām. Yuk pangannal sigām, “Angkan arai' buwattē' pah'lling si Isa sabab halam kita bay amowa tinapay.”",
        8: "Kinata'uwan asal e' si Isa bang ai ya pinagsuli-suli e' sigām, angkan yukna, “Angay pagsuli-sulibi pasal halam aniya' tinapaybi? Ariki' pahāp pangandolbi ma aku!",
        9: "Halam gi' tahatibi bahā'? Halam taentombi bay waktu kapagpōng-pōngku tinapay lima hekana pamakan saga limangibu a'a he'? Entomunbi bang pila ambung aheya bay pangisihanbi kapin kinakan e'?",
        10: "Maka tinapay pitu' hekana bay pamakan mpat ngibu a'a he'. Pila ambung bay pangisihanbi kapin?",
        11: "Daka angay kam mbal makahati. Ngga'i ka tinapay ya bay pagbissalaku he'. Yukku, halli'inbi pasulig tinapay saga Parisi maka Saddusi!”",
        12: "Minnē' yampa tahati e' sigām ngga'i ka pasulig pamasulig tinapay ya bay pah'llingna, sagō' pandu' min saga Parisi maka min saga Saddusi. Ya na he' subay nihalli'an pahāp.",
        13: "Na, palintas disi Isa ni jadjahan lahat ma kasekotan da'ira Kesareya Pilipi. Maina'an pa'in, tinilaw e'na saga mulidna, yukna, “Bang ma pangupama a'a, sai kono' aku Anak Manusiya' itu?”",
        14: "Yuk sambung saga mulid e', “Bang ma a'a kasehe'an ka'a kono' si Yahiya Magpapandi. Bang ma a'a kasehe' in ka'a nabi Elija atawa nabi Irimiya. Maka bang ma a'a kasehe' isab dakayu' nabi ka bay ma masa awal e'.”",
        15: "“Na, bang ma ka'am,” yuk si Isa, “ai yukbi? Sai sa aku itu?”",
        16: "Anambung si Simun Petros. “Ka'a Al-Masi,” yukna, “Anak Tuhan ya kakkal salama-lama.”",
        17: "“Aheya kahāpan ma ka'a, Simun anak si Jona,” yuk si Isa, “sabab ngga'i ka min manusiya' ya angkan kata'uwannu ilu-i. Bay pamata'u ka'a e' Mma'ku ma deyom sulga'.",
        18: "Na, ya na itu pangahakaku ma ka'a: ka'a si Petros, hatina batu. Ati ma diyata' batu lakit ilu pangahinanganku langgalku, hatina saga jama'aku kamemon. Mbal sigām tara'ug minsan amatay.",
        19: "Buwananta ka kunsi', hatina kapatut angukab pasōran manusiya' tudju ni deyom pagparintahan Tuhan. Ai-ai lāngnu ma deyom dunya itu nilāng du isab ma deyom sulga', maka ai-ai pamarūlnu ma deyom dunya itu pinarūl du isab ma deyom sulga'.”",
        20: "Puwas e' binanda'an e' si Isa saga mulidna, da'a sinō' angahaka ni sai-sai in iya Al-Masi.",
        21: "Manjari puwas minnē', anagna' si Isa amahatian saga mulidna pasal ai tum'kka ni iya ma sinosōng. Yukna, “Subay aku pehē' ni da'ira Awrusalam. Aheka du kabinasahan pinat'kka ni aku e' saga pagmatto'ahan, e' saga kaimaman alanga, maka e' saga guru sara' agama. Pinapatay du aku, sagō' bang palabay na t'llumbahangi pinakallum du aku pabīng.”",
        22: "Sakali si Petros bay amowa si Isa paokat min kasehe'an, bo' yampa pabukaganna, yuk-i, “S'lle' bale puhu', pinatā e' Tuhan ya yuknu he' bo' mbal makani-ka'a.”",
        23: "Sagō' nialop si Petros e' si Isa. Yukna, “Ala'an ka min aku, saitan! Kabimbangan aku e'nu. Ya pamikilnu ilu pikilan manusiya' ko', ngga'i ka pikilan Tuhan.”",
        24: "Puwas e' amissala si Isa ni saga mulidna. “Bang aniya' bilahi ameya' ma aku,” yukna, “subay ngga'i ka kabaya'an baranna ya dūlanna. Subay tinanggung e'na hāgna pamapatayan iya, hatina kabinasahan ma sababku. Minnē' iya makajari ameya' ma aku.",
        25: "Sai-sai allogan kallum baranna, amutawan du kallum-nyawana min Tuhan. Sagō' sai-sai mbal allogan ma kallum-baranna, lilla' isab amatay ma sababku, makabāk du iya kallum kakkal.",
        26: "Sababna,” yuk si Isa, “bang aniya' a'a ganta' kaniya'an alta' deyom dunya kamemon, aheya lugi'na bang halam aniya' kallumna kakkal. Sabab halam aniya' tapangal'kkatna kallum-nyawana bang amutawan na.",
        27: "Aku Anak Manusiya' pabīng du pi'itu, aliput e' sahaya Mma'ku, maka sinehe'an aku e' saga mala'ikatna. Tungbasanku manusiya' kamemon, pinapagtongod maka bay hinang sigām dangan maka dangan.",
        28: "B'nnal ya pah'llingku itu ma ka'am, aniya' maitu ma ka'am mbal amatay sat'ggol halam gi' pi'itu in Anak Manusiya' bo' magparinta ma deyom dunya. Subay na aku ta'nda' e' sigām bo' yampa sigām amatay.”",
    },
    17: {
        1: "Palabay pa'in nnom llaw min waktu he'-i, binowa e' si Isa si Petros maka duwangan magdanakan, ya si Yakub maka si Yahiya, patukad ni diyata' būd alanga, sigām-sigām sadja.",
        2: "Maina'an pa'in sigām, apinda luwa si Isa ma pang'nda' sigām. Asahaya pamaihu'anna buwat mata llaw. Makasilaw sidda pote' s'mmekna.",
        3: "Sakali panyata' pina'an si Musa maka si Elija, ta'nda' e' saga mulid inān magsuli-suli maka si Isa.",
        4: "Ah'lling si Petros ni si Isa, yukna, “Tuwan Panghū', ahāp to'ongan itiya' kami maitu. Bilahi ka bahā' bang aku angahinang t'llu panggung-panggung pasindunganbi maitu, dakayu' ma ka'a, dakayu' ma si Musa itu, maka dakayu' ma si Elija?”",
        5: "Sabu pa'in iya ah'lling, aniya' gabun asahaya bay angalandungan sigām, maka aniya' suwala ah'lling min deyomna. Yuk suwala he', “Anakku ko' itu kalasahanku. Landu' aku kasulutan ma iya. Iya ya kalehunbi.”",
        6: "Pagkale pa'in suwala itu e' saga mulid inān, landu' to'ongan sigām tināw angkan kum'ppang magtūy sigām ni tana'.",
        7: "Sagō' pina'an si Isa ni sigām amat'ppak tanganna ma sigām. Yukna, “Pabungkal kam, da'a kam tināw.”",
        8: "Pagtongas sigām, halam aniya' saddī ta'nda' e' sigām, luwal si Isa.",
        9: "Manjari itu, sabu pa'in sigām palūd min būd e', binanda'an e' si Isa saga mulidna, yukna, “Da'a kam angahaka ni sai-sai pasal bay ta'nda'bi mahē' ma diyata' būd e'. Subay na aku, Anak Manusiya' itu, tapakallum pabīng min kamatayku bo' yampa kam angahaka.”",
        10: "Sakali tinilaw si Isa e' sigām, yuk-i, “Angay saga guru sara' agama magpina'in in si Elija subay dahū palahil pi'itu?”",
        11: "Anambung si Isa, yukna, “B'nnal ko' ilu, si Elija palahil dahū min Al-Masi anakapan kamemon.",
        12: "Sagō' haka'anta kam, bay na palahil si Elija pi'itu ati halam iya bay takilā e' saga manusiya'. Bay tahinang e' sigām ma iya ai-ai kabaya'an sigām. Damikiyanna aku, Anak Manusiya', bininasa du isab e' sigām.”",
        13: "Minnē' tahati e' saga mulidna si Yahiya Magpapandi iya pinagbissala e' si Isa.",
        14: "Na, makabīng pa'in disi Isa ni kaheka'an a'a he', aniya' dakayu' a'a pina'an ni iya angōk-tu'ut.",
        15: "Yukna ni si Isa, “Tuwan, ma'ase' pa'in ka ma anakku l'lla. Binawi-bawi iya, landu' iya abinasa. Araran iya pahantak ni api atawa ni bohe'.",
        16: "Bay bowaku iya ni saga mulidnu sagō' mbal iya kauli'an e' sigām.”",
        17: "Anambung si Isa, yukna, “Ka'am saga a'a ma tahun itu-i, asā' landu' pikilanbi! Halam to'ongan aniya' imanbi! Subay buwattingga gi' t'ggolku ma ka'am anandalan kabuwattilubi bo' yampa kam magkahagad? Bowahun pi'itu onde' ilu,” yukna.",
        18: "Tabowa pa'in onde' inān ni si Isa, magtūy pabukaganna saitan. Pinaluwas e'na min baran onde' ati saru'un-du'un du pahali sakina.",
        19: "Puwas e' tinilaw si Isa e' saga mulidna, sigām-sigām sadja. Yuk sigām, “Angay kami bay mbal makapaluwas saitan e'?”",
        20: "Yuk si Isa, “Sabab akulang pangandolbi ma Tuhan. Haka'anta kam to'ongan, abila bay makasali' heya pangandolbi ni buwat heya bigi-tinanom anahut, tahinangbi du kamemon minsan buwattingga hunitna. Bang saupama soho'bi būd itu papinda minnitu pina'an, papinda du. [",
        21: "Sagō' in ginis saitan ina'an-i mbal tapaluwas, luwal bang kam angamu'-ngamu' maka amuwasa dahū.]”",
        22: "Aniya' dakayu' waktu magtimuk saga mulid ma lahat Jalil. Yuk si Isa ni sigām, “Aku itu, Anak Manusiya', arai' na sinōngan ni pagbaya'an saga a'a,",
        23: "ati pinapatay aku e' sigām. Sagō' t'llumbahangi puwas min kamatayku allum du aku pabīng.” Minnē' asusa to'ongan saga mulidna.",
        24: "Pagt'kka si Isa maka saga mulidna ni da'ira Kapirnaum, aniya' pina'an ni si Petros saga a'a angā' sukay langgal. Yuk sigām ni iya, “Gurubi ilu, amayad sukay langgal bahā'?”",
        25: "“Aho',” yuk sambung si Petros. Makasōd pa'in si Petros ni deyom luma' arak angahaka, makarahū si Isa ah'lling ni iya, yukna, “Simun, bang ma ka'a, sai niā'an sukay e' saga sultan ma babaw dunya itu? Anak-kampungna ka, atawa a'a saddī?”",
        26: "“A'a saddī,” yuk si Petros. “Na,” yuk si Isa, “bang buwattilu, hatina in kitam panganak Tuhan itu mbal wajib magsukay.",
        27: "Sagō' mbal kitam bilahi kinap'ddi'an atay e' saga a'a inān, angkan ka subay pehē' ni bihing danaw inān amuwang. Pagtinduk daing, hella'un magtūy. Makabāk du ka sīn ma deyom bowa'na, sarang pamayadta sukay langgal. Ngā'un sīn inān bo' pamayarun pehē'.”",
    },
    18: {
        1: "Ma waktu he'-i du, pina'an ni si Isa saga mulidna atilaw iya, yuk sigām, “Sai alanga katapusan ma deyom pagparintahan Tuhan?”",
        2: "Sakali nilinganan e' si Isa dakayu' onde'-onde', sinō' an'ngge ma dahuwan sigām.",
        3: "Yuk si Isa, “Haka'anta kam to'ongan, sai-sai mbal apinda palantarana ni buwat palantara onde'-onde' itu, mbal to'ongan pinasōd ni deyom pagparintahan Tuhan.",
        4: "Sai-sai amareyo' atayna, pinasali' ni buwat atay onde'-onde' itu, ya na katapusan alanga ma deyom pagparintahan Tuhan.",
        5: "Sai-sai isab anaima' dakayu' onde'-onde' buwattitu ma sabab ōnku ya pamanyabutanna, sali' aku baranku ya tinaima' e'na.”",
        6: "Yuk si Isa lagi', “Bang aniya' a'a makaparusa ma dakayu' onde'-onde' buwattitu ya taga-pangandol ma aku, ahāp lagi' kadal a'a inān bang pa'in iya pinagantungan batu abuhat ma k'llongna bo' nihūg ni timbang.",
        7: "“Maka'ase'-ase' to'ongan saga manusiya' itu, sabab aniya' na pa'in sasat makaparusa ma sigām. Tantu paniya' saga sasat-manasat, sagō' maka'ase'-ase' sidda ya pamakadal ma sasuku anasat sehe'na amowa magdusa.",
        8: "Bang tanganbi atawa tape'bi ganta' amowa ka'am magdusa, subay paggatunbi. Gom na pa'in pukulinbi bo' tinimanan. Ahāp lagi' kam allum ma deyom sulga' ma apukul dambila' tanganbi atawa tape'bi, bang pa'in kam da'a nilarukan ni deyom api nalka' ya mbal kap'ddahan ma ajukup tape'-tanganbi.",
        9: "Damikiyanna isab bang matabi ganta' amowa ka'am magdusa, gom lagi' lugitunbi bo' tinimanan. Ahāp lagi' kam allum ma deyom sulga' ma abuta dambila' matabi, bang pa'in kam da'a nilarukan ni deyom api nalka' ma ajukup matabi karuwambila'.”",
        10: "“Kamaya'-maya' kam. Da'a palehomunbi saga kamanahutan itu. Sabab haka'anta kam, ina'an anunggu'an sigām saga mala'ikat ya paharap na pa'in ni Mma'ku Tuhan ma deyom sulga'.",
        11: "(In aku, Anak Manusiya', bay pi'itu ni dunya angalappas saga a'a ya alawak min Tuhan.)",
        12: "“Bistahunbi: bang saupama aniya' a'a taga-bili-bili dahatus hekana, bo' wa'i pasiha' dakayu', ai bahā' hinangna? Tantu pasagaranna siyampū' maka siyam mahē' ma kabīd-bīran bo' iya pasa'ut pehē' amiha dakayu' bay pasiha' he'.",
        13: "Jari bang tabākna na, haka'anta kam, kinōgan iya to'ongan. Palabi lagi' kakōganna ma bili-bili dakayu' inān min siyampū' maka siyam ya halam bay alungay.",
        14: "Buwattē' du isab Mma'bi ma deyom sulga', mbal iya bilahi aniya' alungay dakayu' onde'-onde' min okomanna.”",
        15: "“Na, bang aniya' pagkahinu ganta' makarusa ma ka'a, pehē' ka ni iya ati haka'in iya pasal kasā'anna. Sagō' subay hal ka'am duwangan magbissala. Bang ka kinale e'na, bo' kabaya'anna maghāp maka ka'a, pahogot gom pa'in kapagbagaybi.",
        16: "Sagō' bang hati mbal akuhanna dusana, bowahun dakayu' atawa duwa a'a saddī anaksi'an ai-ai pagbissalahanbi, bo' supaya tabeya' panoho'an bay ma Kitab, ya yuk-i, ‘Bang aniya' palkala'bi subay aniya' duwangan atawa t'llungan amuwan saksi' bo' supaya pinagsab'nnal.’",
        17: "Sagō' bang a'a inān agagga angasip ma saga a'a saddī ya bowanu inān, na, haka'in saga sehe'bi dajama'ahan kamemon. Jari bang iya mbal bilahi akale ma kagara'an saga jama'a kamemon, a'a inān subay niniyat e'bi sali' a'a halam aniya' tuhanna, atawa a'a maga'ā' sukay parinta.”",
        18: "“Haka'anta kam to'ongan, ai-ai lāngbi ma deyom dunya itu nilāng du isab ma deyom sulga', maka ai-ai parūlbi ma deyom dunya itu pinarūl du isab ma deyom sulga'.",
        19: "Aniya' isab pangahakaku ma ka'am, bang duwangan kam ma dunya itu maguyun angamu'-ngamu' ai-ai, tantu kam nirūlan e' Mma'ku ma deyom sulga'.",
        20: "Sababna bang aniya' duwangan atawa t'llungan a'a magtimuk pagka ōnku ya pamanyabutan sigām, ina'an du aku ma deyoman sigām.”",
        21: "Puwas ina'an pehē' si Petros ni si Isa atilaw. “Tuwan Panghū',” yukna, “min pila subay ampunku pagkahiku bang iya makarusa ma aku? Min pitu' bahā'?”",
        22: "Yuk si Isa, “Ngga'i ka hal min pitu', sagō' min pitumpū' maka pitu'.”",
        23: "Jari magparalilan si Isa, yukna, “In kapagparinta Tuhan sali' dalil dakayu' sultan ya bilahi amista palutangan saga tendogna.",
        24: "Sakali itu, hinabuna magbista utang, aniya' binowa ni iya dakayu' tendogna taga-utang laksa'an pilak.",
        25: "Jari in sīn ma tendog inān mbal makabayaran utangna, angkan magpanoho'an sultan in a'a inān sampay anak-h'ndana subay pinab'llihan nihinang ata. Subay pinab'llihan isab ai-aina kamemon pamayad utangna.",
        26: "Na, angōk-tu'ut magtūy tendog itu ma alopan sultan angamu' junjung ni iya. ‘O tuwan,’ yukna, ‘patangguhun gi' aku. Bayaranku du utangku kamemon.’",
        27: "Manjari ma'ase' sultan inān ma tendogna. Pinahalam na utangna ati pinapole' iya.",
        28: "“Na, pagluwas tendog inān min alopan sultan, aniya' talanggalna pagkahina, tendog sultan isab. In tendog damuli itu taga-utang dangkuri' ma tendog tagna'. Magtūy iya niragtu' maka pin'kkol e' tendog tagna'. Yukna, ‘Bayarin na utangnu ma aku.’",
        29: "Magtūy angōk-tu'ut tendog damuli itu anganjunjung, yukna, ‘Patangguhun gi' aku. Bayaranta du ka.’",
        30: "Sagō' mbal pinatanggu, gom pa'in ni'isi ni deyom kalabusu sat'ggol mbal makapuwasan utangna kamemon.",
        31: "Pag'nda' pa'in e' saga tendog kasehe'an ma kahinangan tendog tagna' inān, magtūy sigām landu' asukkal, ati pehē' ni sultan angahaka pasal pakaradja'an inān.",
        32: "“Jari pinalinganan e' sultan tendog bay aheka utangna he'. ‘Jahulaka' pahāp ka ilu!’ yukna. ‘Bay pahalamku utangnu kamemon ma sabab panganjunjungnu ma aku.",
        33: "Arapun ka'ase'annu pagkahinu he', buwat bay ka'ase'ku ma ka'a!’",
        34: "Jari sidda angastol sultan inān ma iya, angkan soho'na tendog e' ni'isi ni deyom kalabusu sampay tiniksa' sat'ggol halam gi' kabayaranna utangna.”",
        35: "Yuk si Isa, “Buwattē' du isab nihinang e' Mma'ku ma sulga' ma ka'am dangan maka dangan, bang mbal ampunbi pagkahibi min deyom ataybi.”",
    },
    19: {
        1: "Aubus pa'in pamissala si Isa buwattē', ala'an iya min lahat Jalil tudju ni lahat Yahudiya, ni jadjahan ma liyu sapa' Jordan.",
        2: "Aheka to'ongan saga a'a bay ameya' ma iya, ati kauli'an e'na saga saki sigām maina'an.",
        3: "Sakali aniya' pina'an saga Parisi anulayan iya bo' supaya iya tajallat ma bissalana. Yuk sigām ma iya, “Bang ma sara'tam, makajari bahā' bang l'lla animanan h'ndana, minsan ai sababanna?”",
        4: "Anambung si Isa, yukna, “Kilāku halam bay tabassabi ya tasulat ma Kitab, ya yuk-i, ‘Ma tagna' pamapanjari Tuhan ma manusiya', bay sigām pinapanjari e'na l'lla maka d'nda?’",
        5: "Yuk Tuhan e', ‘Angkanna l'lla ang'bba min ina'-mma'na bo' parakayu' ni h'ndana. Manjari in bay duwa baran, dabaran na.’",
        6: "Ngga'i ka na sigā duwa baran,” yuk si Isa, “sagō' dabaran na sigā karuwangan. Angkan subay mbal pinapagbutas e' manusiya' ya bay pinapagdakayu' e' Tuhan.”",
        7: "Atilaw saga Parisi ma si Isa, yuk-i, “Na angay bahā'? Bang ma pandu' si Musa, makajari l'lla animanan h'ndana bang pa'in aniya' sulatna pagpasahan.”",
        8: "Ya sambung si Isa, “Ya angkan kam pinarūl e' si Musa animanan h'ndabi, sabab agagga kam pinandu'an. Saguwā' ngga'i ka buwattē' bay ma waktu tagna'.",
        9: "Haka'anta kam, sai-sai animanan h'ndana ma halam bay angaliyu-lakad min iya, ati magh'nda iya saddī, taga-dusa iya angaliyu-lakad min h'ndana po'on.”",
        10: "Yuk saga mulid si Isa ma iya, “Bang buwattē' kahālanna ma a'a maglakibini, ahāp lagi' subay mbal magpūn.”",
        11: "Anambung si Isa, yukna, “Pandu' ilu mbal kabogbogan e' manusiya' kamemon, luwal sigām ya kabuwanan kosog e' Tuhan.",
        12: "Magginis isab pagsababan ya angkan l'lla mbal magh'nda. Aniya' a'a mbal makapagh'nda sabab aniya' salla' ma baranna. Aniya' mbal makapagh'nda sabab kinabili e' a'a, maka aniya' isab magniyat subay mbal magh'nda ma sabab pagparinta Tuhan ya pagmatayanna. Sai-sai makataima' pandu' itu, subay anaima' to'ongan.”",
        13: "Na, aniya' saga a'a bay amowa saga anak sigām ni si Isa bo' supaya pinat'nna'an tanganna maka niamu'an kahāpan min Tuhan. Sagō' bay pinabukagan saga a'a amowa inān e' kamuliran si Isa.",
        14: "Ah'lling si Isa, yukna, “Parūlunbi pi'itu ni aku saga kamanahutan itu. Da'a lāngunbi. Sabab sai-sai makasali' kaul-pi'ilna ni buwat kamanahutan ilu, taga-palsuku'an du ma pagparintahan Tuhan.”",
        15: "Jari pinat'nna' e' si Isa tanganna ni saga onde' inān, bo' yampa ala'an minnē'.",
        16: "Manjari itu aniya' dakayu' a'a pehē' ni si Isa. Yukna, “Tuwan Guru, kahāpan ai subay hinangku bo' supaya aku kaniya'an kallum taptap ni kasaumulan?”",
        17: "Yuk si Isa, “Angay aku tilawnu pasal kahāpan? Tunggal du Tuhan ahāp. Bang ka bilahi pinasuku'an kallum taptap, subay bogbogannu panoho'an Tuhan.”",
        18: "Atilaw gi' l'lla, yukna, “Panoho'an ingga?” Ya sambung si Isa, “Da'a ka amapatay a'a. Da'a ka angaliyu-lakad ni ngga'i ka paghola'nu. Da'a ka anangkaw. Da'a ka anaksi' puting.",
        19: "Pagaddatin ina'-mma'nu. Maka kalasahin pagkahinu manusiya' buwat e'nu alasahan barannu.”",
        20: "Yuk l'lla inān, “Ā, bay na kabogboganku ina'an-i kamemon. Ai gi' subay hinangku?”",
        21: "Yuk si Isa ma iya, “Bang ka bilahi tubus kahāp addat-tabi'atnu, pehē' ka, pab'llihin alta'nu kamemon bo' pamuwanun b'llihanna ma saga a'a miskin. Manjari aniya' du karayanu ma deyom sulga'. Puwas e' pi'itu ka ameya' ma aku.”",
        22: "Pagkale a'a inān ma bissala si Isa, magtūy iya ala'an, maka e'na asusa sabab landu' aheka alta'na.",
        23: "Sakali ah'lling si Isa ni saga mulidna, yukna, “Haka'anta kam to'ongan, in a'a dayahan kahunitan pasōd ni deyom pagparintahan Tuhan.",
        24: "Aho', haka'anta kam, kaluhayan gi' unta' palabay min buli' jalum min a'a dayahan pasōd ni deyom pagparintahan Tuhan.”",
        25: "Ainu-inu to'ongan saga mulid pagkale sigām ma bissala si Isa itu. “Bang buwattē',” yuk sigām, “sai bahā' makasampay ni kasalamatan ma deyom sulga'?”",
        26: "Pinandang e' si Isa saga mulidna he' maka e'na anambung. Yukna, “Bang manusiya' mbal to'ongan makarapat. Sagō' halam aniya' ahunit ma Tuhan.”",
        27: "Anambung lagi' si Petros, “Nda'un ba kami itu,” yukna. “Bay bbahan kami ai-ai kami kamemon bo' ameya' ma ka'a. Ai bahā' panungbas kami?”",
        28: "Yuk si Isa, “Haka'anta kam to'ongan: in aku Anak Manusiya', bang ta'abut na waktu kapaningkō'ku ma deyom kasahaya'an, magagi du aku ma dunya baha'u. Ya du ka'am saga bebeya'anku, pinatingkō' du isab ma tingkō'an sangpū' maka duwa hekana, ati nihukum e'bi saga bangsa panubu' si Isra'il kasangpū' maka duwa.",
        29: "Sasuku bay ang'bbahan luma'na atawa danakanna, atawa ina'-mma'na, atawa panganakna, atawa tana'na, ma sabab katuyu'na ma aku, tinungbasan du iya paheka e' Tuhan, lipat manglipat min bay bbahanna. Maka kaniya'an du iya kallum taptap ni kasaumulan.",
        30: "Sagō' aheka a'a makarahū buwattina'an, pinaramuli ma waktu sinōng. Aheka isab taramuli ma buwattina'an, pinarahū ma waktu sinōng.”",
    },
    20: {
        1: "Magparalilan si Isa, yukna, “In kapagparinta Tuhan sali' dalil a'a tag-dapu kabbun pananoman bahan anggul. Dai' llaw pa'in, pal'ngngan tag-dapu angā' a'a maghinang ma kabbunna.",
        2: "Tinambahan kono' sigām dakayu' denari, ya panamba dangan a'a ma dang'llaw. Magsulut pa'in, sinō' sigām pehē' maghinang ma kabbunna.",
        3: "“Na, ta'abut pa'in lisag siyam subu, pehē' tag-dapu ni pagtabu'an, ati aniya' ta'nda'na maina'an saga a'a hal an'ngge-n'ngge.",
        4: "Yukna ma sigām, ‘Pehē' kam isab maghinang ma kabbunku. Tambahanku du kam pila-pila ya katongoranbi.’",
        5: "Na, pehē' na sigām. Augtu pa'in llaw, pehē' na isab tag-dapu amiha a'a kasehe' maghinang ma kabbunna. Buwattē' du isab paglisag t'llu kohap.",
        6: "Jari itu, song pa'in lisag lima kohap, pabīng iya ni pagtabu'an, ati aniya' ta'nda'na saga a'a hal an'ngge-n'ngge maina'an. Yukna ma sigām, ‘Angay animpus llaw mbal kam maghinang?’",
        7: "“Yuk sambung sigām, ‘Tu'ud halam aniya' anoho' kami maghinang’. ‘Na,’ yuk tag-dapu, ‘pehē' kam maghinang ma kabbunku’.",
        8: "“Manjari itu, pagabay kohap na, amissala tag-dapu ni mandul pangandolanna, yukna, ‘Linganin saga maghihinang ilu bo' tambahin. Tambahin dahū saga a'a bay ta'ā'ku damuli ilu, bo' yampa sigām ya bay ta'ā'ku dahū.’",
        9: "Jari ya panamba saga a'a ya bay anagna' maghinang lisag lima kohap, magtongod maka hinang dang'llaw, minsan dai'-dai' du ya kapangahinang sigām.",
        10: "Na, ta'abut pa'in tinambahan saga a'a ya bay ta'ā' waktu subu lagi', aholat sigām tinambahan aheya. Sagō' sali' du tambahan ya tasambut sigām.",
        11: "Pagsambut pa'in, pinagmusmuran e' sigām tag-dapu.",
        12: "Yuk sigām, ‘Angay itu? Saga a'a bay ngā'nu damuli, danjām du bay pangahinang sigām. Bo' kami itu bay animpus min subu-subu sampay ni kakohapan, maghulas-sangsā' ma kapasu'an llaw! Sagō', papagsali'nu tambahan sigām maka tambahan kami.’",
        13: "Yuk tag-dapu kabbun ni dangan inān, ‘Bagay, halam ka bay akkalanku. Ya kapagsulutanta tambahan pinapagtongod maka hinang dang'llaw.",
        14: "Na, ngā'un na tambahannu itu bo' ka amole'. Tu'ud kabaya'anku pinapagsali' tambahan a'a bay ta'ā'ku damuli maka bay panambaku ka'a.",
        15: "Angay, halam bahā' aniya' kapatutku magbaya' ma sīnku? Angimbū ka bahā' pagga pagmuraku sīnku?’”",
        16: "Yuk si Isa isāb, “Sai-sai taramuli ma buwattina'an, pinarahū ma sinosōng. Maka sai-sai makarahū ma buwattina'an, pinaramuli ma waktu sinōng.”",
        17: "Na, patukad disi Isa tudju ni da'ira Awrusalam. Jari ma labayan pa'in, binowa e' si Isa mulidna kasangpū' maka duwa pasaddī min a'a kasehe'an bo' yampa sigām bissalahanna.",
        18: "Yukna, “Pakale kam. Itiya' kitam patukad ni Awrusalam. Mahē' pa'in, in aku Anak Manusiya' sinōngan du ni pang'ntanan kaimaman alanga maka saga guru sara' agama. Pinat'kkahan aku e' sigām hukuman ni kamatay.",
        19: "Puwas e' ni'nde'an du aku ni pang'ntanan saga a'a ngga'i ka Yahudi, ati pinagudju'-udju' aku e' sigām. Pinagdaplosan du aku bo' yampa nilansang ni hāg pinapatay. Sagō' ta'abut t'llumbahangi min kamatayku allum du aku pabīng.”",
        20: "Sakali pina'an ni si Isa h'nda si Sibidi beya' maka anakna l'lla duwangan, mulid si Isa asal. Pasujud d'nda itu ma dahuan si Isa angamu' junjung.",
        21: "Tinilaw iya e' si Isa, yukna, “Ai amu'nu?” Yuk d'nda, “Bang ta'abut waktu kapagparintanu, patingkō'un kono' duwangan anakku itu min karuwambila'nu.”",
        22: "Anambung si Isa, yukna, “Mbal kata'uwanbi bang ai ya amu'bi ilu. Makasandal kam bahā' pinananaman kabinasahan buwat paminasa ma aku?” “Aho', makasandal du kami,” yuk sigā.",
        23: "Yuk si Isa, “Asal makananam du kam kabinasahan buwat kabinasahan ya song pat'kka ni aku. Sagō' halam aniya' kapatutku amene' bang sai pinatingkō' ma bihingku kowan atawa ma bihingku gibang. Suku' ko' inān saga a'a ya tinagamahan paningkō'an ina'an-i e' Mma'ku Tuhan.”",
        24: "Takale pa'in e' saga sangpū' mulid kasehe' pasal bay niamu' e' h'nda si Sibidi, magtūy ap'ddi' atay sigām ma duwangan magdanakan e'.",
        25: "Angkan sigām kamemon sinoho' e' si Isa patimuk ni atagna. Yukna, “Kata'uwanbi kajarihan saga a'a ma dunya itu. Ya ang'ntanan pagparinta ma bangsa inān magmanda asal ma saga a'a ma deyo'an sigām. Ya du saga puntuk nakura' sigām, angahagda na pa'in.",
        26: "Sagō' ka'am ilu subay mbal magbuwattē'. Sai-sai kam bilahi taga-ōn ma deyomanbi, subay magsosoho'an ni kasehe'an.",
        27: "Sai-sai kam bilahi pinalanga, subay magpa'ata ni pagkahina.",
        28: "Buwat aku, ya Anak Manusiya'. Ya maksudku pi'itu ni dunya ngga'i ka aku subay pinaghulas-sangsā'an e' a'a kasehe', sagō' aku ya maghulas-sangsā' panabang sigām. Pi'itu aku bo' paglilla'ku kallumku pangal'kkatku saga a'a aheka min paldusahan sigām.”",
        29: "Manjari atulak pa'in disi Isa min da'ira Ariha, aheka a'a bay paturul ma iya.",
        30: "Sakali aniya' maina'an duwa l'lla buta aningkō' ma bihing lān palabayan sigām. Makata'u pa'in saga buta itu in si Isa ina'an palabay, magtūy sigā angalingan pakosog. “O Tuwan, tubu' Sultan Da'ud!” yuk sigā. “Ma'ase' ka ma kami.”",
        31: "Pinabukagan sigā e' kaheka'an a'a inān, sinō' da'a maghibuk. Sagō' pinakosog gom pa'in pangalingan sigā, yuk-i, “O Tuwan! Tubu' si Da'ud! Ma'ase' na ka ba!”",
        32: "Pahogga' si Isa bo' angalingan ni duwangan buta inān, yukna, “Ai kabaya'anbi hinangku ma ka'am?”",
        33: "“Tuwan,” yuk sigā, “bilahi kami maka'nda' pabīng.”",
        34: "Jari ma'ase' si Isa ma sigā, ati pinat'nna' tanganna ma mata sigā. Saru'un-du'un du sigā maka'nda' pabīng ati ameya' sigā paturul ma si Isa.",
    },
    21: {
        1: "Jari itu, asekot pa'in disi Isa ni da'ira Awrusalam, bo' ma tongod būd Kayu Jaitun na, ta'abut e' sigām kaluma'an Betpage. Mahē' pa'in, sinoho' e' si Isa duwangan mulidna parahū.",
        2: "Yukna, “Pehē' na kam ni kaluma'an ya ma dahuanbi ilu. Pagt'kkabi pina'an, makabāk du kam kura' maka anakna paengkot maina'an. Hubarinbi bo' bowahunbi pi'itu.",
        3: "Bang aniya' ganta' atilaw ka'am bang angay ngā'bi, haka'inbi buwattitu, yukbi, ‘Tu'ud pagguna e' nakura'.’ Jari pinasagaran du kam magtūy e'na.”",
        4: "Pinaniya' buwattē' bo' magtanda' ya bay pinagkallam e' dakayu' nabi, ya yuk-i,",
        5: "“Haka'inbi saga a'a Awrusalam, Ilu na sultanbi at'kka ni ka'am. Areyo' pangatayanna, angura' iya ma anak kura'.”",
        6: "Na, pehē' duwangan mulid e', nihinang e' sigā ya bay panoho'an si Isa.",
        7: "Binowa e' sigā kura' maka anakna, nilampikan maka badju' sigā bo' yampa pangura'an e' si Isa.",
        8: "Angura' pa'in iya, landu' aheka a'a bay am'llat s'mmek sigām ma lān palabayanna. Saga a'a kasehe' bay anabulakan pina'an saga engas-engas dahunan bay labasan sigām.",
        9: "Manjari ba'anan saga a'a ya magl'ngnganan min dahuan si Isa, sampay sigām paturul min buli'anna, magpangolang sama-sama yuk-i, “Mahaldika' ni tubu' sultan Da'ud! Bang pa'in binarakatan ya kawakilan e' Tuhan pi'itu! Sanglitantam Tuhan Mahatinggi!”",
        10: "Manjari pagt'kka si Isa ni Awrusalam, ahiluhala' deyom da'ira inān kamemon. Yuk saga a'a maina'an, “Sai bahā' a'a ilu?”",
        11: "Anambung kaheka'an, yuk sigām, “Si Isa ko' itu, nabi min Nasaret ma lahat Jalil.”",
        12: "Sakali itu pasōd si Isa ni deyom langgal pagkulbanan bo' yampa pinala'an e'na sasuku maglilitu maka magdagang maina'an. Binaliskat e'na lamisahan saga a'a magsambi'an sīn bangsa liyu ni sīn Yahudi. Ya du binaliskat e'na paningkō'an saga a'a magdagang assang pagkulban.",
        13: "Yuk si Isa ni saga a'a inān, “Tasulat asal ma Kitab Kanabi-nabihan bay pagkallam Tuhan, ya yuk-i, ‘Luma'ku itu niōnan luma' pagsambahayangan saga a'a.’ Sagō' tahinangbi na sali' luma' patapukan mundu.”",
        14: "Maina'an lagi' si Isa ma deyom langgal, pina'an ni iya saga a'a buta maka a'a pengka' ati kauli'an sigām e'na.",
        15: "Sagō' angastol saga kaimaman alanga maka saga guru sara' agama, pag'nda' sigām ma hinang si Isa makainu-inu inān, maka pagkale sigām ma saga onde' magpangolang ma deyom langgal, ya yuk-i, “Mahaldika' ni tubu' Sultan Da'ud!”",
        16: "Jari ah'lling saga nakura' inān ni si Isa, yuk sigām, “Takalenu bahā' ya pinah'lling e' saga onde'-onde' itu?” “Aho',” yuk si Isa. “Angay? Kilāku halam tabassabi ya tasulat ma Kitab Jabul, ya yuk-i, ‘Min kahandaknu saga kamanahutan amudji ōnnu, saga anak duru'an lagi' ananglitan ka'a.’”",
        17: "Puwas e' ala'an si Isa min sigām bo' paluwas min da'ira tudju ni kaluma'an Betani. Pahanti' iya mahē' dambahangi.",
        18: "Pagk'llat llaw, ma labayan pa'in si Isa tudju ni Awrusalam pabīng, lingantu iya.",
        19: "Ta'nda'na dampo'on kayu igira ma bihing lān, sagō' pagpehē'na, halam aniya' buwa' tabākna maina'an, luwal dahun. Jari sinapdahan e' si Isa kayu inān, yukna, “Puwas minnitu, kayu itu mbal to'ongan magbuwa' pabīng.” Magtūy alanos kayu inān.",
        20: "Pag'nda' saga mulidna, ainu-inu sigām. “Allā,” yuk sigām, “angay kayu igira itu alanos saru'un-du'un?”",
        21: "“Na, haka'anta kam to'ongan,” yuk si Isa, “bang kam angandol to'ongan ma halam aniya' hawal-hawal deyom ataybi, makahinang du kam buwat bay hinangku ma kayu igira itu. Maka ngga'i ka hal e'-i. Minsan būd inān, bang soho'bi ala'an min baina bo' pat'nna' ni deyom s'llang, tantu du ameya'.",
        22: "Bang kam angandol, tasambutbi du ai-ai pangamu'-ngamu'bi ni Tuhan.”",
        23: "Jari pabīng na si Isa ni deyom langgal pagkulbanan bo' amandu'. Sabuna pa'in amandu', pina'an ni iya saga kaimaman alanga maka saga pagmatto'ahan Yahudi. Yuk sigām, “Ai kapatutnu maghinang ka buwattilu? Sai bay amuwanan ka'a kapatut?”",
        24: "Anambung si Isa, yukna, “Aniya' dakayu' patilawku ma ka'am dahū. Bang itu sambunganbi, haka'anta du kam bang ai kapatutku maghinang buwattitu.",
        25: "Ya bay kapatut si Yahiya magpandi saga a'a, kapatut min Tuhan bahā' atawa min manusiya' sadja?” Na, magisun-isun sigām, yuk-i, “Bang saupama yukta in kapatut si Yahiya inān bay min Tuhan, tantu kitam tinilaw e'na bang angay kitam halam bay magkahagad ma si Yahiya.",
        26: "Sagō' bang yukta in kapatut si Yahiya inān min manusiya' sadja, na piligdu kitam. Sabab saga a'a itu magkahagad kamemon in si Yahiya nabi min Tuhan.”",
        27: "Angkan buwattitu ya panambung saga nakura' ma panilaw si Isa, yuk-i, “Mbal kata'uwan kami.” “Na,” yuk si Isa, “ya du aku mbal angahaka'an ka'am bang minningga ya kapatutku maghinang saga hinang itu.”",
        28: "Amissala si Isa, yukna, “Pikilunbi paralilanku itu. Aniya' a'a duwa anakna l'lla. Na pehē' a'a itu ni anakna siyaka, yukna, ‘Otō', pehē' ka llaw ilu maghinang ma kabbun.’",
        29: "Yuk sambung siyaka he', ‘Mbal aku.’ Saguwā' apinda pikilanna ati pehē' iya ni kabbun maghinang.",
        30: "Jari pehē' a'a itu ni anakna siyali, anoho' iya maghinang buwat bay panoho'anna ma siyaka. ‘Aho', Mma',’ yuk sambung siyali. Sagō' halam iya bay pehē'.",
        31: "Na,” yuk si Isa ni saga a'a inān, “bang ma ka'am, sai ya bay ameya' ma kabaya'an mma'na?” “Ya anak siyaka,” yuk sambung sigām. “Haka'anta kam to'ongan,” yuk si Isa, “saga a'a dusahan, ya buwat maga'ā' sukay parinta maka d'nda ala'at, parahū sigām min ka'am ameya' ma pagparinta Tuhan.",
        32: "Sabab si Yahiya Magpapandi bay pi'ilu ni ka'am amata'uwan ka'am bang ingga ya lān abontol, sagō' halam iya bay kahagadbi. Malaingkan saga a'a magā' sukay parinta maka saga d'nda ala'at, bay magkahagad. Maka minsan ta'nda'bi ina'an-i, halam bay apinda pikilanbi bo' kam magkahagad ma si Yahiya.”",
        33: "“Pakale kam ma paralilan dakayu' itu,” yuk si Isa. “Aniya' dakayu' a'a tag-dapu tana' bay ananom bahan anggul ma kabbunna. Nilikus e'na maka ād, kinali e'na lowang pagp'gga'an buwa' anggul, maka nihinang e'na pamantawan alanga. Puwas e' patunggu'anna kabbun inān ma saga magtutunggu', bo' yampa iya atulak ni lahat saddī.",
        34: "Ta'abut pa'in musim pagpusu' buwa' anggul, sinoho' e' tag-dapu kabbun saga sosoho'anna pehē' ni saga magtutunggu' angā' palsuku'anna.",
        35: "“Sagō' pagt'kka pehē' saga sosoho'an itu, sinaggaw sigām e' magtutunggu'. Dakayu' sosoho'an inān bay niraplosan, dakayu' bay pinapatay, dakayu' isab bay pinagbantung.",
        36: "Puwas e' in tag-dapu bay amapehē' saga sosoho'an saddī, aheka lagi' min bay dahū. Ya du sigām bay nila'at e' saga tunggu', buwat bay pangala'at sigām ma sosoho'an tagna'.",
        37: "Na, ma katapusan, bay pinapehē' anak tag-dapu, sabab pangannalna, ‘Tantu pinagaddatan anakku e' saga tunggu' he'.’",
        38: "“Sagō' pag'nda' saga tunggu' ma anak tag-dapu itu, magtūy sigām magisun, yuk-i, ‘Ya na ko' ilu anak tag-dapu. Sūng kitam, papataytam iya bo' ta'ā'tam tana'na.’",
        39: "Manjari sinaggaw e' sigām anak tag-dapu. Nijudjalan iya paluwas min likusan, bo' pinapatay.",
        40: "“Na,” yuk si Isa, “bang at'kka tag-dapu kabbun pehē', ai bahā' hinangna ma saga a'a magtutunggu'?”",
        41: "Anambung sigām, yuk-i, “Tantu papatayna saga pilliyu inān. Patunggu'anna kabbunna ma a'a saddī, ya bilahi ang'nde'an palsuku'anna bang ta'abut musimna.”",
        42: "Yuk si Isa ni sigām, “Halam bahā' tabassabi ayat Kitab ya yuk-i, ‘Ya batu bay sinulak e' a'a maghinang luma', ya na batu manjari pamapagon luma'. Hinang Tuhan ko' inān, landu' ahāp ma pang'nda' kami.’",
        43: "“Angkan kam haka'anku,” yuk si Isa, “nila'anan du min ka'am bay palsuku'anbi ma deyom pagparintahan Tuhan bo' pinapinda ni a'a saddī bangsa. Jari sigām ya amaluwas kahāpan ya tōp ma pagparintahan Tuhan. [",
        44: 'Sasuku ahūg ni batu itu atumu-tumu du baranna. Maka sasuku kahūgan batu itu apipis du kamemonna.]”',
        45: "Pagkale e' saga kaimaman alanga maka e' saga Parisi ya pamaralil e' si Isa itu, magtūy tasayu in sigām ya pina'andigan e'na.",
        46: "Angkan sigām bilahi anaggaw si Isa, sagō' halam kalandu'an. Tināw sigām ma kaheka'an a'a inān sabab dī nabi si Isa bang ma bistahan sigām.",
    },
    22: {
        1: "Manjari magparalilan si Isa pabīng ma saga a'a, yukna,",
        2: "“In kapagparinta Tuhan sali' dalil sultan bay magsakap pagjamu ma waktu kapagkawin anakna l'lla.",
        3: "Sinoho' e' sultan saga ipatanna amata'u saga a'a ya bay sinō' paluruk. Sagō' mbal ameya'.",
        4: "“Angkan aniya' ipatan saddī pinapehē' e' sultan. Yukna ni sigām, ‘Pata'uhunbi saga a'a ya soho'ku paluruk in pagjamuku sakap na. Bay na sinumbali' saga sapi'ku l'lla maka saga anak sapi' al'mmok. Sakap na kamemon. Sō'un sigām paluruk na ni pagkawinan.’",
        5: "Sagō' agagga saga a'a inān, sabab aniya' gawi sigām saddī. Dangan inān wa'i ni humana maghinang, dangan ni tindana,",
        6: "kasehe'an bay anaggaw saga sosoho'an sultan inān. Niraplosan e' sigām maka pinapatay.",
        7: "Pagta'u pa'in sultan, landu' akagit atayna angkan soho'na tumpukan sundaluna pehē' amapatay saga pamomono' he'. Sinō' isab tinunu' kaluma'an sigām.",
        8: "Puwas e' nilinganan e' sultan saga ipatanna, yukna, ‘Sakap na jamu pagkawin sagō' mbal na tōp saga a'a bay ta'abbitku.",
        9: "Jari pehē' kam ni lān aheka a'ana, ati sō'unbi paluruk sasuku tabākbi mahē'.’",
        10: "Angkan pehē' saga ipatan inān ni kalān-lānan amatimuk sasuku a'a tabāk e' sigām, a'a ahāp ka atawa ala'at. Jari in luma' pagkawinan e' ap'nno' e' luruk.",
        11: "“Sakali itu, makasōd pa'in sultan pehē' ang'nda' ma saga luruk, aniya' ta'nda'na maina'an dakayu' a'a amakay s'mmek mbal tōp ma pagkawinan.",
        12: "Yuk sultan ni a'a itu, ‘Bagay, buwattingga kasōdnu pi'itu ma halam aniya' s'mmeknu tōp ma pagkawinan?’ Sagō' halam anambung a'a inān.",
        13: "Angkan ah'lling sultan ni saga sosoho'anna, yukna, ‘Engkotinbi tape'-tangan a'a itu, bo' larukinbi iya pehē' ni deyom kalendoman. Magtangis saga a'a maina'an maka magtage'ot empon kabowa susun sigām.’",
        14: "“Sababna,” yuk si Isa, “aheka a'a tina'abbit ameya' ma pamarinta Tuhan, sagō' salat du tapene'.”",
        15: "Na, paluwas saga Parisi minnē' bo' magisun bang buwattingga e' sigām anganjallat si Isa ma bissalana.",
        16: "Jari aniya' saga mulid sigām maka saga bebeya'an si Herod pinapehē' ni si Isa. “Tuwan Guru,” yuk sigām ma iya, “kata'uwan kami in ka'a apote' asal ataynu. B'nnal sadja pamandu'nu pasal kaul-pi'il ya kinabaya'an e' Tuhan. Mbal ka tināw sinoway e' sai-sai, sabab sali' du bowahannu ma a'a kamemon.",
        17: "Na, haka'in kami kono' bang ai pikilannu pasal itu-i: bang kita ganta' amayad sukay ni parinta Rōm, ya deyo' min Sultan Mahatinggi he', langgalta bahā' sara' agamatam?”",
        18: "Sagō' kinata'uwan asal e' si Isa aniya' kala'atan minaksud e' sigām, angkan yukna ni sigām, “Ka'am ilu hal magbau'-bau' atilaw buwattilu. Tu'ud kam bilahi anganjallat aku ma panambungku.",
        19: "Panda'in aku sīn, ya pamayad sukay parinta.” Jari binowahan iya sīn atibu'uk.",
        20: "Yuk si Isa ma sigām, “Patta' sai maka ōn sai ma sīn itu?”",
        21: "“Patta' Sultan Mahatinggi maka ōnna,” yuk sambung sigām. “Na,” yuk si Isa, “pagka suku' sultan, pamayarunbi ni sultan. Damikiyanna, bang aniya' ai-ai suku' Tuhan, tukbalinbi isab ni Tuhan.”",
        22: "Pagkale saga a'a inān ma panambung si Isa itu, magtūy sigām ainu-inu ati ang'bba sigām min iya bo' ala'an minnē'.",
        23: "Na ma llaw du ina'an, aniya' pina'an ni si Isa saga a'a min umpigan Saddusi. Atilaw sigām ma iya,",
        24: "“Tuwan guru, aniya' sara' bay min si Musa pasal l'lla amatay ma halam taga-tubu'. In baluna subay niā' h'nda e' siyalina bo' supaya aniya' anak binista tubu' min a'a bay amatay he'.",
        25: "Na,” yuk sigām, “aniya' bay ma lahat kami pitu' l'lla magdanakan. Taga-h'nda kasiyakahan he', sagō' amatay ma halam aniya' tubu'na. Jari baluna bay ta'ā' h'nda e' siyali pasunu'.",
        26: "Sagō' ya du siyali itu, bay amatay ma halam taga-tubu'. Damikiyanna isab siyali pasunu'. Papu'utta na, in pitu' magdanakan bay makah'nda ni dakayu' d'nda he', bo' amatay sigām kamemon ma halam taga-anak.",
        27: "Ma katapusanna amatay isab d'nda.",
        28: "Na, Tuwan,” yuk sigām, “bang ta'abut llaw pagpakallum pabalik saga a'a magpatayan, h'nda sai bahā' d'nda he'? Sabab bay iya ta'ā' h'nda e' sigām kapitu' magdanakan.”",
        29: "Anambung si Isa ma sigām, yukna, “Asā' kam, sabab halam kata'uwanbi bang ai tasulat ma Kitab, maka mbal kata'uwanbi kosog kawasa Tuhan.",
        30: "Sabab bang ta'abut waktu kallum pabīng min kamatay, in manusiya' makasali' du ni bangsa mala'ikat ma deyom sulga'. Mbal na sigām magh'nda-magh'lla.",
        31: "Ya pasal isab saga a'a pinakallum pabīng min kamatay, kilāku halam tabassabi bay pangallam Tuhan ma ka'am, ya yuk-i,",
        32: "‘Aku ya Tuhan disi Ibrahim, si Isa'ak maka si Yakub.’ In Tuhan itu,” yuk si Isa, “pagtuhanan asal ma saga a'a allum, ngga'i ka ma a'a magpatayan.”",
        33: "Makakale pa'in kaheka'an a'a inān ma bissala si Isa inān, sidda sigām ainu-inu.",
        34: "Sakali itu, pagkale saga Parisi in si Isa bay makatambol bowa' saga Saddusi he', pina'an sigām patimuk ni iya.",
        35: "Aniya' ma sigām dakayu' guru sara' agama bay atilaw si Isa, kalu tajallat ma panambungna.",
        36: "Yukna, “Tuwan Guru, ma sara' agama, ingga ya panoho'an ahalga' min kamemon?”",
        37: "Yuk sambung si Isa, “Wajib kam alasa to'ongan ma Panghū'bi Tuhan. Ya lasabi ma iya subay min deyom ataybi maka min deyom tawhidbi maka min panahu'anbi.",
        38: "Ya na ko' he' panoho'an umbul dakayu', ahalga' min kamemon.",
        39: "Maka ya na itu panoho'an karuwana, ahalga' isab: wajib kam alasahan pagkahibi manusiya' buwat e'bi alasahan baranbi.",
        40: "Ya panoho'an kamemon bay pang'bba e' si Musa, sampay pamandu' saga nabi, luwas du min duwa panoho'an tasabbutku itu.”",
        41: "Hinabu magtimuk maina'an saga Parisi, aniya' tinilaw e' si Isa ma sigām,",
        42: "yuk-i, “Ai pikilanbi pasal Al-Masi? Tubu' sai iya?” Ya sambung sigām, “Tubu' sultan Da'ud.”",
        43: "“Na bang buwattē',” yuk si Isa, “angay angkan si Da'ud bay angōn ‘Panghū'’ ma Al-Masi, ma waktu kapagbaya' Rū Tuhan ma iya? Buwattitu bay pagkallam si Da'ud e',",
        44: "‘Bay angabtang Tuhan ni Panghū'ku, yukna, dai' ka aningkō' ma bihingku kowan, ati bowaku palbantahannu tatau' ma deyo' pād-tape'nu.’",
        45: "Na,” yuk si Isa, “pagka Al-Masi itu niōnan Panghū' e' sultan Da'ud, tantu iya ngga'i ka hal panubu' si Da'ud.”",
        46: "Jari halam aniya' a'a makapanambung ma si Isa minsan dakabtang. Puwas minna'an halam aniya' makatawakkal anilaw iya.",
    },
    23: {
        1: "Manjari ah'lling si Isa ni katimukan a'a maka ni saga mulidna.",
        2: "Yukna, “Aniya' kapatut saga guru sara' agama maka saga Parisi amandu'an a'a pasal saga sara' si Musa.",
        3: "Angkan subay beya'bi ai-ai pamandu' sigām. Subay ikutbi pahāp pamissala sigām. Sagō' da'a panunurinbi kahinangan sigām, sabab halam tabeya' e' sigām ya bay pamandu' sigām ma a'a kasehe'an.",
        4: "Pinabuhat e' sigām saga panoho'an ya pamatanggung sigām ma saga a'a kasehe'an, sagō' mbal sigām bilahi anabang ma saga a'a inān, minsan la'a hal tabang ariki'.",
        5: "Ai-ai nihinang e' saga Parisi maka saga guru he' subay ma matahan kaheka'an a'a. Nda'unbi kaheya puyu'-puyu' pangisihan ayat Kitab ya pin'kkos ma tuktuk maka ma l'ngngon sigām. Nda'unbi isab juba sigām, kataha' jambayna.",
        6: "Bang sigām ganta' ma pagjamuhan, kabilahian sigām subay pinatingkō' ma paningkō'an bangsahan. Ya du bang sigām ma deyom langgal, subay paningkō'an ya tinau'an a'a alanga.",
        7: 'Bilahi sigām nihulmat bang ma mairan, bilahi isab pinagsabbut ‘Tuwan Guru.’',
        8: "“Sagō' ka'am ilu subay mbal angangut niōnan ‘Tuwan Guru’ e' pagkahibi, sabab in ka'am magdauranakan kamemon, maka dakayu' du gurubi luggiya'.",
        9: "Da'a panabbutinbi ‘Mma'’ sai-sai ma deyom dunya itu, sabab dakayu' du pag'mma'anbi, ya Tuhan ma deyom sulga'.",
        10: "Da'a kam mikiōn nakura', sabab tunggal Al-Masi ya pagnakura'anbi.",
        11: "Sai-sai bilahi alanga ma deyomanbi, subay iya magpa'ata ma kasehe'anna.",
        12: "Sai-sai magpalanga ma baranna, pinareyo' du iya, maka sai-sai amareyo' di-na pinalanga du isab.”",
        13: "“Maka'ase'-ase' sidda ya pamakadal ka'am, saga guru sara' agama maka saga Parisi!” yuk si Isa. “Magbau'-bau' sadja kam in ka'am ahāp addatbi, sagō' tambolanbi saga a'a bo' supaya sigām mbal makasōd ni deyom pagparintahan Tuhan. Ka'am baranbi ilu mbal bilahi pasōd pina'an, maka lāngbi isab sasuku bilahi pasōd. [",
        14: "Maka'ase'-ase' sidda ya pamakadal ka'am, saga guru sara' agama maka saga Parisi, ya magbau'-bau' in ka'am ahāp! Ni'inyaya e'bi saga d'nda balu bo' ta'ā'bi luma' sigām, ati pataha'bi panambahayangbi paglaku-lakubi in ka'am bal-iman, bo' pa'in katapukan kahinanganbi ala'at. Angkan pinakalap kabinasahanbi ma ahirat.]",
        15: "“Maka'ase'-ase' sidda ya pamakadal ka'am, saga guru maka saga Parisi! Magbau'-bau' kam ahāp addatbi! Atuyu' kam amasaplag pandu'bi, ya angkan lintasbi deya-dilaut bang pa'in aniya' tabowabi ameya' ma pandu'bi minsan la'a hal dakayu' a'a. Ati bang aniya' ganta' makabeya', akalap gi' iya min ka'am pinaganta'an nalka', ma sabab pamandu'bi ya pameya'anna.",
        16: "“Maka'ase'-ase' sidda ya pamakadal ka'am! Sali' kam sapantun a'a buta angambit pagkahina. Yuk pamandu'bi, bang aniya' anganjanji' bo' sabbutna langgal pagkulbanan palsaksi'an janji'na, halam du aniya' dusana minsan mbal suhulna bay janji'na he'. Sagō' bang kapanyapan bulawan ma deyom langgal ya panabbutanna, wajib kono' subay suhulna to'ongan.",
        17: "Asā' landu' pikilanbi, bā'nu kam abuta! Langgal inān asal pangarapan ni Tuhan, angkan yukta asussi kapanyapanna.",
        18: "Aniya' isab pamandu'bi dakayu', yuk-i, sai-sai anabbut tongod pagkulbanan palsaksi'an janji'na, makajari minsan mbal sinuhul janji'na. Sagō' bang panabbutanna ai-ai tinukbalan ni Tuhan ma diyata' pagkulbanan e', in janji'na kono' wajib subay sinuhul to'ongan.",
        19: "Asā' landu' pikilanbi! Ingga aheya gunana, ya ai-ai tinukbalan ma diyata' pagkulbanan, atawa pagkulbanan sussi, ya makabuwan kasussihan isab ma tutukbalan e'?",
        20: "Angkanna, bang aniya' a'a ganta' anabbut pagkulbanan, panabbutanna isab kamemon ya tinukbalan ni Tuhan maina'an.",
        21: "Damikiyanna, bang aniya' anabbut langgal pagkulbanan, panabbutanna isab Tuhan ya pat'nna' asal maina'an.",
        22: "Bang aniya' anabbut sulga', panabbutanna isab paningkō'an Tuhan maka panabbutanna isab Tuhan.",
        23: "“Maka'ase'-ase' sidda ya pamakadal ka'am, saga guru sara' maka saga Parisi! Magbau'-bau' kam ahāp addatbi. Atukid sidda kam anukbal ni Tuhan bahagi' sangpū' min ai-aibi kamemon, minsan la'a hal ginisan sayul-sayul ya pamapābi kinakan. Ahāp isab kapanukbalbi buwattē', da'a subay ni'bbahan, sagō' ya panoho'an ahalga' min kamemon halam kabogboganbi. Mbal kam a'adil, mbal kam ma'ase' ma pagkahibi, mbal kam kapangandolan. Arapun ilu-i panuyu'anbi to'ongan dahū min kamemon.",
        24: "Sali' kam a'a buta ya angambit sehe'na. Sapantun kam a'a angayak inumanna bo' mbal makainum kammut, bo' pa'in tat'llonna unta' ma katibu'ukanna.",
        25: "“Maka'ase'-ase' sidda ya pamakadal ka'am, saga guru maka saga Parisi! Magbau'-bau' kam ahāp addatbi. Sali' kam sapantun sawan maka lai. Kose'anbi luwasanna sagō' haram deyomna sabab ap'nno' e' pangalangpasbi maka pagnapsubi dumasiyaw.",
        26: "Ka'am saga Parisi, asā' sidda pikilanbi! Lanu'inbi dahū deyomna ati alanu' sampay luwasanna.",
        27: "“Maka'ase'-ase' sidda ya pamakadal ka'am, saga guru maka saga Parisi! Magbau'-bau' kam ahāp addatbi. Sali' kam sapantun kubul bay pininta pote' luwasanna bo' ahāp ninda', sagō' deyomna akansang e' to'olang mayat maka ginis kahalu'an.",
        28: "Buwattē' isab hantangbi. Bang pangluwahanbi ta'nda' e' a'a, ahāp sadja, sagō' deyom ataybi ilu ap'nno' e' pagbau'-bau'bi maka kala'atanbi.”",
        29: "“Maka'ase'-ase' ya pamakadal ka'am, saga guru maka saga Parisi! Magbau'-bau' kam ahāp addatbi. Tahinangbi tampat ma kanabi-nabihan, tapa'altibi saga kubul bay pangubulan a'a ka'adilan.",
        30: "Yukbi isab, ‘Bang bay kami allum ma waktu ka'mbo'an kami he', mbal du kami bay palamud ma hinang saga a'a kasehe'an, ya kapamapatay sigām ma saga nabi he'.’",
        31: "Na,” yuk si Isa, “pagka buwattilu pah'llingbi, magpasab'nnal kam in ka'am panubu' min saga a'a bay amono' kanabihan e'.",
        32: "Pehē'unbi na, talusunbi saga dusa ya bay tinagna'an e' ka'mbo'anbi.",
        33: "“Mbal tasipat la'atbi! Halam aniya' kaholatanbi papuwas min hukuman nalka'.",
        34: "Haka'anta kam, papi'iluku du ni ka'am saga nabi, saga a'a bal-akkal, maka saga guru. Bono'bi du sigām kasehe', kasehe' isab lansangbi du ni hāg pinapatay, kasehe' daplosanbi ma deyom langgal, maka kasehe'an turulbi du min kaluma'an dakayu' ni dakayu'.",
        35: "Angkan kam pinat'kkahan hukuman, ma sabab kapamapataybi ma saga a'a halam taga-dusa, tinagna'an min si Habil anak si Adam, sampay ni si Jakariya anak si Baraki. Si Jakariya he' bay pinapatay e' bangsabi ma llotan langgal maka tongod pagkulbanan.",
        36: "Haka'anta kam to'ongan, ka'am ma ahil jaman itu pamatanggungan du karusahan saga a'a inān kamemon.”",
        37: "Magkarukka'an si Isa yukna, “Arōy! Ka'am saga a'a Awrusalam, makasusa ko' ka'am ilu! Saga nabi min Tuhan hal papataybi. Saga sosoho'an Tuhan hal bantungbi bang pinapi'ilu ni ka'am. Min pila aku bay bilahi animuk ka'am ma sabakanku, sali' sapantun manuk d'nda bang magsabak anak-anakna ma deyo' pikpikna. Sagō' mbal kam.",
        38: "Nda'unbi na, asiya-siya lahatbi e' Tuhan.",
        39: "Haka'anta kam, mbal na aku ta'nda'bi pabalik sampay ni waktu kapananglitbi ma aku, ya yukbi, ‘Bang pa'in binarakatan ya pinapi'itu kawakilan e' Tuhan.’”",
    },
    24: {
        1: "Manjari itu, makaluwas pa'in si Isa min langgal pagkulbanan, pasekot ni iya saga mulidna anudlu' hinangan langgal e'.",
        2: "Yuk si Isa, “Ta'nda'bi kahāpna. Sagō' haka'anta kam, ma sinosōng in langgal itu alubu du. Halam aniya' batuna angapin magbangkat, kinanat du kamemon.”",
        3: "Puwas e', aningkō' pa'in si Isa mahē' ma būd Jaitun, pehē' ni iya saga mulidna, sigām-sigām sadja. Yuk sigām, “Pahatiun kono' kami bang sumiyan paniya' ya bay yuknu insini', maka bang paltanda'an ai pinatuwa' bo' kinata'uwan in kapi'itunu asekot na, maka dunya itu song kiyamat na?”",
        4: "Anambung si Isa, yukna, “Kamaya'-maya' kam bo' kam mbal ka'akkalan.",
        5: "Sabab ma sinosōng aheka pi'itu anabbut ōnku, maglaku-laku in sigām Al-Masi, ati aheka tabowa-bowa niakkalan e' sigām.",
        6: "Makakale du kam pasal pagbono' ma kasekotan. Makakale kam isab hunub-hunub pasal pagbono' ma lahat saddī. Sagō' da'a kam tināw. Tantu paniya' pagbono' sagō' ngga'i ka ina'an-i llaw kiyamat.",
        7: "Magbono' du bangsa dakayu' maka dakayu', parinta dakayu' isab maka parinta dakayu'. Paniya' isab gotom ma sabarang lahat, maka linug ma kaluha'an dunya.",
        8: "Sagō' in bala' kamemon itu hal tagna'anna sadja, sali' dalil d'nda ab'ttong bang yampa tananamna amuka' puhu'.",
        9: "“Bang at'kka saga pakaradja'an ina'an-i, sinaggaw du kam, tinukbalan ni saga a'a bo' kam bininasa sampay pinapatay. Kinab'nsihan du kam e' a'a kamemon ma sabab pameya'bi ma aku.",
        10: "Ma waktu ina'an aheka a'a bay bebeya'anku ang'bba min pagiman sigām. Aheka isab magla'at-liya'ati maka anukbal pagkahi sigām ni saga a'a ab'nsi ma si Isa.",
        11: "Aheka maglaku-laku in sigām nabi min Tuhan, maka aheka tabowa niakkalan e' sigām.",
        12: "Pasōng na pa'in kala'atan indaginis ma waktu sinōng inān, angkan kaheka'an manusiya' mbal na maglasa-liyasahi.",
        13: "Sagō' lappasan du sai-sai ahogot imanna sampay ni kahinapusan.",
        14: "Maka lapal ahāp pasal kapagparinta Tuhan, pinagnasihat na pa'in ma kaluha'an dunya supaya pasaplag saksi' pasal si Isa ni sabarang bangsa. Puwas e' kiyamat na dunya.”",
        15: "“Takallam asal e' nabi Daniyel ma pasal waktu sinōng inān, yukna, aniya' ‘kasammalan makaharam’ pat'nna' ma deyom langgal mahasussi. Sasuku kam amassa, sinō' pahati. Bang ta'nda'bi ina'an-i,",
        16: "sasuku a'a pat'nna' ma lahat Yahudiya subay alahi pehē' ni kabūd-būran.",
        17: "Bang aniya' a'a ganta' ma luwasan luma'na subay mbal sōdna luma'na angā' ai-aina.",
        18: "Bang aniya' a'a ma humana subay mbal batukna badju'na paghaggut.",
        19: "Ndū', maka'ase'-ase' saga d'nda ab'ttong ma masa ina'an-i, maka saga d'nda taga-anak duru'an lagi'.",
        20: "Amu'inbi ase' ni Tuhan bang pa'in ya llaw kalahibi inān mbal magsabu maka musim haggut atawa llaw Sabtu', ya paghalibi ni Tuhan.",
        21: "Sababna saga kabinasahan ya patumbuk ma masa sinōng inān,” yuk si Isa, “akalap gi' bisana min kabinasahan kamemon bay kalabayan manusiya' sangay min tagna' kapaniya' dunya, sampay ni kabuwattina'anan. Maka mbal isab kabalikan.",
        22: "Daipara kinulangan du e' Tuhan t'ggol kabinasahan inān. Bang bay mbal, halam aniya' angapin allum. Kinulangan du e' Tuhan ma sabab saga a'ana, ya asal tapene'na.",
        23: "“Na, bang ta'abut waktu ina'an-i, bo' aniya' ganta' anuhuma ni ka'am, yuk-i, ‘Nda'unbi! Itiya' na Al-Masi,’ atawa ‘Ina'an na iya maina'an’, da'a to'ongan kahagarunbi.",
        24: "Sabab ma waktu ina'an aniya' du patuwa' saga a'a magnahu'-nahu' in sigām Al-Masi, atawa in sigām nabi min Tuhan. Magpa'nda' sigām saga hinang barakatan maka saga paltanda'an kainu-inuhan a'a, bo' supaya ka'akkalan sampay a'a suku' Tuhan, bang hati' tabowa niakkalan.",
        25: "Pakale kam,” yuk si Isa. “bay na kam pata'uku ma pasal ina'an-i ma halam gi' ta'abut waktuna.",
        26: "“Angkan ko', bang aniya' angupama ni ka'am, yuk-i, ‘Ina'an Al-Masi ma lahat halam maga'a’, da'a kam pehē'. Atawa bang yukna, ‘Ina'an iya patapuk maina'an’, da'a beya'unbi.",
        27: "Sabab aku Anak Manusiya' itu, bang aku pabalik na, ta'nda' du kapi'ituku, buwat lāt aninagan b'ttong langit min sobangan sampay ni s'ddopan.”",
        28: "Magparalilan si Isa, yukna, “Maingga-maingga lahat kaniya'an patay, ina'an du patipun saga owak.”",
        29: "“Na,” yuk si Isa, “apuwas pa'in saga kabinasahan bay sabbutku he', ‘Angalendom mata llaw, mbal amuwan sawa mata bulan. Saga bitu'un magkapakpak na min diyata' langit, saga pandoga ma tonga'an ayan tabowa maglensa.’",
        30: "“Ma waktu ina'an, patuwa' du paltanda'an ma b'ttong langit, paltanda'an sin Anak Manusiya'. Jari magdukka kabangsa-bangsahan kamemon ma deyom dunya. Ta'nda' e' sigām in Anak Manusiya' pi'itu labay min gabun, aheya barakatna maka sanglit sahayana.",
        31: "Puwas e' pinah'lling tiyup-tiyup bo' yampa soho'na saga mala'ikatna pehē' ni mpat pidju alam animuk saga a'a bay tapene'na, min bihing langit dambila' maka dambila'.”",
        32: "“Pamintānginbi po'on kayu igira,” yuk si Isa. “Bang ta'nda'bi kayu igira itu angugbus tōng engas-engasna, sampay angandahun na to'ongan, minnē' kata'uwanbi song musim pang'llaw na.",
        33: "Damikiyanna bang ta'nda'bi paniya' na bay pamissalaku ma ka'am e', minnē' isab kata'uwanbi in kabalikku ni dunya asekot na.",
        34: "Haka'anta kam to'ongan,” yuk si Isa, “ma halam gi' magpatayan kamemon saga a'a ya allum ma buwattina'an, paniya' du pakaradja'an kamemon bay pamissalaku he'.",
        35: "Papinda du langit maka dunya, sagō' kabtanganku itu mbal to'ongan magkapinda.”",
        36: "“Halam aniya' makata'u bang sumiyan llaw maka waktu kabalikku pi'itu ni dunya. Minsan bangsa mala'ikat ma deyom sulga', mbal kinata'uwan e' sigām. Minsan aku, Anak Tuhan, mbal kata'uwanku. Luwal Mma'ku Tuhan ya makata'u.",
        37: "Bang ta'abut waktu kabalikku pi'itu, sali' du kahālanna maka kahālan bay ma masa si Nū he'.",
        38: "Saga a'a ma masa dahū lagi' min latap aheya, hal magkakanan maka maginuman. Bay sigām magh'nda-h'lla, sampay ta'abut waktu kasakat disi Nū ni diyata' adjung.",
        39: "Halam tata'u e' saga a'a inān bang ai song tum'kka ni sigām. Yampa kinata'uwan bang sigām katumbukan latap na, maka tabowa alaglag kamemon. Buwattē' isab kahālan saga a'a ma dunya itu bang aku, Anak Manusiya', pabalik na pi'itu.",
        40: "Ma waktu inān aniya' duwangan a'a maghinang ma huma, jari niā' dakayu' ati tabba dakayu'.",
        41: "Aniya' duwangan d'nda magtabang anganggiling tirigu, niā' dakayu' ati tabba dakayu'.",
        42: "“Angkan kam subay pajaga, sabab mbal kata'uwanbi bang sumiyan waktu pabalik Panghū'bi pi'itu.",
        43: "Sagō' pahati kam, bang a'a tag-dapu luma' bay ata'u bang lisag pila ya kasakat panangkaw ni luma'na, tantu du iya magjaga bo' mbal tasōd luma'na.",
        44: "Angkan kam soho'ku subay patanam sakahaba' waktu, sabab pabalik du Anak Manusiya' ma waktu mbal kata'uwanbi.”",
        45: "“Bang aniya' sosoho'an ahāp akkalna, a'a kapangandolan, ya na ina'an pinene' e' nakura'na magmandul ma saga sosoho'an kasehe'an. Iya na isab magatas-pikil ma balanja' sigām.",
        46: "Na, bang bay alikut nakura' inān bo' at'kka na pabīng, aheya kahāpan sosoho'an inān bang iya ta'abut e' nakura'na anogol ma bay pamahinang iya.",
        47: "Haka'anta kam, tantu pangandol e' nakura' inān alta'na kamemon ma sosoho'an kapangandolan e'.",
        48: "Sagō' bang sosoho'an inān bay ala'at addatna, bo' yukna ma deyom atayna in nakura'na at'ggol gi' at'kka,",
        49: "anagna' iya angala'ugan saga pagkahina sosoho'an e'. Maglami-lami iya maka saga a'a paglalango. Magkakan iya sampay maginum maka sigām.",
        50: "Sakali patagha' sadja ya t'kka nakura' inān, ma waktu halam kinata'uwan e' sosoho'an.",
        51: "Tantu iya nilagut e' nakura'na, sampay abugtang. Pinakadalan iya nalka' sali'-sali' maka saga a'a ya magbau'-bau' in addat sigām ahāp. Maina'an sigām magtangis maka magtage'ot empon sigām.”",
    },
    25: {
        1: "Magparalilan si Isa pabalik, yukna, “Buwattitu ya kapagparinta Tuhan ma waktu kabīngku pi'itu: sali' dalil sangpū' budjang bay amowa palita'an sigām pakaniya-kaniya, patanam pehē' anampang pangantin l'lla.",
        2: "Lima budjang inān sali' arupang, bo' lima inān ataha' asal akkal sigām.",
        3: "Na, in lima budjang arupang itu bay amowa palita'an sagō' halam bay amowa ns'llan maglabi pangisi ni palita'an sigām bang song ap'dda.",
        4: "Ya lima budjang taga-akkal bay amowa pangisihan ap'nno' e' ns'llan, saddī isab ya ma deyom palita'an.",
        5: "Na, pagka at'ggol t'kka pangantin l'lla, kinaru' na sigām kamemon angkan tatuli.",
        6: "“Ta'abut pa'in tonga' bahangi, aniya' angalingan yukna, ‘Ilu na pangantin l'lla. Dai' na kam anampang iya.’",
        7: "Abati' na kasangpū' budjang inān ati pinahāp e' sigām keyat palita'an sigām.",
        8: "Yuk saga budjang arupang ni budjang taga-akkal, ‘Amuwan kam kono' ns'llanbi ilu, sabab song na ap'dda palita'an kami.’",
        9: "‘Ē, mbal,’ yuk budjang taga-akkal e'. ‘Mbal maka'abut ns'llan itu ma kitam kamemon. Pehē' kam ni tinda am'llihan di-bi.’",
        10: "Na, pehē' na ni tinda saga budjang arupang inān am'lli ns'llan. Alikut pa'in sigām, magtūy at'kka pangantin l'lla. Ya lima budjang asal asakap bay ameya' ma iya pasōd ni deyom luma' pagkawinan bo' yampa tinambol lawang.",
        11: "“Mbal at'ggol at'kka budjang kasehe'an min tinda, ati angalingan ni pangantin l'lla. ‘O Tuwan,’ yuk sigām, ‘ukabin kami.’",
        12: "Sagō' anambung pangantin l'lla yuk-i, ‘Mbal ukabku, mbal kam takilāku.’",
        13: "“Na,” yuk si Isa, “subay kam pajaga to'ongan, sabab mbal kata'uwanbi bang sumiyan llaw atawa waktu kabalikku pi'itu.”",
        14: "“Buwattitu ya kapagparinta Tuhan ma waktu kabīngku pi'itu, sali' dalil dakayu' a'a magbantu atulak ni lahat saddī. Ma halam lagi' iya palanjal, pinatimuk e'na saga sosoho'anna bo' pajagahanna alta'na ma sigām.",
        15: "Ya pang'bbana ma sigām dangan maka dangan inān pinapagtongod maka akkal-kapandayanna. Dangan bay pang'bbahan limangibu pilak, dangan duwangibu pilak, maka dangan dangibu. Puwas e' atulak na a'a tag-alta' he'.",
        16: "Na, ya tendog bay pang'bbahan limangibu pilak inān, magtūy magusaha'an sīn ma iya ati makauntung iya limangibu pilak.",
        17: "Damikiyanna sosoho'an pasunu', ya bay pang'bbahan duwangibu pilak, makauntung iya duwangibu pilak isab.",
        18: "Sagō' ya sosoho'an bay pang'bbahan dangibu pilak e', pehē' angali' lowang panapukan sīn nakura'na ma deyom tana'.",
        19: "“At'ggol-t'ggol pa'in minnē' amole' na nakura' sigām. Pagt'kkana, magbista iya maka sosoho'anna.",
        20: "Ya sosoho'an bay pang'bbahan limangibu pilak e' ang'nde'an limangibu pilak bay tauntungna. Yukna ni nakura', ‘Tuwan, bay aku pang'bbahannu limangibu pilak pagpo'on. Itiya' isab limangibu pilak bay tauntungku.’",
        21: "Yuk nakura', ‘Ahāp hinangnu. Ahantap ka maka kapangandolan. Pagka ka'a ilu kapangandolan ma alta' ariki', pangandolku du isab ma ka'a alta' aheka to'ongan. Dai' ka, palamud ka ma kakoyaganku.’",
        22: "“Puwas e' pina'an isab sosoho'an pasunu', ya bay pang'bbahan duwangibu pilak e'. Yukna ni nakura', ‘Tuwan, bay pang'bbahannu aku duwangibu pilak pagpo'on. Itiya' isab untungna duwangibu pilak.’",
        23: "Yuk nakura'na, ‘Ahāp ko' hinangnu ilu. Ahantap ka maka kapangandolan. Pagka ka kapangandolan ma alta' ariki', pangandolku isab ma ka'a alta' aheka. Dai' ka, palamud ka ma kakoyaganku.’",
        24: "“Puwas e' pina'an isab sosoho'an dakayu', ya bay pang'bbahan dangibu pilak. Yukna ni nakura', ‘Tuwan, kata'uwanku asal in ka'a akuriput. Angani ka minsan ngga'i ka ka'a ya bay magsangsā' ananom. Amatimuk ka, minsan ngga'i ka ka'a ya bay maghampa'.",
        25: "Tināw aku ma ka'a, angkan bay tapukanku sīnnu ma deyom tana'. Ā! Itiya' na.’",
        26: "“Anambung nakura' inān, yukna, ‘Ala'at ka! Lisu'an sidda! Kata'uwannu bahā' in aku anguntung min ngga'i ka paglu'uganku, angā' aku buwa' isab min halam bay tanomku?",
        27: "Na, bang buwattē', arapun bay patau'nu sīnku ma deyom bangko. Jari pagt'kkaku ta'ā'ku du sīnku sampay anakna.’",
        28: "Puwas e' ah'lling nakura' ni sosoho'an saddī, yukna, ‘Ngā'unbi sīn min iya itu ati pamuwanun ni a'a dakayu', ya aniya' sīnna sangpū' ngibu pilak inān.",
        29: "Sabab sasuku kapangandolan ma aheka, kin'nnopan du ma iya sampay ni manglabi-labihan. Sagō' sasuku mbal kapangandolan minsan ma ariki', kinulangan du ai-ai bay ma iya.",
        30: "Na, ya sosoho'an halam aniya' kapūsanna itu, larukinbi iya pehē' ni deyom kalendoman. Magaluran saga a'a mahē', magtage'ot isab empon sigām.’”",
        31: "Masi amandu' si Isa, yukna, “Bang aku Anak Manusiya' pabalik pi'itu maka sanglit-sahayaku, sinehe'an du aku e' kamemon saga mala'ikat. Aningkō' isab aku ma tingkō'an sultan.",
        32: "Jari makatimuk pa'in palbangsa-bangsahan ma alopanku, papagsaddīku sigām, buwat a'a magipat hayop amapagsaddī bili-bilina maka kambingna.",
        33: "Saga a'a adil, ya sali' hantang bili-bili, pasaddīku tampal ni kowan. A'a kasehe'an, ya hantang kambing, pasaddīku tampal ni gibang.",
        34: "Jari angallam aku, ya pagsultanan sigām. Yukku ma saga a'a ma atagku tampal ni kowan, ‘Ka'am kabuwanan kahāpan e' Mma'ku, pi'itu na kam bo' kaniya'an palsuku'an ma deyom pagparintahanku, ya bay tinagamahan ka'am asal e' Tuhan sangay min waktu kapaniya' dunya itu.",
        35: "Ya na ilu panungbas ka'am. Sabab bay aku lingantu ati pakanbi aku. Bay aku patay bohe' ati painumbi aku. Bay aku a'a liyu ati pa'iddabi aku ma deyom luma'bi.",
        36: "Bay halam aniya' s'mmekku ati pas'mmekanbi aku. Bay aku asaki ati ussapbi aku. Bay aku ma deyom kalabusu ati tibawbi.’",
        37: "“Anambung du saga a'a adil inān, yuk-i, ‘Sumiyan ka bay ta'nda' kami lingantu, ati pakan kami ka, atawa patay bohe' ati painum kami ka?",
        38: "Sumiyan ka bay ta'nda' kami sali' a'a liyu, ati pa'idda kami ka ma deyom luma' kami? Sumiyan ka bay ta'nda' halam aniya' s'mmeknu, ati pas'mmekan kami ka?",
        39: "Sumiyan ka bay ta'nda' kami asaki atawa ma deyom kalabusu, ati tibaw kami ka?’",
        40: "Sambunganku du saga a'a inān, yukku, ‘Haka'anta kam to'ongan, sumiyan-sumiyan aniya' bay kahinanganbi buwattē' ma dakayu' bebeya'anku areyo' kapaga'ana ilu, aku ya kahinanganbi.’",
        41: "“Puwas e', ah'lling aku ni saga a'a kasehe'an inān, ya ma atagku tampal ni gibang. Yukku, ‘Ala'an kam min aku, saga pagmulka'an Tuhan. Pehē' kam ni api nalka', ya tinagamahan nakura' saitan maka saga tendogna.",
        42: "Ya na ina'an panungbas ka'am, sabab bay aku lingantu sagō' halam aku bay pakanbi. Bay aku patay bohe' sagō' halam aku bay painumbi.",
        43: "Bay aku a'a liyu sagō' halam aku bay pa'iddabi ma deyom luma'bi. Bay halam aniya' s'mmekku sagō' halam aku bay pas'mmekanbi. Bay aku asaki, bay aku ma deyom kalabusu, sagō' halam aku bay tibawbi.’",
        44: "“Jari anambung du saga a'a inān, yuk sigām, ‘Sumiyan ka bay ta'nda' kami lingantu, atawa patay bohe', atawa pina'an ni lahat kami sali' a'a liyu? Sumiyan ka bay ta'nda' kami halam aniya' s'mmeknu, atawa asaki, atawa ma deyom kalabusu, ati halam bay tinabang e' kami?’",
        45: "Sambunganku sigām, yukku, ‘Haka'anta kam to'ongan, sumiyan-sumiyan kam halam bay anabang ma dakayu' bebeya'anku areyo' kapaga'ana itu, sali' aku ya halam bay tabangbi.’",
        46: "Manjari saga a'a inān pinehē' du ni kabinasahan ya anatas ni kasaumulan. Sagō' in saga a'a adil pinaniya'an kalluman kakkal ni kasaumulan.”",
    },
    26: {
        1: "Aubus na e' si Isa pamandu'na kamemon, ati ah'lling iya ni saga mulidna.",
        2: "Yukna, “Asal kata'uwanbi, Hinang Paglakad na simuddai. Ya na ko' ina'an llaw pamatukbal Anak Manusiya' ni saga a'a bo' nilansang ni hāg pinapatay.”",
        3: "Manjari saga imam alanga maka saga pagmatto'ahan magtimuk pehē' ni astana' si Kayapas ya Imam Muwallam.",
        4: "Magisun sigām bang buwattingga e' sigām anaggaw si Isa ma halam aniya' makata'u, bo' supaya iya pinapatay.",
        5: "“Sagō',” yuk sigām, “da'a pasalta'ta ma pagjamu, bo' mbal ahiluhala' saga a'a kamemon.”",
        6: "Na, ina'an si Isa ma Betani, ma deyom luma' si Simun, a'a bay ni'ipul.",
        7: "Ma pagkakanan pa'in si Isa, aniya' pina'an ni iya dakayu' d'nda amowa bingki'-bingki' hinangan batu pote', isihan ns'llan pahamut landu' ahalga'. Jari binusugan e'na kōk si Isa.",
        8: "Pag'nda' saga mulid, magtūy ap'ddi' atay sigām. “Ahalga' ns'llan itu, angay pinaka'at?” yuk sigām.",
        9: "“Arapun du pa'in bay pinab'llihan ma hatusan pilak ati b'llihanna pamuwan ni saga a'a miskin.”",
        10: "Sagō' kinata'uwan e' si Isa bang ai pinagbissala e' saga mulid inān, angkan yukna, “Angay sasawbi d'nda itu? Ahāp sidda hinangna ma aku.",
        11: "Paddas na pa'in aniya' a'a miskin ma ka'am, sagō' aku itu dai'-dai' du.",
        12: "Ya angkan d'nda itu bay amu'usan ns'llan pahamut ni baranku, pangawal llaw pagkubul ma aku.",
        13: "Haka'anta kam,” yuk si Isa, “pi'ingga-pi'ingga lahat pagnasihatan lapal ahāp ma kaluha'an dunya, kinissa du pasal bay hinang d'nda itu, pangentoman ma iya.”",
        14: "Puwas pa'in ina'an, si Judas Iskariyut, dakayu' mulid si Isa min kasangpū' maka duwa, bay pehē' ni kaimaman alanga amowa sigām magbissala.",
        15: "Yukna, “Ai pamuwanbi aku bang si Isa sōnganku ni ka'am?” Ni'itungan iya t'llumpū' solag sīn dī pilak panamba iya.",
        16: 'Pagubus, amiha na si Judas waktu ahāp panōngna si Isa ni sigām.',
        17: "Na, ta'abut pa'in tagna'an llaw pangisbat Hinang Tinapay Halam Pasuligna, pehē' ni si Isa saga mulidna atilaw iya, yuk-i, “Maingga kabaya'annu panakapan kami pagjamuhannu ma Hinang Paglakad?”",
        18: "Yuk si Isa, “Aniya' dakayu' a'a ma deyom da'ira ilu, pehē' kam ni iya ati haka'inbi. Yukbi, ‘Sinō' ka nihaka'an e' guru, asekot na kono' waktu ya pangangganta' iya. Bilahi iya magjamu maka saga mulidna ma luma'nu bo' maghinang Hinang Paglakad.’”",
        19: "Na bineya' e' saga mulid inān bay panoho'an si Isa, ati sinakap e' sigām pagjamu Paglakad.",
        20: "Pagabay kohap pa'in, magtingkō'an na si Isa maka saga mulidna kasangpū' maka duwa ma pagkakanan.",
        21: "Amangan pa'in, amissala si Isa ni sigām, yukna, “B'nnal ya pah'llingku itu ma ka'am, aniya' dangan min ka'am magbantu anōngan aku ni bantaku.”",
        22: "Magtūy landu' asusa saga mulid he', ati atilaw sigām ma si Isa magsunu'-sunu', yuk-i, “Ngga'i ka bahā' aku, tuwan?”",
        23: "Yuk sambung si Isa, “Ya sehe'ku magt'nno'an tinapayna ni deyom pinggan itu, ya na iya anōngan aku.",
        24: "Aku itu, Anak Manusiya',” yuk si Isa, “amatay du buwat bay tasulat ma pasalanku. Sagō' asiya-siya du a'a anōngan Anak Manusiya' ni bantana. Ahāp lagi' a'a inān halam bay nianakan.”",
        25: "Jari ah'lling si Judas, ya song anukbalan si Isa ni bantana. “Tuwan Guru,” yukna, “aku na bahā' ya pagbissalanu ilu?” Yuk si Isa, “Aho', buwat na yuknu ilu.”",
        26: "Hinabu sigām masi amangan, niā' tinapay e' si Isa. Niamu'an e'na pagsukulan bo' yampa pinagpōng-pōng e'na, ati pamuwanna ma saga mulidna. “Sambutunbi bo' kakanunbi,” yukna, “sabab in tinapay itu baranku ko'.”",
        27: "Niā' isab e'na dakayu' sawan isihan binu-anggul, ati niamu'an isab pagsukulan bo' yampa sōnganna ni sigām. “Ka'am kamemon,” yukna, “inumunbi isi sawan itu.",
        28: "Laha'ku ko' itu, tanda' sin kapagsulutan Tuhan maka manusiya'. Song pinabu'us laha'ku ma sabab a'a aheka, pangampunan dusa sigām.",
        29: "Haka'anta kam, puwas itu mbal na aku anginum binu-anggul itu pabīng. Subay na kitam magbeya' anginum binu-anggul baha'u ma deyom pagparintahan Mma'ku bo' yampa aku makainum pabīng.”",
        30: "Aubus pa'in e' sigām angalang dakayu' kalangan pamudji Tuhan, paluwas na sigām tudju ni būd Kayu Jaitun.",
        31: "Manjari amūng si Isa ni sigām, yukna, “Sangom itu alahi du kam kamemon ang'bba min aku, buwat tasulat ma Kitab Kanabi-nabihan, ya yuk-i, ‘Bono'ku,’ yuk Tuhan, ‘a'a angupiksa' bili-bili, ati akaukanat saga bili-bili bay daumpigan.’",
        32: "Sagō' bang aku tapakallum na pabīng min kamatayku, parahū aku min ka'am tudju ni lahat Jalil.”",
        33: "Ah'lling si Petros ni si Isa, yukna, “Mbal ka bbahanku minsan ka ni'bbahan e' kasehe'an.”",
        34: "Yuk si Isa ni iya, “Haka'anta ka to'ongan. Ma sangom itu, ma halam gi' angukku'uk manuk, amalilu du ka min t'llu in aku mbal takilānu.”",
        35: "Yuk sambung si Petros, “Minsan aku paunung amatay ma ka'a, mbal du ka paliluhanku.” Buwattē' du isab pah'lling saga mulid kasehe'an.",
        36: "Manjari palanjal na disi Isa ni kabbun niōnan Getsemane. Yuk si Isa ni saga mulidna, “Maitu kam aningkō'. Pina'an lagi' aku anabbut Tuhan.”",
        37: "Ya binowa e' si Isa panehe', si Petros maka duwangan anak si Sibidi. Sakali magkasusahan si Isa, magk'bba-k'bba deyom atayna.",
        38: "Yukna ni t'llungan mulidna he', “Aku itu agon-agon magkamamatay ma sabab kasusahan itu. Angagad kam maitu, sehe'inbi aku magjaga.”",
        39: "Makalawak-lawak pa'in iya min sigām, kum'ppang iya ni tana' maka e'na anabbut ni Tuhan. Yukna, “Arōy, Mma'! Bang makajari, la'anin lagi' min aku sawan kabinasahan itu. Sagō' ngga'i ka kabaya'anku subay nirūlan, bang pa'in min kabaya'annu du.”",
        40: "Puwas e' pabīng si Isa ni sehe'na kat'llungan, bo' tabākna sigām magtulihan. Yukna ni si Petros, “Angay kam mbal makatatas magjaga maka aku minsan la'a hal danjām?",
        41: "Pajaga kam, angamu' kam tabang ni Tuhan bo' kam mbal tabowa-bowa e' sasat. Lilla' asal deyom ataybi sagō' abuhat pamarananbi.”",
        42: "Sakali pehē' si Isa ni baina angamu'-ngamu' ni Tuhan pabīng. Yukna, “O Mma', bang mbal kala'anan kabinasahan itu, luwal bang kalabayanku, na, ka'a du iya abeya'.”",
        43: "Makabalik pa'in iya ni disi Petros, tabākna na isab sigām magtulihan pabīng sabab kinaru' sidda.",
        44: "Manjari pehē' si Isa ni baina angamu'-ngamu' ni Tuhan pabīng buwat bay dahū, kamint'lluna na.",
        45: "Puwas e' pabalik iya ni mulidna kat'llungan. Yukna, “Oy, atuli gi' kam? Pahali-hali gi' kam? Nda'unbi ba, ta'abut na waktuku. Aku, Anak Manusiya' itu, arai' na tinukbalan ni pang'ntanan saga a'a ala'at.",
        46: "Pabungkal kam. Sūng kitam, sabab ilu na a'a ya anōngan aku ni sigām.”",
        47: "Na, hinabu lagi' si Isa ah'lling ni saga mulidna, magtūy at'kka pina'an si Judas, dakayu' mulid si Isa min kasangpū' maka duwa he'. Aheka a'a magbeya' maka iya magpamowa takos maka saga kakakal. Bay sigām sinō' pina'an e' saga kaimaman alanga maka e' saga pagmatto'ahan.",
        48: "Bay sigām asal kabuwanan pandoga e' si Judas bo' aniya' pangilāhan sigām ma si Isa. Ya pamissalana ma sigām, “In a'a siyumku, ya na he' saggawunbi.”",
        49: "Pagt'kka si Judas pina'an magtūy iya pa'abut ni si Isa magaddat ma iya, yukna, “Salam, Tuwan Guru,” ati siyumna si Isa.",
        50: "“Bagay,” yuk si Isa ni iya, “lanjalin hinangnu.” Sakali pasekot ni si Isa saga a'a inān anaggaw iya, amalutan iya pahogot.",
        51: "Sagō' aniya' sehe' si Isa dakayu' bay angahurusan pakokosna. Nilagut e' a'a itu dakayu' sosoho'an Imam Muwallam, autas magtūy dambila' taingana.",
        52: "Yuk si Isa, “Pabalikun takosnu ni tagubanna ilu, sabab sasuku amowa kalis pamapatay a'a, amatay du isab iya e' kalis.",
        53: "Halam bahā' kata'uwanbi, bang aku angamu' tabang ni Mma'ku nirūlan sadja aku? Pinabeya'an du aku mala'ikatna ma ibuhan.",
        54: "Sagō' bang aku ganta' angamu' tabang, mbal magmaksud ya bay tasulat ma deyom Kitab, ya yukna in saga pakaradja'an itu subay pat'kka buwattitu.”",
        55: "Manjari ah'lling si Isa ni ba'anan a'a inān, yukna, “Pangannalbi bahā' in aku itu mundu, ya po'on kam subay amowa takos maka kakakal panaggawbi aku? Llaw-llaw na pa'in aku bay mahē' aningkō' amandu' ma deyom langgal pagkulbanan, sagō' halam aku saggawbi.",
        56: "Patut bang saga pakaradja'an itu kamemon pinat'kkahan aku bo' supaya aniya' kamaksuran ma bay tasulat e' kanabi-nabihan ma deyom Kitab.” Magtūy maglahian saga mulid si Isa kamemon. Jari pinasagaran na iya.",
        57: "Manjari binowa si Isa e' a'a bay anaggaw iya pina'an ni luma' si Kayapas ya Imam Muwallam. Ina'an magtimuk saga guru sara' agama maka pagmatto'ahan.",
        58: "Si Petros bay paturul ma si Isa sagō' min katahan. Paturul iya sampay pasōd na ni deyom halaman luma' Imam Muwallam. Ma deyom pa'in, magtingkō'an iya maka saga jaga imam bang pa'in ta'nda'na bang ai kamattihan si Isa.",
        59: "Saga kaimaman alanga maka saga a'a ma Tumpukan Maghuhukum inān amiha sababan panuntut sigām ma si Isa, minsan ngga'i ka b'nnal, bang pa'in aniya' pagsababan pamapatay sigām ma iya.",
        60: "Saguwā' minsan aheka a'a bay anaksi' puting pasal si Isa, halam aniya' pagsababan b'nnal tabāk sigām. Ma katapusanna, aniya' duwangan a'a pa'alop ma palhimpunan ah'lling,",
        61: "yuk sigā, “Bay takale kami a'a itu ah'lling in iya angalubu langgal pagkulbanan, ati ma deyom t'llung'llaw kono' tapat'nggena pabalik.”",
        62: "Manjari an'ngge Imam Muwallam amissala ma si Isa, yukna, “Ka'a ilu, halam bahā' aniya' da'awanu ma panuntut ka'a itu?”",
        63: "Sagō' halam anambung si Isa. Amissala pabīng Imam Muwallam, yukna, “Pasapata ka ma ōn Tuhan ya kakkal salama-lama. Haka'in kami to'ongan bang ka'a Al-Masi, Anak Tuhan.”",
        64: "“Aho',” yuk si Isa, “ya na yuknu. Sagō' haka'anta kam, mbal du at'ggol ta'nda'bi du Anak Manusiya' aningkō' ma bihing Tuhan Sangat Kawasa, tampal ni kowan. Maka ta'nda'bi du iya pi'itu ameya' ma gabun min deyom sulga'.”",
        65: "Manjari ginese' e' Imam Muwallam pakayanna, kabowa astolna. Yukna, “A'a itu amah'lling pangkal ni Tuhan! Da'a na kitam amiha saksi' saddī! Takalebi na llingna pangkal!",
        66: "Ai pangahukumbi?” Yuk sambung sigām, “Subay iya pinat'nna'an hukuman ni kamatay.”",
        67: "Puwas e' niludja'an si Isa e' sigām ma baihu'na, maka pinagtibu'. Aniya' isab sigām bay anampak iya,",
        68: "maka e' sigām ah'lling, yuk-i, “Bang ka'a Al-Masi, tokorun bang sai ya bay anampak ka'a!”",
        69: "Manjari ina'an si Petros aningkō' ma halaman luma' he'. Aniya' pehē' ni iya dakayu' d'nda, ipatan Imam Muwallam. Yuk d'nda itu ni iya, “Ka'a ilu, bay sa ka ameya' ma si Isa, ya a'a Jalil inān.”",
        70: "Sagō' amalilu si Petros ma alopan a'a inān kamemon. “Mbal kata'uwanku,” yukna, “bang ai ya pah'llingnu ilu.”",
        71: "Puwas e' pehē' iya tudju ni bowa' lawang, ati aniya' ipatan d'nda saddī bay maka'nda' iya. Pag'nda' d'nda itu ma si Petros, yukna ni saga a'a maina'an, “A'a itu bay ameya' ma si Isa, a'a Nasaret inān.”",
        72: "Magtūy amalilu si Petros pabīng maka anapahan iya di-na. “Mbal kata'uwanku a'a inān!” yukna.",
        73: "Mbal at'ggol, pina'an ni si Petros saga a'a ya asal magt'nggehan maina'an. Yuk sigām, “Kata'uwan kami in ka'a b'nnal bay sehe' disi Isa sabab tapangli'ta ka ma bissalanu.”",
        74: "Minnē' magbalik-balik si Petros anapahan di-na. Ya pah'llingna, “Mbal takilāku a'a inān!” Saru'un-du'un du angukku'uk manuk,",
        75: "ati taentom e' si Petros bay lling si Isa ma iya, ya bay yukna, “Ma mbal gi' angukku'uk manuk sangom itu, amalilu du ka min t'llu in aku mbal kata'uwannu.” Magtūy paluwas si Petros minnē'. Anangis iya maka he'na magdukka to'ongan.",
    },
    27: {
        1: "Ta'abut pa'in pagk'llat llaw, maggara' kaimaman alanga kamemon maka saga pagmatto'ahan bangsa Yahudi bang buwattingga pamapatay sigām ma si Isa.",
        2: "Manjari kinarenahan si Isa bo' yampa tin'kkahan ni si Pilatu, gubnul bangsa Rōm.",
        3: "Pagta'u si Judas, in si Isa pinat'nna'an hukuman na ni kamatay, magtūy iya magsusun ma bay hinangna anukbalan iya ni bantana. Jari pehē' iya ni kaimaman alanga maka ni pagmatto'ahan, arak ang'nde' sīn bay panamba iya, t'llumpū' solag sīn Yahudi, dī pilak.",
        4: "Yukna ma sigām, “Aheya dusaku sabab katukbalanku a'a halam taga-dusa, maka itiya' iya arai' na pinapatay.” “Min ka'a ko' ilu,” yuk sigām. “Ngga'i ka min kami.”",
        5: "Sakali nihantakan sīn inān e' si Judas ni lantay langgal bo' yampa paluwas minnē' maggantung di-na bo' amatay.",
        6: "Manjari kaimaman inān amuwa' sīn bay nihantakan e' si Judas e'. Yuk sigām, “Sīn itu haram bang ma agamata sabab bay tambahan pamapatay a'a. Mbal manjari pinatimbul ni sīn langgal.”",
        7: "Arakayu' pa'in paggara' sigām pasal sīn inān, bo' wa'i tapam'lli tana' min a'a magtatampa, ati ginuna pangubulan saga a'a liyu.",
        8: "Angkan tana' inān niōnan, ‘Tana' tambahan laha'’ sampay ni kabuwattituhan.",
        9: "Na, ma sabab hinang inān, aniya' kamaksuranna ma bay tasulat e' nabi Irimiya, ya yukna, “Niā' e' sigām t'llumpū' solag sīn dī pilak ya halga' baran a'a bang ma bangsa Isra'il,",
        10: "ati ginuna pam'lli tana' min a'a magtatampa. Ya na he' bay panoho'an aku e' Tuhan.”",
        11: "Manjari ina'an si Isa an'ngge ma dahuan gubnul Pilatu, sinumariya e'na. “Na,” yuk gubnul, “sultan ka bahā' ma bangsa Yahudi?” Anambung si Isa, yukna, “Ya na yuknu ilu.”",
        12: "Sagō' halam bay sambunganna saga tuntut bay panuntut iya e' kaimaman alanga maka pagmatto'ahan.",
        13: "Ah'lling si Pilatu ni iya, yukna, “Halam bahā' takalenu panuntut saga a'a itu ma ka'a?”",
        14: "Sagō' halam anambung si Isa minsan dakabtang, angkan ainu-inu to'ongan gubnul e'.",
        15: "Na, kahaba' tahun, ma waktu paghinang bangsa Yahudi ma Hinang Paglakad, ya kabiyaksahan gubnul subay aniya' dakayu' pilisu pinaluwas, sai-sai pinene' e' saga Yahudi.",
        16: "Ma waktu ina'an aniya' dakayu' pilisu babantugun, ōnna si Barabbas.",
        17: "Manjari, makapagtimuk pa'in pina'an kaheka'an a'a, tinilaw sigām e' si Pilatu. “Sai kabaya'anbi,” yukna, “subay paluwasku? Si Barabbas atawa si Isa, ya niōnan Al-Masi itu?”",
        18: "Malaingkan kinata'uwan e' gubnul bang ai sababanna angkan si Isa bay tin'kkahan ni iya. Tu'ud sigām angihid ma si Isa.",
        19: "Aningkō' pa'in si Pilatu ma lugal paghukuman, aniya' lapal pinabeya' ni iya e' h'ndana. Yuk lapal, “Da'a ka palamud ni hukuman a'a a'adil ilu. Sabab aniya' tauppiku dibuhi' pasalanna, sidda aku bay maglimpa-limpa.”",
        20: "Manjari ba'anan a'a inān bay tapogos e' kaimaman alanga maka e' pagmatto'ahan subay angamu' pinaluwas si Barabbas, bo' si Isa ya sinō' pinapatay.",
        21: "Sagō' tinilaw sigām pabīng e' gubnul e'. “Sai ma deyom duwangan pilisu itu,” yukna, “subay paluwasku?” “Si Barabbas,” yuk sigām.",
        22: "Atilaw si Pilatu ma sigām, yukna, “Inayku bahā' si Isa itu, ya niōnan Al-Masi?” “Lansangun iya ni hāg,” yuk sigām kamemon.",
        23: "Sagō' atilaw gi' si Pilatu. Yukna, “Ai bay hinangna ala'at?” Luhūy pakosog pangolang saga a'a he', yuk-i, “Lansangun iya ni hāg!”",
        24: "Pagta'u si Pilatu in katimukan a'a inān mbal pahawid maka arai' na aheya kahiluhala'an, magtūy iya angā' bohe' bo' yampa kose'anna tanganna ma dahuan sigām, paltanda'an in iya papuwas min palkala' he'. Yukna ni sigām, “Bang pa'in ngga'i ka min aku bang a'a itu pinapatay. Min kahinanganbi na.”",
        25: "Anambung saga a'a inān kamemon, yuk-i, “Akuhan kami kamatayna, minsan kami kapellengan sampay ni magsuring-magsaingsing.”",
        26: "Sakali si Barabbas ya pinaluwas e' si Pilatu tudju ni ba'anan a'a he'. Sagō' si Isa pinaraplosan e'na ma saga sundalu. Pagubus, sinōngan iya ni saga a'a ya angalansang iya ni hāg.",
        27: "Manjari binowa si Isa e' saga sundalu gubnul pehē' ni deyom astana', ati tinimuk iya he' damba'an sundalu.",
        28: "Nila'anan e' sigām s'mmekna bo' pamajuba ma iya manta keyat sali' hantang sultan.",
        29: "Nilangbid isab bahan itingan e' sigām, nihinang sali' panumping sultan pinat'nna' ni kōkna. Puwas e' pina'ntanan iya tungkud ma tanganna kowan, bo' yampa sigām angōk-tu'ut ni dahuanna magtunggīng iya, yuk-i, “Mahaldika'! Mahaldika'! Sultan Yahudi!”",
        30: "Pinagludja'an iya e' sigām, niā' e' sigām tungkud bay ma tanganna bo' pam'ppok kōkna.",
        31: "Na, aubus pa'in kapagtunggīng sigām ma iya, magtūy niurusan manta bay pajubana inān ati pinas'mmekan iya maka bay s'mmekna tagna'. Puwas e' binowa iya paluwas minnē' bo' nilansang ni hāg pamapatayan iya.",
        32: "Salta' pa'in sigām paluwas min da'ira inān, aniya' talanggal sigām l'lla min lahat Kirini, ōnna si Simun. Minandahan iya e' saga sundalu, sinō' ananggung hāg si Isa.",
        33: "Pagt'kka pa'in sigām ni jadjahan lahat niōnan Golgota, hatina lahat ‘Peya'-peya' Kōk’,",
        34: "arak pamainum sigām ma si Isa binu-anggul kalamuran tambal apa'it. Sagō' pag'ssana, mbal iya anginum.",
        35: "Aubus pa'in e' saga sundalu bay angalansang si Isa ni hāg sampay amat'ngge hāgna, maglegot na sigām bo' pinagtokoran e' sigām s'mmekna bang sai kat'nna'anna.",
        36: "Puwas e' aningkō' sigām maina'an anganjaga.",
        37: "Aniya' sulat panuntut bay pinat'nna' e' sigām ma hāg min diyata' kōk si Isa. Yuk sulat e', ‘SI ISA, SULTAN BANGSA YAHUDI.’",
        38: "Aniya' isab duwangan mundu pinasambeya' ma si Isa. Nilansang sigām ma hāg, dakayu' ma bihing si Isa tampal ni kowan, dakayu' tampal ni gibang.",
        39: "Na, pinagudju' na pa'in si Isa e' a'a maglaulabay, pinaghanduk-handukan.",
        40: "“Allā,” yuk sigām, “ka'a iya angalangkat langgal pagkulbanan inān, ati pabangunnu kono' pabīng ma deyom t'llung'llaw! Angalappasan ka di-nu bang ka b'nnal Anak Tuhan. Pareyo' ka min hāg ilu!”",
        41: "Ya du magpangudju' saga imam alanga maka saga guru sara' agama maka saga pagmatto'ahan.",
        42: "“A'a itu,” yuk sigām, “ata'u angalappas ma a'a saddī sagō' mbal makalappas di-na. Sultan bangsa Isra'il kono' iya! Bang iya ganta' makapareyo'an di-na min hāg, am'nnal kitam ma iya!",
        43: "Angandol iya ma Tuhan, maka in iya kono' Anak Tuhan. Nda'ta kono' bang Tuhan bilahi angalappas iya!”",
        44: "Ya du duwangan mundu bay nilansang pinasambeya' ma si Isa, ameya'-meya' isab angudju' iya.",
        45: "Na, augtu pa'in llaw, taluwa' lendom kaluha'an lahat e' sampay ni lisag t'llu kohap.",
        46: "Paglisag t'llu saga, akosog e' si Isa angalingan, yukna, “Eli, Eli, lama sabaktani?” Hatina, “Tuhanku, O Tuhanku, angay aku pasagarannu?”",
        47: "Pagkale itu e' saga a'a magt'nggehan maina'an, yuk sigām kasehe', “Angalinganan iya nabi Elija.”",
        48: "Magtūy aniya' dakayu' a'a parai'-dai' ang'ggoman l'ppus ni deyom binu al'ssom bo' yampa pasagnatna ni tōng kayu-kayu. Arak pamainumna ma si Isa.",
        49: "Sagō' magin'mbal saga a'a kasehe', yuk-i, “Sagarinbi iya. Nda'ta lagi' bang patuwa' nabi Elija angalappas iya.”",
        50: "Sakali angolang si Isa pabalik, magtūy ab'kkat napasna.",
        51: "Saru'un-du'un du ya kultina bay pangagpang ma deyom langgal pagkulbanan inān agese' duwa min diyata'na tudju pareyo'. Ajogjog deyom dunya, maka magkabila' saga batu lakit.",
        52: "Aniya' isab kakubulan aukab maka aheka saga a'a suku' Tuhan bay pabungkal, allum pabīng min kamatay sigām.",
        53: "Magluwasan sigām min deyom kubul, jari allum pa'in si Isa pabīng, pasōd sigām ni Awrusalam, ya da'ira Mahasussi. Aheka a'a isab bay maka'nda' sigām.",
        54: "Tananam pa'in linug maka pakaradja'an inān kamemon e' kapitan maka saga sundaluna ya bay anganjaga ma kamatay si Isa, magtūy sigām sidda sinōd tāw. Yuk sigām, “B'nnal a'a itu Anak Tuhan!”",
        55: "Aheka isab saga d'nda bay maina'an ang'nda' min katahan. Sigām ya bay ameya' paumpig ma si Isa angussap iya, tinagna'an ma lahat Jalil lagi'.",
        56: "Ina'an si Mariyam min Magdala, si Mariyam ina' si Yakub maka si Yusup, maka h'nda si Sibidi.",
        57: "Pagabay kohap na, aniya' at'kka pina'an dakayu' a'a dayahan, a'a min lahat Arimati. Ōnna si Yusup.",
        58: "Na pehē' si Yusup itu pa'alop ni si Pilatu angamu' mayat si Isa. Jari magpanoho'an si Pilatu inān ni saga sundaluna, sinō' ni'nde'an mayat si Isa ni si Yusup.",
        59: "Ta'ā' pa'in mayat, sinaput e' si Yusup maka kakana' baha'u",
        60: "bo' yampa palegena ma kubul bay tagamahanna di-na, kubul baha'u bay kinehe'an ma deyom batu lakit. Puwas e' ginulungan e'na batu aheya panaplok bowa' lowang e' bo' yampa iya ala'an minna'an.",
        61: "Maina'an asal si Mariyam a'a Magdala, maka Mariyam isayna, aningkō' ma dahuan kubul inān.",
        62: "Pagk'llat llaw dakayu', hatina llaw Sabtu', patimuk ni si Pilatu saga kaimaman alanga maka saga Parisi.",
        63: "Yuk sigām ni iya, “Tuwan, taentom kami ya bay lling a'a putingan inān ma waktu kallumna lagi'. Yukna bang ta'abut t'llung'llaw min kamatayna in iya allum du pabīng.",
        64: "Angkan kubulna inān subay soho'nu nijagahan sakuli-kuli sampay ta'abut kat'llung'llawna. Kalu pehē' saga mulidna anangkaw mayatna bo' angahaka ni kasehe'an in iya allum pabīng min kamatayna. Bang ganta' buwattē' akalap lagi' puting sigām damuli min bay dahū.”",
        65: "“Na,” yuk si Pilatu. “Bowahunbi sundalu pehē' ni kubul bo' pajagahunbi sakuli-kuli.”",
        66: "Manjari magla'anan na sigām minnē'. Aniya' gindan pinikit e' sigām ni taplok batu bo' kinata'uwan bang aniya' bay angukab iya. Sinō' isab saga sundalu anganjaga maina'an.",
    },
    28: {
        1: "Pagka palabay na llaw Sabtu', bo' pagk'llat llaw Ahad, ina'an si Mariyam a'a Magdala maka dakayu' isayna pehē' ang'nda' kubul si Isa.",
        2: "Saru'un-du'un ajogjog lahat e' linug akosog. Aniya' dakayu' mala'ikat min Tuhan bay pareyo' min sulga' anganggulungan taplok batu min lowang kubul bo' yampa aningkō' ma diyata' batu he'.",
        3: "Asahaya pangluwahan mala'ikat inān buwat sawa lāt, maka s'mmekna apote' to'ongan.",
        4: "Saga sundalu anganjaga inān bay sinōd tāw angkan magpamidpid. Sali' sigām a'a amatay, halam makasayu.",
        5: "Manjari amissala mala'ikat ni duwangan d'nda he'. “Da'a kam tināw,” yukna. “Kata'uwanku in ka'am amiha si Isa, ya bay pinapatay ma hāg.",
        6: "Halam na iya maitu sabab allum na pabīng, buwat bay llingna. Pi'itu kam ang'nda' ni bay palegehanna.",
        7: "Puwas e', pasa'ut kam pehē' ni saga mulidna amowahan sigām haka in iya pinakallum min kamatayna. Parahū du iya min sigām ni lahat Jalil, ati maina'an sigām ang'nda' iya. Entomunbi bay pangahakaku itu ma ka'am.”",
        8: "Magtūy sakadjap sadja sigām ala'an min kubul. Tināw sigām dambila', kinōgan isab dambila'. Paragan sigām pehē' angahaka ni saga mulid si Isa.",
        9: "Ma labayan pa'in, saru'un-du'un du patuwa' si Isa amāk sigām. “Ka'am sa ilu,” yukna. Pa'abut sigām ni iya amalutan tape'na maka e' sigām amudji iya.",
        10: "Yuk si Isa, “Da'a kam tināw. Pehē' na kam angahaka'an saga danakanku inān in sigām subay pehē' ni lahat Jalil. Mahē' sigām ang'nda' aku.”",
        11: "Sabu pa'in duwangan d'nda inān palanjal ni pal'ngnganan sigām, aniya' pabalik ni deyom da'ira saga sundalu kasehe' bay anganjagahan kubul. Kahaka'an e' sigām kaimaman alanga pasal bay pakaradja'an ma pagkubulan e'.",
        12: "Manjari magtimuk kaimaman maka saga pagmatto'ahan maggara'. Ya paggara' sigām in saga sundalu inān subay binuwanan sīn aheka.",
        13: "Yuk saga imam e', “Haka'inbi saga a'a in kamuliran si Isa bay pehē' waktu sangom anangkaw mayatna hinabubi bay atuli.",
        14: "Sagō' da'a kam asusa bang itu ganta' tata'u e' gubnul. Binissalahan iya pahāp bo' supaya kam mbal pinagamahan.”",
        15: "Manjari niā' sīn inān e' saga sundalu ati pangahaka e' sigām buwat bay panoho'an kaimaman e'. Sampay ni kabuwattituhan ya na he' hunub-hunub pinasaplag ma deyom bangsa Yahudi, hatina in mayat si Isa bay tinangkaw e' saga mulidna.",
        16: "Manjari in kasangpū' maka dda mulid si Isa wa'i ni lahat Jalil, patukad ni būd ya bay pangahaka si Isa ma sigām.",
        17: "Pag'nda' sigām ma si Isa, magtūy sigām amudji iya, sagō' aniya' sigām kasehe'an magduwa-ruwa ma deyom atay sigām bang ina'an-i b'nnal si Isa.",
        18: "Pasekot si Isa ni sigām, yukna, “Bay na aku kabuwanan kawasa magbaya' ma dunya sampay ma sulga'.",
        19: "Angkan kam soho'ku pehē' ni sabarang bangsa bo' sigām bowahunbi pamulid ma aku. Pandihunbi sigām min ōn Tuhan Mma', maka min ōn Anak, maka min ōn Rū Sussi.",
        20: "Pandu'inbi sigām subay ameya' ma kamemon bay panoho'anku ka'am. Maka itu entomunbi pahāp, pagapi' du aku ma ka'am sampay niabutan masa.” Tammat",
    },
}
